window.POEM_DB=window.POEM_DB||{};POEM_DB["ming_042"]={"n":"王恭","dyn":"明","poems":[{"t":"春雁","f":"七言绝句","c":["春风一夜别衡阳，楚水燕山万里长。","莫怪春来便归去，江南虽好是他乡。"]},{"t":"塞下曲二首 其二","f":"五言律诗","c":["登埤望烽火，落日烟尘紫。","百战久不归，空闺泪如水。","汉兵十万馀，尽没长城死。","城下有精灵，啾啾月明里。"]},{"t":"舟次镡津","f":"五言律诗","c":["木落川气凉，鸿飞水容夕。","微灯射远沙，夜榜邻幽石。","月色凄处寒，霜花坐来白。","遥见九华峰，苍苍但萝薜。"]},{"t":"初秋同叔韬彦时游崇山兰若","f":"五言古诗","c":["习静厌纷扰，幽寻给孤园。","翛然香林下，似得桃花源。","一鸟落天镜，千花秀禅门。","纷吾道机浅，谬接甘露言。","月色隐秋思，荷香清夜魂。","终希偶缁锡，永矣超尘喧。"]},{"t":"虚白子水墨图为陈思孝题","f":"五言古诗","c":["开图见嵩山，妙趣忽已领。","濛濛花源阴，窈窕多灵境。","石洞閟苔纹，天窗逗云影。","迎秋鹖冠凉，先雪荷衣冷。","长夜何所闻，龙鸣在西顶。"]},{"t":"题画二首 其二","f":"五言古诗","c":["鹖冠饭雕胡，分与时人浅。","道存心自玄，岂必泉萝远。","绿水净鸣琴，空林对虚馆。","山中春桂枝，倏尔飞霜满。","寄语青云人，投簪事应晚。"]},{"t":"偶书醉樵扇头","f":"五言律诗","c":["幽谷夜来雨，遥岑积鲜云。","山光与潭影，清辉并在君。","佳期发琴兴，念尔鸾鹤群。","何为解萝薜，怅然坐离分。"]},{"t":"梅城小景","f":"五言古诗","c":["沧江湛回流，荒城出花屿。","海色明远洲，岚光过新雨。","渔家孤笛秋，烟火疏林暮。","漠漠天际帆，苍苍鸟边树。","若人静者流，持竿得真趣。","取乐非取鱼，日斜忘归去。"]},{"t":"书香山九老图","f":"七言古诗","c":["唐家名臣白居易，暮年脱略青云器。","抗节羞趋当路门，拂衣起谢人间事。","以兹疏散爱香山，洛下群公亦遂閒。","玉堂金马俱残梦，流水孤云同去还。","石楼烟树朦胧见，八节回滩泻秋练。","云衣落落古松姿，鹤发皤皤冻梨面。","人生宦达应如此，岂必浮名絓青史。","楚国三生少见机，竹林七子徒为尔。","名遂身閒古所稀，洛阳山水又清晖。","青山何处无佳赏，白首湮沈空布衣。"]},{"t":"赋易水送人使燕","f":"七言古诗","c":["燕山北起高峨峨，东流易水无停波。","北风萧萧筑声切，昔人于此送荆轲。","图中匕首非良计，堪叹燕丹无远器。","髑髅空死樊将军，日暮秦兵满燕市。","往事空馀易水寒，白翎飞下地椒乾。","经过此地对流水，知尔踟蹰马上看。"]},{"t":"筝人劝酒","f":"七言古诗","c":["新丰美人青楼姬，绛裙素腕娇双眉。","暂歇秦筝劝郎酒，西凉葡萄金屈卮。","郎君但饮休辞醉，百年悠悠梦中是。","神血朝凝不复知，日暮青山北邙里。","回身更整十三弦，金雁离离绕钿蝉。","十二栏杆月将坠，锦筵红烛浮青烟。","人生欢乐那能久，岂悟星躔倏奔走。","妾容未改君少年，日日尊前劝君酒。"]},{"t":"望秋月","f":"古风","c":["望秋月，在家见月如等閒。","几度天涯望秋月，明月虽同非故山。","举头问明月，古往今来几圆缺。","明月如有言，问我少年今白发。","君不见汾水秋风鸿雁来，邺中歌舞尽苍苔。","忧欢只问今时月，曾照离宫与露台。","今月应将古月同，古人今在九泉中。","谁言金粟西陵下，不见流光到梓宫。"]},{"t":"妾薄命","f":"七言古诗","c":["玉钗堕地无全股，双凤蟠龙两飞去。","虽藏匣底终弃捐，欲卖傍人不直钱。","辘轳宛转黄金井，手挽铜瓶系纤绠。","谁知绠断瓶堕泉，千尺深沈不窥影。","铜瓶堕泉钗堕地，君心何得生离异。"]},{"t":"去妇词","f":"古风","c":["刺促何刺促，东家迎鸾西家哭。","哭声休使东家闻，东家新妇嫁郎君。","满堂笑语看珠翠，夹道风传兰麝薰。","浮云上天花落树，君心一失无回悟。","明知遣妾何所归，饮泪行寻出门路。","青铜镜面无光采，苦心尚在容华改。","东家新妇倾城姿，似妾从前初嫁时。"]},{"t":"三山朱孔周南楼伟观","f":"古风","c":["飞楼轶浮埃，迥绕三峰翠。","楼中十二曲栏干，下瞰苍苍但鳞次。","七闽重镇旧繁华，九陌三衢十万家。","连营国步军容盛，法宇仙台鸟道斜。","遥天塔影回孤雁，何限清晖卷虚幔。","洗马濠头过雨香，钓鲈矶下春潮满。","白云飞上越王山，忆昔豪华午梦间。","城池百战今谁在，草色千门几度閒。","玉章绘衮分秦土，雕弓白马空陵树。","霸气荣光共渺然，屠龙射鳄知何处。","登临怀古兴悠悠，酌酒弹弦醉不休。","博陵才子能高咏，灵武词人解唱酬。","门外金羁多上客，独怜王粲未销忧。"]},{"t":"鸡公垄","f":"古风","c":["荒岗古墓鸡垄边，蔓草离离生野烟。","狐狸养子隐荆棘，乌鸢作巢衔纸钱。","石麟埋沈土花湿，雕砖剥落樵人拾。","天阴燹火暗复明，月下精灵语还泣。","此坟未必无子孙，夙昔传闻皆宦门。","浮荣一去不复盛，空馀古木啼清猿。","谁家新冢高数尺，又买西家坟头石。","忆过秦中北邙路，丧车辚辚冢无数。","黄金买山葬死灰，昨日官军斫坟树。","崩茔断圹碎苔痕，髑髅无声眠草根。","生前意气动山岳，身后凄凉邈九原。","君不见羊公岘首石已刻，季子延陵碑尚存。","锦袍醉倒长安市，谁招?石江心魂。","岂知百年后，身世两俱没，贵贱终同草上尘。","升沈且进杯中物，笑矣乎，悲矣乎，眼中之人今有无。"]},{"t":"闻笛歌送人之塞上","f":"古风","c":["横笛对离亭，扁舟越江口。","月下何人最断肠，天涯怨别吹《杨柳》。","《杨柳》繁音愁复愁，梧桐萧瑟江枫秋。","长林半夜叶皆脱，积水三江云不流。","长夜漫漫听未了，变羽回宫犹袅袅。","越海天边鸟不飞，闽关月暗猿声小。","须臾一曲更凄清，零落梅花满楚城。","楚城迢迢接沙碛，边客闻之泪俱滴。","黄埃积雪暗长关，绝域穷荒草根白。","此夜愁心独对君，明朝怅别又离群。","单于城上吹羌管，知尔相思不忍闻。"]},{"t":"送张少府朝觐","f":"七言古诗","c":["闽州少尹家何处，梦里青山溧阳树。","讼庭无事独哦松，走马金陵看花去。","青绳御路连青天，五陵侠少黄金鞭。","红桥青幔多买醉，少尹囊中无酒钱。","朝回道过乡山口，春风又发秦淮柳。","溧水芹边二校文，相逢为问平安否。"]},{"t":"夏夜曲","f":"五言律诗","c":["初月照回廊，鸣珰出洞房。","竹清残暑气，荷汎小池香。","雪腕宫罗润，云鬟夜玉凉。","庭前有梧叶，早晚落银床。"]},{"t":"梅江送林中州归龙塘","f":"五言律诗","c":["清时尚不官，道在任家寒。","夜梦梅花帐，朝吟苜蓿盘。","鱼风吹鬓冷，蚌月照衣残。","归去乡林下，横塘竹万竿。"]},{"t":"寒村隐者","f":"五言律诗","c":["谷口微霜度，寒村独见君。","西风见萧瑟，落叶不堪闻。","古路无行客，闲门有白云。","为怜幽处好，不忍更轻分。"]},{"t":"梅江送林泽中归屿南","f":"五言律诗","c":["卖药偏成隐，相逢但布衣。","梅江秋外别，花屿雨中归。","远火千峰夕，遥钟独雁飞。","自言今白首，此去故人稀。"]},{"t":"客中见新燕","f":"五言律诗","c":["可怜江上燕，几日到乌衣。","欲向谁家去，多应旧主非。","落花深巷小，乔木画梁稀。","自笑天涯别，秋风想未归。"]},{"t":"寒夜宿张藻宅偶赋","f":"五言律诗","c":["旅人眠不安，抱剑夜中弹。","月映花林白，霜凄画壁寒。","澹云孤梦远，流水半生残。","想是平原馆，萋萋草正繁。"]},{"t":"梅江送林中州归","f":"五言律诗","c":["不羡鱼羹饭，宁甘苜蓿香。","小斋邻蟹舍，曲几近蛟房。","别路分沙堰，行衣受海霜。","到家看旧竹，凉月满横塘。"]},{"t":"九日","f":"五言律诗","c":["落叶满秋山，亲朋杳霭间。","江村多雨外，世难几人还。","白发偏能长，黄花好是閒。","聊将一杯酒，暂尔解离颜。"]},{"t":"吴城怀古","f":"七言律诗","c":["姑苏城下刺兰桡，却忆吴王古市朝。","香辇路边春寂寂，馆娃宫外草萧萧。","千年往事空啼鸟，半夜疏钟自落潮。","明发不堪回首处，暝烟秋雨过枫桥。"]},{"t":"赋得白雁送人之金陵","f":"七言律诗","c":["燕山榆叶望秋稀，雪羽潇潇向楚微。","夜雨芦花看不定，夕阳枫树见初飞。","影随汉骑营边落，梦绕胡儿笛里归。","君到石城霜渐冷，暮云声断欲沾衣。"]},{"t":"题彭韫玉秋山行旅图","f":"七言律诗","c":["閒门秋晚叶皆飞，征路逢霜客渐稀。","独树断猿愁远骑，隔林残烧映行衣。","西风一饭人烟少，落日千峰夕鸟微。","莫向他乡留滞久，故园山水候君归。"]},{"t":"初秋寄清江林崇高先辈","f":"七言律诗","c":["十年沧海寄萍踪，迢递乡山思万重。","鸟外明河秋一叶，天涯凉月夜千峰。","心知久别魂应断，生事中年梦亦慵。","无限相思何处著，越山仙岛树蒙茸。"]},{"t":"送别林彦时之建上","f":"七言律诗","c":["黄叶纷纷秋满天，故人今夜惜离筵。","他乡见月长为客，别路逢霜半在船。","剑浦绿芜连晚烧，幔亭荒树带寒烟。","明朝碧水丹山下，知尔相思若个边。"]},{"t":"道人延翠轩","f":"七言律诗","c":["山水婵娟扫黛屏，清晖迢递到柴扃。","云归独树天边小，雪罢孤峰鸟外青。","寒藓带花侵卷幔，野泉流叶近閒庭。","浮生只解人间事，未得从师种茯苓。"]},{"t":"沙堤燕集次韵答王介轩黄嗣杰","f":"七言律诗","c":["沧洲沙馆共欢携，红烛青尊月易西。","孤客独怜萍尚泛，幽期那似鹤同栖。","霜飘败叶催残腊，雁引寒声入夜溪。","何事故人俱断酒，风流佳句若为题。"]},{"t":"梅城夜泊","f":"七言律诗","c":["泽国秋风旅雁飞，海天愁思正依依。","孤城背岭闻吹笛，白露横江卧湿衣。","砧杵远村寒事早，市桥残火夜渔归。","兴来且醉梅江月，遮莫乡原落梦微。"]},{"t":"行次海上","f":"七言律诗","c":["晚风吹酒动离颜，别路萧条草树间。","积水乱流疑梦渚，一峰中断似君山。","鸡鸣海曙寒潮小，雁引秋声落叶闲。","行李飘飘又何往，暮云飞鸟也知还。"]},{"t":"送友人流西凉","f":"七言律诗","c":["凤林关路远悠悠，惆怅行人过陕州。","渭水寒流秦塞晚，灞陵残雨汉原秋。","玉门壁垒行应遍，白苇黄榆梦亦愁。","江海同人今已尽，南冠何事到君头。"]},{"t":"送陈自立游古田","f":"七言律诗","c":["孤舟何处兴堪携，红树千山野水西。","别路鸿声天外小，荒江帆影望中迷。","到楼残笛兼秋听，向壁新诗倚醉题。","我有相思寄流水，寒潮唯到白沙溪。"]},{"t":"古镜","f":"五言绝句","c":["宝镜何年铸，龙纹积暗尘。","非关磨洗倦，恐照白头人。"]},{"t":"鹧鸪","f":"五言绝句","c":["绿树残春外，双飞锦翼齐。","长沙有迁客，莫向雨中啼。"]},{"t":"长信宫落花","f":"七言绝句","c":["深宫花谢使人愁，片片随风满御沟。","妾命自怜花共薄，君恩那似水东流。"]},{"t":"渔笛","f":"七言绝句","c":["扁舟吹笛度横塘，欸乃声中也断肠。","莫道渔郎无别恨，武陵虽好是他乡。"]},{"t":"闻子规","f":"七言绝句","c":["枝上声声怨落晖，居人闻此也沾衣。","啼时莫近湘山路，更有长沙客未归。"]},{"t":"咏秋风","f":"七言绝句","c":["青蘋江上响潇潇，吹得林间万叶飘。","何处凄凉最关别，数株残柳灞陵桥。"]},{"t":"挽道士","f":"七言绝句","c":["云卧山房秋草青，步虚声断月冥冥。","凄凉行到空坛上，拾得松间旧鹤翎。"]},{"t":"村居","f":"七言绝句","c":["草径茆扉带软沙，隔林鸡犬几人家。","青山尽日垂帘坐，落尽棕榈一树花。"]},{"t":"衰柳","f":"七言绝句","c":["西风昨夜灞陵秋，千树萧条带驿楼。","莫道离人空有恨，暮蝉寒雀也关愁。"]},{"t":"海城秋晚","f":"七言绝句","c":["西风一雁海城头，羌笛声中水乱流。","枫叶萧萧山月下，戍楼残火几家秋。"]},{"t":"老马","f":"七言绝句","c":["百战沙场老此身，长楸宫草几回春。","只今弃掷寒郊路，犹自悲鸣恋主人。"]},{"t":"山窗夜雨","f":"七言绝句","c":["深涧垂萝暗竹房，半枝残烛雨声凉。","萧条树叶千峰里，不独啼猿断客肠。"]},{"t":"山楼对酒","f":"七言绝句","c":["楼前积水映苍苔，卷幔孤云落酒杯。","更尽一樽秋雨外，故山曾有几人回。"]},{"t":"海上送别林崇高先辈二首 其一","f":"七言绝句","c":["海上新晴野水春，烟村花鸟送行尘。","十年客路堪惆怅，况复今朝别故人。"]},{"t":"东山留别林良箴寓舍二首 其一","f":"七言绝句","c":["凤林溪上见秋风，客里相看欲转蓬。","鸿雁萧萧霜渐冷，别离况是叶声中。"]},{"t":"东山留别林良箴寓舍二首 其二","f":"七言绝句","c":["秋原千树叶初飞，夜火遥村听捣衣。","莫向他山倍惆怅，家林犹恐未堪归。"]},{"t":"胡儿吹笛","f":"七言绝句","c":["雪净阴山片月孤，数声羌笛起单于。","不堪吹作《梅花》调，少多中原客在胡。"]},{"t":"月下闻筝","f":"七言绝句","c":["愁心不见薛琼琼，何处银筝半夜声。","肠断十三弦上月，一弦一柱总关情。"]},{"t":"题梨花班鸠图","f":"七言绝句","c":["绣颈斓斑锦翼齐，梁园春树好飞栖。","乐游年少偏嫌雨，莫向花间自在啼。"]},{"t":"挽方山阐维那 其一","f":"七言绝句","c":["双树花飞送断香，六时经梵转凄凉。","青山何处堪垂泪，残月疏钟下影堂。"]},{"t":"挽方山阐维那 其二","f":"七言绝句","c":["禅心无住复无依，何处飘飘只履归。","想是石桥西畔去，寒林空葬旧僧衣。"]},{"t":"舟经彭蠡","f":"五言律诗","c":["杨帆过彭蠡，远见匡庐色。","瀑布天上来，芙蓉望中碧。","东林钟磬远，沽酒浔阳夕。","枫树忽鸣猿，凄然念乡国。"]},{"t":"题诸葛孔明像","f":"五言古诗","c":["炎祚忽云季，诸侯骋雄图。","栖栖刘豫州，三顾何勤劬。","汉贼不两立，一心抱区区。","临崩寄大事，忠愤常郁纡。","鞠躬乃尽瘁，贤哉此丈夫。"]},{"t":"钓台怀古","f":"五言古诗","c":["新室篡炎祚，中兴复舆图。","故人即轩冕，先生独樵渔。","一出尽交态，拂袖归桐庐。","岂唯黄绮辈，得与巢由俱。","我来访遗迹，高台倚荒芜。","酾酒酬千古，悲风起天隅。"]},{"t":"铜雀妓","f":"五言律诗","c":["朝上铜雀台，夕弄管弦哀。","酾酒望陵树，悲风千里回。","飞缦絓青汉，舞袖空徘徊。","君王不可见，玉座成苍苔。"]},{"t":"塞下曲二首 其一","f":"五言古诗","c":["横行羽林儿，生小邯郸里。","出塞入塞时，顾勋宁顾死。","去年战桑乾，今年战楼兰。","马上擒突厥，帐下降可汗。","谁知百馀战，封侯竟艰难。"]},{"t":"明妃曲","f":"五言古诗","c":["行行出塞门，饮血思长安。","穹庐冻不暖，雪飞边草乾。","汉国回头没，严霜镜中寒。","金铛煮羊酪，强接单于欢。","夜半雁声急，琵琶哀自弹。"]},{"t":"秋胡妻","f":"五言古诗","c":["河洲美王雎，所托有深意。","委身事良人，誓死终不二。","君行赴陈汝，妾独深闺里。","采采陌上桑，翩翩路傍骑。","黄金是何物，视之若泥滓。","日夕采桑还，行人已归止。","入门拜高堂，适来狂驰子。","相顾默无言，怀惭复何已。","羞与斯人俱，将身赴河水。"]},{"t":"妾薄命","f":"五言古诗","c":["妾家丛台下，花颜耀青春。","嫁得金吾婿，飘飘事边尘。","昨闻羽书至，阵殁交河滨。","战马委沙碛，兵符属他人。","念此每欲死，淋浪泪沾巾。","罗襦为君解，瑶瑟不复陈。","始信古人言，容华多误身。"]},{"t":"游天台国清寺","f":"五言古诗","c":["飞步赤城标，连峰积空翠。","杳霭葱茜间，千秋隐灵异。","石桥孤鸟外，香界清晖里。","群壑澹归云，遥林引寒吹。","遂造丰干庐，垂萝覆溪外。","真僧五百人，各了西来意。","愿此学无生，超然谢尘滓。"]},{"t":"寻清冷台访洽上人","f":"五言古诗","c":["端居在人境，久没尘壤中。","探奇不惮远，于焉得佳逢。","石怪互森列，台高絓虚空。","林端宿云去，竹外微径通。","岩壑深杳霭，天花雨臈茸。","洽师禅门秀，戒臈同古松。","说法超上乘，苦心归妙宗。","予惭善根浅，迷方莫能从。","暂此松下石，聊疏浮世踪。"]},{"t":"秋塘曲","f":"五言律诗","c":["妾身在寒塘，夫婿平原客。","白马五陵游，空闺断行迹。","忆昨别君时，蒲生柳条碧。","及此君不归，登舻感秋色。"]},{"t":"送春词","f":"五言律诗","c":["袅袅杨柳枝，纷纷五陵儿。","翩翩白鼻騧，灿灿黄金羁。","昔为浣纱女，今作吴王姬。","不惜送春去，但恐换秋眉。"]},{"t":"悼邻妇","f":"五言古诗","c":["入水江有鱼，采山林有木。","栖栖东邻孀，悲凉守空屋。","年荒鬻钗钏，服食恒不足。","虽有膝下儿，身为富人仆。","浮生几何时，奄忽风中烛。","一旦寿命终，萧条但床蓐。","骨肉已不收，亲情复谁哭。","徒然束缚去，瘗彼沙冈麓。","为问里中豪，畴能念穷独。","姬文昔埋胔，千载耀芳躅。"]},{"t":"拟古","f":"五言古诗","c":["明月照我室，揽衣起中堂。","北风卷帷幔，罗袜微有霜。","崇兰委芳质，寒螀鸣近床。","平生所亲者，宛在天一方。","相思无由理，况此寒夜长。","单居易为感，不觉涕沾裳。"]},{"t":"暮秋过陈氏园林","f":"五言律诗","c":["幽人栖隐处，苔径连深曲。","秋至垂橘黄，霜清大梨熟。","方池汎大影，可以澄心目。","饮水共忘形，何须徇荣禄。"]},{"t":"书上清方壶醉墨山水","f":"五言律诗","c":["林下多白云，溪口饶水木。","长啸鸾鹤群，翛然在空谷。","悠悠山色闲，浩浩波光绿。","寄醉墨壶中，惟应道机熟。"]},{"t":"与同志汎舟得净字","f":"五言古诗","c":["登舻发清啸，落日镜湖净。","微月波上澄，归云鸟边迥。","水木生夏凉，孤崖破阴暝。","矧兹簪佩同，复此沧洲兴。","中夜棹歌还，遥峰响烟磬。"]},{"t":"秋日山行","f":"五言古诗","c":["清秋发佳兴，著屐穷翠微。","鸟度黄叶涧，猿啼白云扉。","野寺隐孤磬，遥峰当夕晖。","浮云淡空宇，石濑清心机。","缅怀苏门啸，愿拂林中衣。","长歌望薜萝，思与尘世违。"]},{"t":"独酌言怀","f":"五言律诗","c":["林居绝轮鞅，独酌形亦忘。","百年会衰朽，一室任荒凉。","寤寐友千古，游心见羲皇。","所以陶潜翁，颓然卧柴桑。"]},{"t":"九月一日过崇信兰若","f":"五言古诗","c":["荒山响清梵，竟日无行迹。","释子支遁流，相逢澹空寂。","云归天际閒，鸟度林中夕。","境净秋色多，心远群机息。","妙契两忘言，微钟出萝薜。"]},{"t":"送林汉孟游温陵","f":"五言律诗","c":["月出螺渚寒，扁舟水容夕。","独树起鸣猿，遥山带行客。","清源钟磬音，金粟烟萝碧。","高唱人莫酬，探幽向禅寂。"]},{"t":"送别","f":"五言律诗","c":["鸡鸣海气白，驱马临长陌。","远树带鸣蝉，孤城对行客。","蓬累我萧然，萍流子何适。","相送独销魂，青山澹寒色。"]},{"t":"仲秋送人之塞上","f":"五言古诗","c":["河洲始鸣雁，白露沾我衣。","念子背乡国，秋风度金微。","举头见黄叶，倏忽四散飞。","如彼远游子，飘泊何当归。","人生无百年，会面安可希。","行当慎霜霰，皓首以为期。"]},{"t":"雨中怀瓢所","f":"五言古诗","c":["积雨抱幽独，斋舍何寥寥。","缅怀博陵子，隐处唯一瓢。","濯足双涧深，行歌七岩遥。","如何在城市，巾舄生尘嚣。","蕙草日已萎，松花日已凋。","相思不可见，梦落寒江潮。"]},{"t":"夏日过憩天王寺","f":"五言古诗","c":["炎暑不可度，端居日方永。","同袍四五人，共爱山中静。","飞阁轶氛埃，丛林逗萝径。","潭静日已秋，竹深午犹暝。","初沿双溪转，稍入空中境。","婉婉林鸟声，悠悠野僧定。","平生好幽玩，尽日惬佳兴。","山水发清机，风泉澹初性。","日夕徐徐归，云间响孤磬。"]},{"t":"经友人故宅","f":"五言古诗","c":["策马孤城下，经过泪盈襟。","开门絓蟏蛸，井灶莓苔深。","念彼泉下人，悽然杳难寻。","萧条故篱菊，识我平生心。","揽辔向前路，徘徊出寒林。","谁知山阳笛，恻怆犹至今。"]},{"t":"送别陈平叔归黄山","f":"五言古诗","c":["置酒雁峰上，酣歌豁冲襟。","临觞不尽醉，何以慰我心。","望望遥天云，苍苍远州树。","落日波上风，残钟鸟边屿。","此别虽未远，重来复何时。","论交愧知己，握手翻成悲。","君卧黄山云，我弄沧洲月。","云月两悠悠，相思坐超忽。"]},{"t":"思诚斋为曾照磨赋","f":"五言古诗","c":["冲漠窅无眹，苍苍但幽玄。","仲尼既摽本，兹道常豁然。","末流矜小智，百伪汨其天。","达人贵精一，思将体乎乾。","斋居澹而默，万汇纷我前。","浑沦灵台奥，缅尔太极先。","众妙倏有契，洞然冰鉴悬。","始从勿妄语，终以谐圣贤。","谁欤洓水翁，千载感微言。"]},{"t":"潘源润思义轩","f":"五言古诗","c":["志士顾名节，商人竞刀锥。","义路久荒没，人谁得其蹊。","夷齐独何为，行矣西山薇。","猗彼延陵子，高踪邈难期。","清风激颓靡，薄俗渐浇漓。","岂意千世下，人犹想刑仪。","端居贵名教，动息怀所宜。","冥心戒苟得，百行从可知。","仲尼有明训，勖尔恒自持。"]},{"t":"林伯予师宴堂","f":"五言古诗","c":["交久敬弥笃，仲尼称其贤。","廛居任湫隘，豆肉不掩肩。","美哉君臣义，金石行当宣。","遂令太史公，忻慕思执鞭。","吾子重高节，尚友千古前。","堂开七岩下，中有双涧泉。","宴坐澹无私，恬然忘外喧。","寤寐梦先哲，道存犹未捐。","余惭石父贱，感激应谁怜。"]},{"t":"同林汉孟池景大静得轩壁","f":"五言古诗","c":["胚浑本无象，圣人亦何言。","唯应遂初心，庶以窥其源。","冥栖守玄默，水木澹丘园。","浮云净空宇，爽气当前轩。","妙契忽自领，恬然忘外喧。","孰云吾道远，乃自灵台根。"]},{"t":"连川医者许得明悠然楼","f":"五言古诗","c":["楼居结遐想，高超世人群。","冥栖寄寥廓，心远遥天云。","举目见归鸟，夕岚浮氤氲。","清晖旷无际，揽之不盈分。","缅怀沈蛟井，金绳閟苔纹。","灵贶亘千古，英声耀前闻。","以言岐黄秘，稽首长桑君。","毋令上池水，独涴灵台焚。"]},{"t":"梁董教乐善堂","f":"古风","c":["志士迈恒调，所践唯格言。","心以善自乐，身将义弥敦。","结堂奉脩?，孝养勤朝昏。","庭门水木秀，春至池草蕃。","世情徇荣禄，所向多异门。","谁知贵天爵，此乐难具论。"]},{"t":"题松陵吴文刚长春轩","f":"五言古诗","c":["习隐向微道，了然玄牝门。","口含金鹅蕊，身寄桃花源。","结宇閟青阳，寒林变氛氲。","逍遥太和际，发生灵台根。","结想梦岐伯，飞声继轩辕。","希君黄芽秘，永矣驻精魂。"]},{"t":"古田陈叔重著存堂","f":"五言古诗","c":["风树叹亲没，含悽竟何言。","空馀永感下，慨此雷露繁。","蘋藻洁时祀，焄蒿动精魂。","音容恍在眷，謦欬恒若存。","堂虚俨像设，林木当前轩。","林木有时变，此心常弗谖。"]},{"t":"清江散人为林孔逸写前林过雨图","f":"五言古诗","c":["清川带长林，雨后宜水木。","澹沲天影寒，孤光霁人目。","归云澹空青，虚窗响悬瀑。","日夕山气佳，心閒道机熟。","烟际下遥钟，西岩数峰绿。"]},{"t":"题虎","f":"五言古诗","c":["麟凤那可驯，托迹穷幽邃。","群动争朵颐，纷纷竞相噬。","何意爪牙雄，隐身翠微里。","朝膳松下麋，夕饮涧中水。","矢心不咥人，逍遥白云际。","日与龙为徒，优游保终始。"]},{"t":"寒夜宴集陈拙脩西轩","f":"五言古诗","c":["飞霰夜仍集，寒飙鸣近林。","感君玉壶酒，微昏忽盈襟。","中庖出丰膳，剧饮成讴吟。","宾言无多酌，主称宜再斟。","人生亦奚为，所愿常盍簪。","何必候离间，临风想徽音。","顾惭悠悠者，辱此惠爱深。","穷匮不能答，嘿嘿以铭心。"]},{"t":"书怀寄所知","f":"五言古诗","c":["孟冬天气肃，北风何凄凉。","引领望江介，凝霜沾我裳。","非无越乡感，别久以为常。","终怀首丘念，欲往川无梁。","越鸟辞旧林，燕禽正南翔。","清川去悠悠，离心日已长。","盛年不再至，玄鬓忽已霜。","驾言适皇邑，远结金与张。","片言不合意，东还守空堂。","因书诉知己，恨恨中自伤。"]},{"t":"书溪山林薮图","f":"五言律诗","c":["花溪过残雨，隐处青苔纹。","松栝逗天影，萧萧鸾鹤群。","以言丘中赏，遗身寄孤云。","金梯与神遇，华顶青氤氲。"]},{"t":"传别驾风树卷","f":"五言古诗","c":["疾风吹庭树，游子常苦心。","禄养已不逮，江湖行且深。","鼎茵岂云乐，藜藿宁自任。","怀哉古人意，锡类犹至今。","鄱水漾寒波，楚云还远林。","含悽念幽壤，几欲忘华簪。"]},{"t":"题郭熙水墨为陈沧洲作","f":"五言古诗","c":["飞流积天镜，胜寄来花源。","寻林烟露晚，扫石泉萝偏。","瑩神庶遗境，历寂焉累烦。","身与鸟共远，兴将云独还。","以求沧洲侣，永矣洗心言。"]},{"t":"题林彬家画","f":"五言律诗","c":["谷口翠微路，深溪明药丛。","宴林候巾舄，卷幔来群峰。","心远鱼鸟狎，迹幽猿鹿同。","行当复摇棹，杳霭东林钟。"]},{"t":"送郑上舍缙省亲之朔州","f":"五言古诗","c":["解薛受圭组，分符抚黎氓。","何意五马荣，翻垂曼胡缨。","持法在权贵，皇仁无此情。","狂歌夷门道，感激谁为平。","驱车出宛洛，悠悠念徂征。","恒山郁空翠，晋水空流声。","部曲不见让，嫖姚岂知名。","下去且勿叹，宁亲向边营。","何必儿女别，临岐泪纵横。"]},{"t":"送新宁簿丹徒镏公之天官","f":"五言古诗","c":["翩翩瑶台凤，鸣声何嗈嗈。","本期金琅玕，暂尔栖棘丛。","谁云小千室，守道随污隆。","三考未迁秩，一官恒屡空。","兹晨复辞满，祖道嘶华骢。","驿舫荔支雨，江邮榕叶风。","輶轩上京口，坐听金陵钟。","到家未几日，谒帝明光宫。","余亦弹冠者，何由托冥鸿。"]},{"t":"九日宴集盘石得诸商","f":"古风","c":["飙号大野萧，索如孟诸落。","日送飞鸿千，岩寒木疏置。","酒登啸台举眸极空虚酣歌醉。","仙菊列坐飘长裾身寄猿鸟外。","神游元化初飞声瑶池凤远致。","麻姑书遥海上孤月寒潮带。","归鱼天空百，泉响独鹤哀。","有馀不见松，柏路苍苍闭。","玄庐谁知委，运去千载随。","荒墟且复酌，美酒挥刀脍。","双鱼。","人生非乔松，不饮当何如。"]},{"t":"岁宴别施伯予还冶城甥馆","f":"五言古诗","c":["沂泗不可极，河汾亦悠悠。","真源了无迹，谁知溯其流。","爱尔尚苦节，担簦适来游。","披荒得微路，稍见窥前修。","尔家新宁墅，来往冶城秋。","夜雨梦甥馆，残灯忆家楼。","臈日湖上别，北风吹布裘。","寒山对绿酒，大雪飘行舟。","我有跌宕怀，翻然积离忧。","临岐叹孤凤，去去鸣丹丘。"]},{"t":"寄新宁林伯坚秀才","f":"五言古诗","c":["三峰过残雨，独树冥返照。","鸟外寻片云，霞边发孤笑。","若人沧浪心，挂席淩海峤。","白社偶香缘，清江隐渔钓。","缅怀中林期，负我苏门啸。","荣贱非所知，君其可同调。"]},{"t":"钱塘徐教谕春萱堂","f":"五言古诗","c":["陟屺积遥想，望云郁重襟。","夫子树丛萱，罗生北堂阴。","爱日耀朝景，繁英媚华簪。","采掇忧可忘，盼睐情何深。","方欣禄就养，亦尔道自任。","南陔有遗响，白华多好音。","愿言保贞素，永怀慈母心。"]},{"t":"赠德成岩道者二首 其一","f":"五言古诗","c":["巢居迥无迹，浮人岂知名。","振文掇霞采，孤坐白云英。","神閒了遗境，欲澹将寡营。","摽枝与野鹿，邈然两忘形。","适来本何期，倏别宁钟情。","长啸忽归去，啾啾鸾鹤声。"]},{"t":"赠德成岩道者二首 其二","f":"五言古诗","c":["岩栖带灵境，寥寥布金园。","跫然足音少，所遇麋与猿。","井灶白云里，枕席莓苔痕。","悬灯梦石榻，蝙蝠飞前轩。","腹中楞伽经，心解口不言。","众方委尘劫，此独求真源。","笋笠挂绝壁，卷衣弄潺湲。","夜半月出山，泉萝四垂门。","了然忘天地，独与静者论。"]},{"t":"遁素轩为张伯和赋","f":"五言古诗","c":["圭组岂不贵，藜藿岂不饥。","达士顺流坎，道在随所宜。","回也一瓢饮，禹稷恒忧时。","傅岩亦何卑，莘野宁久微。","夫子尚名教，遁世不见知。","遗身衡门下，守素无外驰。","大道且囊括，时来将有为。","非徒野鹿性，偃蹇如摽枝。"]},{"t":"题闽清林中叔梅林耕隐卷","f":"五言古诗","c":["结宇隐空翠，耦耕梅花林。","群岭寄孤鸟，众溪澄一心。","春至觇泉脉，遥遥西顶岑。","夤缘片云上，杳霭穷源深。","潭雨飒已至，虹蜺生我襟。","翩翩洪厓子，采药青萝阴。","手持若木杖，笑拂丘中琴。","以言得仙道，岂必服黄金。","言既忽飞去，诸峰龙夜吟。","榛篁閟秋影，石洞闻幽音。","翘首望不及，苍然何处寻。","还归理吾稼，宁用竞华簪。"]},{"t":"梦游武夷吴十董大客上","f":"五言古诗","c":["夕发紫霞想，神游紫霞峰。","回飙汎轻棹，九曲青芙蓉。","不见武夷君，幽溪但濛濛。","九函閟仙蜕，千载如花红。","白鹿行不返，丹楼烟霭中。","羽士尚控鹤，真人犹豢龙。","相携三姑石，眺晚闻霜钟。","毛竹隐初月，天鸡鸣万松。","夤缘金梯上，更历千数重。","双壁忽中断，氤氲垂药丛。","平铺亘百里，旷远谐心胸。","居人半鸡犬，鼎灶并房栊。","云衣卷山罽，石床疑鬼工。","洞中两神女，瑩色桃花容。","一笑粲玉齿，再言情已通。","愿留就金液，果然惬奇逢。","愁君乏仙骨，兹去迷灵踪。"]},{"t":"题冯公夙家藏方壸神岳琼林图","f":"五言古诗","c":["吾爱方壶子，翩翩列仙流。","咽津结龙虎，逍遥与天游。","有时发仙秘，戏扫琼林秋。","趋然粉墨外，坐使真华愁。","兹峰表神岳，漫漫元气浮。","祥飙转琪树，肃飒珊瑚钩。","玄凤隐朝景，三花媚灵湫。","伐毛紫霞里，濯足泉萝幽。","黄金变绿髓，千岁栖蓬丘。","世人哂丹汞，饭稻甘蜉蝣。","披图有遐想，其将方外求。"]},{"t":"林思器席上燕别高漫士得思字","f":"五言古诗","c":["月出东大堤，含辉正流丽。","同心以绸缪，何乃生离异。","置酒登高台，台中筦弦思。","临觞不能御，恨恨心已醉。","忆昔俱少年，眷言不相弃。","及兹别离时，衰境倏已至。","念君远行游，严驾越淮泗。","阿阁入云中，皇居俨迢递。","京邑多故人，谁为愿微细。","恨无承风翰，随君发遐裔。","浮云东南翔，夕景忽西逝。","安能守穷贱，皓首以遗世。"]},{"t":"题林汉孟瓢所","f":"五言古诗","c":["东林富猿鹿，下有静者庐。","四壁无长物，一瓢常晏如。","青萝覆虚牖，落叶纷前除。","初疑许由室，终类颜子居。","饭糗常自乐，饮泉非愿馀。","双涧时浣衣，七岩閒著书。","何须洗双耳，始与尘事疏。"]},{"t":"赠周谷泰赴召天京","f":"五言古诗","c":["王风变诸夏，光岳生才彦。","遂令布衣臣，歘起皆缨弁。","马卿宁久微，宁戚岂长贱。","扈从甘泉宫，承恩未央殿。","金陵郁龙虎，佳气浮葱茜。","天子坐明堂，群公牧州县。","奇居倜傥怀，而无故乡恋。","耻学儿女仁，含悽别亲串。","绿水映行辀，青山对华饯。","兹去复何辞，皇情有深眷。"]},{"t":"方壶渔隐图","f":"五言律诗","c":["沧波深不极，孤棹独容与。","白发尚渔竿，何心恋圭组。","翛然水木兴，浩荡沙鸥侣。","回首莓苔峰，苍茫夜来雨。"]},{"t":"题郑氏家藏古画","f":"五言律诗","c":["凉雨净氛壒，孤云结层阴。","飞流激芳涧，嘉木澄幽林。","鸟啼谷中趣，人閒川上心。","谁为后来者，当期此投簪。"]},{"t":"题山水小景","f":"五言古诗","c":["习静喜还山，山水趣方永。","灌木澄幽阴，风泉溜华顶。","清听空外遥，吾心坐未醒。","空山落叶时，渡口潮初长。","远树带虚亭，閒云霁孤舫。","古路今人行，浮生几回往。"]},{"t":"书问耕堂","f":"五言古诗","c":["庞公喻刘表，仲尼小樊迟。","为学贵自广，遗安亮无危。","若人隐耕稼，取乐宁在兹。","用舍随所遇，荣贱心弗移。","闭门面场囿，开轩瞩清池。","棕叶覆我牖，藤花垂我衣。","方春始微雨，薄言往东菑。","田叟既相勉，耰种恒及时。","稻苗日已长，稂莠日已稀。","远心易无闷，悟物兼忘疲。","虽云体力倦，斗酒聊自怡。","伐檀夙有戒，素食良可讥。","岂不善微禄，知命复奚疑。"]},{"t":"次韵奉答郑助教","f":"五言古诗","c":["凉雨净炎燠，微风松下来。","眷言青云客，晼晚沧洲怀。","翰墨冠时辈，风流倾众才。","高情表千仞，逸足淩三台。","既欣簪佩狎，复与缁锡谐。","清言方屡接，又恐心期乖。","短褐逐渔钓，衡门翳蒿莱。","宁知枉高驾，酌我林中杯。","尽醉无复辞，俱忘形与骸。"]},{"t":"书金碧山水","f":"五言古诗","c":["群峰绚金碧，积水澄天镜。","丛木生夏凉，孤云破朝暝。","波深鱼鸟同，地远衣冠胜。","意惬遂忘机，神閒庶遗境。","扰扰尘坌中，吾将弄烟艇。"]},{"t":"书林良箴云山幽隐图","f":"五言律诗","c":["沧江湛回流，野树带远色。","白云东山来，雅与幽兴集。","静抚丘中琴，时散林下帙。","余亦淡荡人，相期此投迹。"]},{"t":"为中林州题山水小景","f":"五言古诗","c":["离居杂尘想，久别山水深。","兹来惬清玩，复得谐夙心。","积雨川上霁，萧萧枫树林。","空翠洒飞阁，孤云閒远岑。","若人此真隐，缃帙与瑶琴。","怅望独不见，空期鸾凤音。"]},{"t":"书高谩士为陈容斋作山水图","f":"五言古诗","c":["落景逗秋思，深潭澄夕氛。","金梯拂萝月，苔泉镜中闻。","但觉灵境幽，都无浮世纷。","白鹿知閒游，呦呦清溪濆。","焚香鬼谷暝，辍棹花源分。","瑩神写冰弦，石床梦氤氲。","而我烟霞侣，今随鸾鹤群。","唯馀瑶华音，山水同清氛。","华顶何寥寥，我行多白云。","长歌采三秀，不堪持寄君。"]},{"t":"题画二首 其一","f":"五言古诗","c":["二十卧云壑，长吟招隐篇。","梯岩结幽构，凿石开山田。","时经翠微峰，扪萝拂青天。","脱巾挂修竹，酌酒挥五弦。","别来如蓬转，兹赏竟茫然。","白首竟垂钓，萧条东海壖。","徒有鸾鹤心，终无黄绮缘。","今晨展图画，因以思林泉。","何时还旧隐，遂买秋江船。"]},{"t":"题林景时水墨山水","f":"五言古诗","c":["向壁见空翠，满堂烟霭生。","都无粉墨姿，但觉泉籁声。","羡尔丘中赏，沿源结幽盟。","閒寻天窗外，时拂青萝行。","身与云共远，心将猿独清。","予亦淡荡人，因之谢浮名。","愿餐金鹅蕊，飞步窥蓬瀛。"]},{"t":"书周造士扇头","f":"五言律诗","c":["极浦澹远姿，遥峰写修书。","清晖袭房栊，缃帙生华滋。","嘉尔日在泮，还山仍下帷。","唯应结幽兴，与我琴心期。"]},{"t":"陈思孝怡偲堂","f":"五言古诗","c":["伯仲我同气，结交我同门。","恳恳互规谏，夸毗奚足云。","常怀连枝爱，岂必篪与埙。","所亲谅已笃，疏者情亦敦。","若人尚古道，堂构依山樊。","庭閒水木秀，清晖蔼前轩。","谷鸟时一鸣，深池芳草繁。","伊彼伐木咏，感兹棠棣篇。","于焉见高义，薄俗难具论。","怀哉鲁中叟，千载垂嘉言。"]},{"t":"赠别陈少尹思孝服阕之天官","f":"五言古诗","c":["晨登无诸台，南望冶城阙。","垂杨夹岐路，一日几人别。","行人恶离别，仆御愁不发。","斯须竟参辰，况乃千里诀。","行人难久留，结驷登瀛洲。","连宫出阊阖，上有佳气浮。","鳷鹊丽飞观，铜龙起高楼。","结托尽中贵，经过皆列侯。","侯家连戚里，日夕歌钟起。","金貂锡元勋，赤舄何几几。","宦游良不恶，冠盖相萦络。","谁怀长卿贫，沈疴守藜藿。"]},{"t":"为醉樵书水墨扇头","f":"五言律诗","c":["入山不辞遥，爱此泉萝僻。","悠然与心期，孤云澹而白。","谷神养玄牝，应寂了空色。","思与静者谐，投踪寄苔石。"]},{"t":"题高漫士","f":"五言古诗","c":["山郭雨新霁，孤云湿犹飞。","岚岭隐空翠，石林閒清晖。","时与同心人，逍遥爱荆扉。","都无浮世累，共我饭蕨薇。","日夕笑分去，微风拂罗衣。"]},{"t":"题传别驾存省堂","f":"五言古诗","c":["大路久榛芜，末流异溪径。","淳庞日已隳，遂令此心病。","众伪挥我真，百邪乱吾正。","谁知灵台中，澹然大虚静。","驯扰无外驰，澄明见初性。","嘉尔有道人，于时复存省。"]},{"t":"张节推存心堂","f":"五言古诗","c":["形妙结元化，虚灵独函中。","瀰漫八弦内，廓尔天地同。","以言道自守，了与真源逢。","澄明烛万变，百体俱随从。","外视失初性，荡然若乘空。","谁应静夜气，复与灵台通。","若人抱月神，日夕怀深衷。","常虑爱物浅，思将拯疲癃。","名堂有远意，岂帷昌厥躬。"]},{"t":"书陈思孟家藏古画二幅 其一","f":"五言律诗","c":["胜寄结幽梦，远林适孤寻。","澹然花源里，杳蔼云木深。","胸次不碍物，但闻丘中琴。","唯应弃瓢者，永言谐夙心。"]},{"t":"书陈思孟家藏古画二幅 其二","f":"五言古诗","c":["绝壁淩山梯，连峰出孤岛。","天虚灵籁寒，月隐泉萝晓。","长啸入苏门，跫然足音少。"]},{"t":"赋得云溪别棹送宪从事赴京师","f":"五言古诗","c":["手折台上柏，送君天外心。","云飞隔溪水，望望隔层阴。","仙棹去俄顷，沧波杳难寻。","行将拂霄汉，发轫当在今。","我有千古怀，寄情江海深。","别离贵有赆，愧无双南金。"]},{"t":"题刘炷家藏画","f":"五言律诗","c":["秦人避嚣处，鸡犬桃花林。","水石隐天镜，泉萝闻夜琴。","纷吾厌氛壒，欲往路瀰深。","永怀苏门啸，邈然尘外寻。"]},{"t":"书水墨图","f":"五言古诗","c":["岚岭閟幽搆，清晖长在门。","閒寻鬼谷隐，杳霭迷仙深。","灌木递葱茜，飞萝垂可扪。","豁然心境异，邈尔朝市喧。","苔际坐亭午，微飙散氤氲。","潭清浣予衣，蕺芳佩兰荪。","绿水深见底，澄明瑩心魂。","孤云石上起，与尔俱无言。"]},{"t":"题高廷礼为陈拙脩绘沧洲隐","f":"五言古诗","c":["我昔放仙鸟，梦游东海滨。","行歌小山桂，遂偶沧洲人。","结交龙门子，招邀浮丘生。","都无簪冕系，而有山水情。","浮丘逐铜辇，龙门登玉堂。","皤然沧洲隐，与我唫沧浪。","有时猎群书，宛在竹深处。","境静不遑眠，中宵启前户。","龙门惜暌离，故写无声诗。","别后见云树，相思但悽其。"]},{"t":"阜阳陈果之爱日堂","f":"五言古诗","c":["慈竹隐疏幔，慈乌巢近林。","春阳发众汇，寸草齐倾心。","懿彼堂上人，辛勤嗣徽音。","至恩谅莫酬，廓然天地深。","以兹常爱日，承颜竞分阴。","常虑日苦短，徂年易骎骎。","皇天锡难老，菽水当在今。","何必太行颠，望云伫层琴。","客游阜阳墅，闻风感微忱。","谁持大手笔，以著贤母箴。","南陔久不作，为君起讴吟。"]},{"t":"游竹林深处因赠拙归居士","f":"五言古诗","c":["深林霁初霭，氤氲逗萝径。","烦熇遍朱火，爱此山中静。","拂石云共眠，横琴鸟皆听。","神閒境自玄，物澹心逾迥。","超然维摩居，水月初见性。","行苦人未归，岩栖独清净。"]},{"t":"建安王彦真善墨竹道遇新宁林彦时写岁寒烟雨为别索余就题其上","f":"五言古诗","c":["黄鹤久为别，苍茫云海涯。","青鸾尔何来，婉娈湘山期。","烟雨变丛色，虚心独华滋。","于焉脱节劲，岂逐春华萎。","二十五清弦，一弦一悽其。","鸾惊复分去，鹤怨仍伤离。","纵使鸾鹤悲，终归集瑶池。","梧树秋不实，天霜落寒威。","谁能慰孤凤，日夕恒苦饥。","缄情寄幽梦，忆君苍筤枝。"]},{"t":"题画扇","f":"五言律诗","c":["山空水云净，月出洲渚白。","寒苇梳幽风，孤蓬逗秋色。","垂纶久忘鱼，击汰非干泽。","终愧坐磻溪，皓首钓人国。"]},{"t":"陈大家题董羽神变图","f":"五言律诗","c":["神踪发幽秘，变化谁可知。","玄感竟莫测，孰能驯扰之。","当其永潜翳，曾不异蛟螭。","时来一奋激，沛然与天期。"]},{"t":"为游道人书栖真图","f":"五言古诗","c":["尘外俱太古，尘内多浇漓。","夜即吸沆瀣，晨将弄参差。","恬然不婴物，至道其无为。"]},{"t":"送陈和中赴召","f":"五言古诗","c":["河洲发仙舸，明日过镡津。","云是金台客，西游谒紫晨。","乳酒白玉壶，送行多亲宾。","酣歌供帐下，策马长江滨。","越水碧到海，楚山青入闽。","挥手谢余去，遥遥动车尘。","三月金陵道，千花白门春。","皇居九天上，簪绂罗群臣。","飘飖双凤侣，追随五龙宾。","日夕饭琅玕，毋为凡鸟嗔。","兹行必特达，飞书报乡人。"]},{"t":"钱林一崟负谴赴京师","f":"五言古诗","c":["泽国噭春雁，风花送离筵。","挥觞念行子，驱车发闽川。","秉笔事藩府，辞家已三千。","何知公冶系，徒使尼父怜。","翘首白云冈，含悽鹡鸰篇。","回林顾天属，远道同周旋。","白璧非不贵，精诚合其天。","明当抵京邑，秦台镜高悬。","含恩沐春露，发兴归秋田。","故里足禾黍，西崖好林泉。","选幽拂霞坐，寻云谒金仙。","閒来结吟社，暂割寰中缘。"]},{"t":"琴乐子墨菊杂以竹兰贻张氏清玩","f":"五言古诗","c":["何事采三秀，清时歌考槃。","缅怀长林子，荷衣而鹖冠。","坠露当朝饮，落英为夜餐。","清冷上池水，一吸无留残。","嗟尔郢中思，徒劳抱琴弹。","唯应褰芳者，可以同岁寒。"]},{"t":"雨夜舟中作","f":"五言古诗","c":["落日浮洞庭，宵分逗烟舸。","侧闻巴陵钟，遥爱君山火。","片雨潭上来，凉声满高卧。","龙鸣秋籁寒，蛟泣灵珠堕。","瑶瑟何悽其，苍梧晓来过。","谁能问重华，空鼓潇湘柂。"]},{"t":"哭沧洲陈景明处士","f":"五言古诗","c":["盥栉中夜起，悲歌泪盈襟。","衔哀思明哲，徒有不死心。","昔来论久要，落落襟期妙。","当以古人求，今人少同调。","君家足文献，胜事令人羡。","脱略远膏腴，追随狎贫贱。","出入恋同声，去留无吝情。","争闻柳下风，竞播栗里名。","平生爱精猎，著作多盈箧。","晨抄不辍手，夕诵未交睫。","客来即命觞，谑浪如疏狂。","醉后又分咏，敏捷皆成章。","有时忽得句，夜半叩予户。","开门见月明，相邀到天曙。","心迹两悠悠，功名无所求。","共吟萧寺雨，同醉镜湖秋。","长怀武夷趣，欲往嗟迟暮。","终羡子长游，空怜向平去。","我本东西人，移家托芳邻。","绨袍意所恋，尊酒情益亲。","铭镌向心骨，倏尔惊存殁。","开箧见遗书，迸然涕俱出。","忆昨登洪山，徘徊苍翠间。","俛仰遽云殁，玄庐竟掩关。","吞声不能道，感激沧洲皓。","怅望无还期，沧洲长春草。"]},{"t":"题吴奉使贪泉卷","f":"五言古诗","c":["宁浣盗泉水，宁爨恶木薪。","贪泉尔何物，一歃移我真。","甘冽滋华池，清冷沁丹府。","谁知灵台根，倏尔成幽蠹。","我闻濯缨者，尚取沧浪清。","朝歌与胜母，昔贤憎其名。","至人方寸间，澹然太虚净。","常以坚白存，何忧及缁磷。","于役念靡盬，时时顾王程。","唯应贪泉戒，永以资廉明。"]},{"t":"夷门怀古","f":"古风","c":["策马夷门道，萧条愁杀人。","魏王公子不复见，大梁宫殿随灰尘。","七雄戈剑纷相击，秦兵已在邯郸陌。","晋鄙难回朱亥椎，如姬早中侯嬴策。","春去秋来百草青，古城落日烟尘生。","眼前不见抱关者，世上空传侠客名。","秋天摇落多愁思，信陵原头木应死。","谁见豪门爱士时，惟有东流汴河水。"]},{"t":"隋堤柳","f":"古风","c":["君不见长堤柳，何袅娜。","广陵二月三月时，两堤人看青丝亸。","忆昔繁华大业秋，此地曾经系綵舟。","莺声忽起黎阳变，风光不驻江都游。","千年往事东流去，柳色依依旧行路。","伤心不必叹销沉，回首唐陵几株树。"]},{"t":"羽林少年行","f":"古风","c":["生少事嫖姚，出身羽林子。","力战三边岂顾身，报雠千里曾轻死。","相看雪刃气如虹，白日横行都市中。","鸣鞭走马入州县，纷纷郎吏争趋风。","自言家住邯郸陌，出入金门侍君侧。","门前不数五侯宾，醉里常轻二千石。","日晚长楸校猎归，可怜人马生光辉。","自矜恩宠常如此，大笑傍人终布衣。"]},{"t":"赋得函谷关送人入秦","f":"古风","c":["迢迢函谷关，北壮秦山路。","关门今古几人行，荆棘荒凉惟古树。","君不见伯阳迢递西入关，骑得青牛去不还。","田文爱材客满座，鸡鸣犬吠今茫然。","秋风黄叶重关下，金锁平明出车马。","男儿独数弃繻人，隐士曾闻抱关者。","君去西游几日归，五侯七贵相追随。","归时为问关城吏，莫笑行人终布衣。"]},{"t":"谩歌","f":"古风","c":["饮君玉壶酒，听我击剑歌。","孝王宾客久寂寞，梁园修竹今如何。","五陵年少无知己，胶漆陈雷更谁是。","昨日青云四五人，弃我悠悠一杯水。","锦袍白马何匆匆，当街上马生春风。","并辔朝回双树下，看花醉倒五陵东。","他人逐势争先后，伫立道傍齐拜手。","君不见张良韩信贫，流落江湖聊寄生，一朝恩宠赐颜色，岂得长为飘泊人。"]},{"t":"从军行","f":"古风","c":["少小事嫖姚，辛苦烟尘里。","力尽三边境未归，身经百战常轻死。","古戍苍苍绝塞边，黄沙白草暗祁连。","将军金印不得佩，麾下铁衣今已穿。","往来阴碛狼山下，破讷峰南战初罢。","走马交河雪下时，洗兵瀚海鸿飞夜。","战骨萧条翳草根，边烽寂寞照营门。","只知边将封侯贵，不见沙场愁断魂。"]},{"t":"书郑伯固冷斋卷","f":"古风","c":["肉食厌藜藿，貂衣哂逢掖。","朝醉邯郸春，莫宿平原宅。","香街白马动行轩，羡君读书长闭门。","华堂绮席仍击钟，羡君一瓢常屡空。","石崇舍下金如土，田鼢门前客无数。","君将富贵等浮云，却向人间独辛苦。","高斋卷幔对青山，曲几残尊野菜盘。","帘前水鸟将心远，灯下松霜落梦寒。","几年在泮閒搔首，禄米何曾足沽酒。","弟子频分出首符，故人已结朝天绶。","他时青紫系黄金，莫负悠悠冰雪心。"]},{"t":"温陵留别陈四博士","f":"七言古诗","c":["军城腊月桐叶飞，北风萧萧吹客衣。","旅馆狂歌转萧索，故园长望空依微。","吴姬酒醒春还早，那似繁华旧时好。","五陵白马尽浮云，甲第朱门共秋草。","怜君十载教温陵，不向青云叹未能。","堂下诸生揖胡琼，海内贤豪趋李膺。","往来京国知名久，健笔雄词世稀有。","草圣曾惊御史骢，风流每醉将军酒。","他乡生计近何如，桐下萧条杨子居。","夜雨长愁旧国柳，秋风忽忆故江鱼。","叹予飘泊红尘里，相识惟君最知己。","问我年来只布衣，念我家贫尚如此。","悠悠萍水各东西，也似飞鸿踏雪泥。","百年心事难倾写，千里云山又解携。","迢迢金粟清源洞，野鸟山花日迎送。","别后清猿夜夜声，知君空有相思梦。"]},{"t":"故人陈孟敷董教三衢适以事归未几亟还竟弗获面使人怏怏故有是作","f":"古风","c":["朝济越江帆，莫投冶城郭。","寒日衣上残，微霜草头落。","城南种柳春复春，几度经过忆故人。","故人得官未得意，青袍束带聊裹身。","萧条客舍三衢里，一片柯山对乌几。","得钱便买浙江鱼，浑家衣食公田米。","忽闻君来喜不定，几日狂歌候萝径。","斗酒空馀别后期，扁舟祗是山阴兴。","如何归骑太匆匆，冠盖纷纷祖钱同。","嗟予参差忽不见，怅望青天飞塞鸿。"]},{"t":"题闽士倪生渠阳军中春晖堂卷","f":"古风","c":["倪生倜傥人，眼白天下士。","腹中千卷人岂知，未肯低头拾青紫。","如何孤剑独从军，迢递乡山隔楚云。","鸿雁声中空吊影，鹡鸰原上叹离群。","故园梦远心常到，惆怅庭帏日应老。","落羽偏怜反哺乌，春晖倍忆忘忧草。","春晖烨烨照营门，游子时时念母恩。","白云几度频回首，边月何人不断魂。","荒城古戍无州县，瘴水蛮烟杂霜霰。","相逢俱是五溪儿，寄书不到三秋燕。","昨夜宁亲赋独还，西风残叶穆陵关。","衣沾彭蠡湖边雨，路指无诸郭里山。","君家更在罗江浦，丹荔花香酒如乳。","菽水重欢膝下情，风沙不记军中苦。","匆匆又说别家林，衣上仍缝慈母针。","时平边塞无烽火，知尔长悬爱日心。"]},{"t":"梅城小景","f":"七言律诗","c":["江城何人夜吹笛，寒落梅花晓无迹。","仙峤苍茫隔海清，人烟寂历连秋色。","何处征帆天际归，夕阳枫树鸟边微。","矶头亦有垂纶者，甘向沧浪老布衣。"]},{"t":"歌行送别林良箴","f":"古风","c":["拔剑击铜斗，醉作游子歌。","凉风萧萧堕梧叶，清猿袅袅啼绿萝。","羡君为人好风采，谁那襟期隔山海。","握手频分两地愁，卜邻空费千金买。","买臣萧条主父贫，布褐羹藜多苦辛。","我今与子俱未达，蹭蹬岂若寻常人。","伯劳东飞燕西去，斗酒相欢别岐路。","座上同声歌送君，杜陵野客心偏苦。","双溪竹屿入云林，君去携书更抱琴。","近闻下榻多贤者，若个交游情最深。"]},{"t":"题洞云耕隐卷","f":"古风","c":["悠悠江上云，落落洞中叟。","老大还耕谷口田，风流亦种柴桑柳。","萧散孤云野鸟边，夕阳门巷桔槔悬。","秋风落叶黄花酒，盘石垂萝白日眠。","晓篱野菜迎霜绿，晚饭山厨旋蠹谷。","羞逐邻翁日贩缯，懒随年少时干禄。","门前春雨泥复深，辛苦由来不愧心。","鹿门向在云深处，刘表殷勤那得寻。"]},{"t":"浮峰歌送进士陈以义贡京师","f":"七言古诗","c":["海上迢迢江水东，江心绝巘青芙蓉。","横空积霭几千丈，绿萝袅袅花濛濛。","深沈玉镜浮仙岛，黛色青青不堪扫。","芳草矶头望欲流，夕阳渡口看还好。","翠壁红泉高际天，閒云古木相连延。","岚烟瀑雨猿声里，僧舍人家鸟道边。","仙舟江上何潇洒，此地那能驻君马。","思尔青云得意时，莫忘幽期绿萝下。"]},{"t":"海上仙槎赠丘二之儋州长史","f":"古风","c":["海上仙槎流汎汎，槎枒古木连枝蔓。","凉秋八月风正高，淩轹鲸鲵泛霄汉。","依微珊，瑚树髣髴扶桑株。","宛疑太乙红莲叶，绝胜鲸高赤鲤鱼。","随风飘飘五云上，烟霞为蓬浪为桨。","坐看神女弄珠游，卧听鲛灵剪绡响。","忆昔漂流海岛间，载得仙翁去不还。","又乘汉使河源里，星斗离离衣上寒。","析木津黄姑渚白波漫，漫澹空宇袖得天。","孙采石归始知身，到银河里君为仙。","吏下炎州，黎母山青瘴海秋。","功成毕竟朝天去，且著灵槎汗漫游。"]},{"t":"送林九博士秩满之天官","f":"七言古诗","c":["我闻昔时伸蒙子，乃在筹峰白云里。","一朝高议动金门，千载香名照青史。","君是伸蒙几叶孙，世泽流传今尚存。","宁将词赋客梁苑，肯随剑里趋平原。","重林书舍何潇洒，花屿南头董峰下。","巷曲能回长者车，门前每系青骢马。","未年三十教黉宫，官舍潇然多好容。","坐上谈经若流水，众中答问如撞钟。","今年官满朝京国，残叶秋风逗行客。","浙水寒山鸟外青，吴门曙月烟中白。","九月秣陵鸿雁飞，霜花扑人初著衣。","日晚行过石渠署，天明入觐黄金扉。","蓬莱参差五云遍，钟阜苍苍压淮甸。","凤阙韶音袅袅闻，龙池柳色深深见。","此去应怀明主恩，石田茅舍不须言。","男儿亦在功名早，何必栖栖恋故园。","城隅别酒同倾写，愧我萧条孟诸野。","相送寒江万古心，他年来问山中者。"]},{"t":"陈思孝石田山房","f":"七言古诗","c":["阿谁书室山阴墅，旧是郎官栖隐处。","山头先雪剪茅茨，石上开云种禾黍。","禾黍秋香酒满杯，绿萝花发映莓苔。","龙龛树底钟初断，金漆湖边月又来。","柴门尽日人稀到，山叶无风自飞堕。","阶下红泉鸟饮残，谷口青泥鹿行破。","忆昨郎官未仕时，石田茅舍此栖迟。","青山醉逐渔樵伴，白眼羞逢杜宛儿。","金陵大道青天上，别后丘园也惆怅。","四壁寒蛩夜夜声，一帘草蔓青青长。","往事浮云共渺然，风流嘉政殁仍传。","旧箧愁看书尚在，开门时见揭犹悬。","看君亦是青云器，野性还应爱山水。","高卧山中绝世尘，萧萧风木更悲辛。","男儿达节有如此，未必寻常畎亩人。"]},{"t":"赋得剑津送郑孟宣之江右考文","f":"古风","c":["闽溪迢迢絓绝壁，平津之水深千尺。","神物湮沈不复知，往往潭心飞霹雳。","银河掩映流寒声，玻瓈井底双龙行。","九华山色纷照耀，丹枫寂历秋风鸣。","吾夫子，浮丘生，送君几度持文衡。","扁舟触热那可度，来往津头须濯缨。"]},{"t":"送林彦宾重庐州省兄","f":"古风","c":["斗酒不忍别，空歌叹离群。","梦随楚天鸟，心逐淮山云。","九月梨花红，千门响砧杵。","朝拂车上霜，暮投月中墅。","一别连枝几断魂，秋风又念鹡鸰原。","此行莫作分飞雁，看尔双双归故园。"]},{"t":"题林良箴琴乐卷","f":"古风","c":["太朴日已远，希音竟谁怜。","见君奏流水，邈然无徽弦。","弦中掩抑多深思，世上谁能识君意。","爱客宁无沽酒资，得钱祗是修琴费。","四十年高尚不官，琴心应与道心閒。","羡君布衣能自乐，知君一瓢能自宽。","兴来拂宫羽，泠然转清商。","脱略徽轸外，人琴两相忘。","阴林折竹寒萧洒，暗水流冰雨飘瓦。","雪海凉天落雁秋，空山腊月乌啼夜。","山妻听曲欲忘贫，稚子弄弦心亦淳。","闭门不受知音赏，应似悠悠太古民。"]},{"t":"陈平叔醉墨堂","f":"七言古诗","c":["黄山笔冢连糟丘，墨池酒泉相映流。","霜毫画酣玉薤露，云笺夜酗蒲萄秋。","黄山中人鹖冠子，身裹绿萝著双履。","萧洒唯应继右军，濩落偏能如长史。","山人草圣自豪雄，何事栖迟酩酊中。","年过五十无名位，其奈萧然沧海东。","砚屏颠倒乌皮几，落日垆头睡初起。","向壁凭陵小吏惊，据床挥霍郎官喜。","七闽大姓五陵儿，握粟持金岂顾之。","心同气合即挥洒，归卧山中无所为。","想当脱腕临池处，兴入寥天与神遇。","深沈铁绠锁寒蛟，偃蹇乌藤絓高树。","鱼丽云鸟势萦纡，疑是将军破骨都。","骖麟翳凤何飘忽，倏忽仙游蕊珠阙。","又如祇苑说空禅，灵花历乱迷诸天。","离丽落磊千万态，流水行云皆自然。","醒来不记濡头墨，千尺寒涛照眼白。","淮海仍传宝晋风，长沙复见藏真迹。","黄山茆宇思悠悠，柿叶青青覆酒楼。","白头未遂中书贵，风流亦似醉乡侯。"]},{"t":"黄氏小圃","f":"七言古诗","c":["汉阴丈人心不羁，生小灌园无是非。","宁辞白发常抱瓮，大笑傍人皆用机。","吾观夫子偏同调，未肯逢时发哂笑。","五十仍无簪冕荣，半生独得丘园妙。","君家累叶尚高节，太华三峰见秋月。","仙都白首卧松云，官署清风洒兰雪。","霜露凄凄薄故林，几回风木感情深。","疏灯细雨怀亲梦，白石清池养道心。","药栏花径青山下，若比平泉更潇洒。","清斋时对去官人，习静长留采芳者。","涧水世事日灌园，浮云世事不须论。","从教纨绮轻荷叶，不分膻腥薄菜根。","有时兀坐榕阴里，悠悠目送孤鸿起。","向人不饮少陵杯，开口常轻马迁史。","燕綵堂深日日春，来清堂上好娱宾。","嗟予江海流离客，愧尔林泉淡荡人。"]},{"t":"题邑造士吴中美胡山书室","f":"七言古诗","c":["邺侯架上书如积，金薤琅玕映奎壁。","纵横断墨莽多岐，浩荡真源了无迹。","延陵书舍带湖山，湖上书声掩霭间。","闭户不知秋叶落，卷帷或见暮云还。","山童洗砚春池黑，仙侣吹藜夜烟白。","半榻清晖草带间，一帘风露芸香夕。","青春衣綵尚趋庭，永日琴尊复聚星。","吟边狭水牵长镜，醉里青天扫画屏。","几年在泮非常调，犹未携书发西笑。","心迹空冷鱼鸟知，文章已作簪缨料。","同辈纷纷似子稀，诵诗三百解人颐。","愁君便逐青云去，谁共山中薜荔期。"]},{"t":"送别陈思孝赴天京兼寄董郑二先辈","f":"古风","c":["沙口柳条色，沧波断归鸿。","君承紫泥诏，西上蓬莱宫。","忆君久抱干将器，三尺鹈膏未曾试。","君不见骅骝叱拨人岂知，一蹴方看小千里。","黄金不独累层台，宣室犹闻此夜开。","郭隗已知天下士，汉文偏爱洛阳才。","只今四海同车辙，万乘宵衣候明哲。","报主应怀国士恩，承家莫负郎官节。","郑虔况是槁门客，早晚龙池道相忆。","仲舒三策已成名，阙下相逢亦寄声。","青丝白马金陵道，酒幔河桥对春草。","天朝此去故人多，江海谁怜布衣老。","舟从故里莫停桡，春水桃花半落潮。","自惭落拓空华发，看尔飞腾上赤霄。"]},{"t":"筹峰歌为长乐尹王道斋赋","f":"古风","c":["海上群峰一峰别，群山向下如丘垤。","云开华顶见琉球，天尽沧波带吴越。","元气鸿濛湿不飞，凉霜五月袭人衣。","迥临飞鸟空青外，始识筹峰天下稀。","石林阴洞何冥密，万籁天声散秋色。","南涧飞泉鹤梦清，太阴积雨龙漦白。","我闻伸蒙子，云卧清晖里。","一旦金马门，名高此山水。","忆昨伸蒙骂贼时，悠悠往事亦堪悲。","支离一代忠臣义，感激千秋达士知。","郎官作县先名节，独访遗踪吊前列。","载酒唯浇石上苔，回鞭不醉山中月。","东山歌酒兰亭笔，疏散当年竟何益。","愿君遗爱比桐乡，功名记在筹峰石。"]},{"t":"送长乐林彦衡之嘉禾文学","f":"七言古诗","c":["先生考满家尚贫，十年坐见淮山春。","一官今来未得意，匹马东还喜拜亲。","君家世业多文献，堂上储书万馀卷。","腹中琅玕不自矜，宛西骐骥令人羡。","承恩今复教吴中，禄薄官卑道益崇。","铜墨相逢皆磬折，衣冠骈立竞趋风。","闽天九月秋萧索，寒叶吹霜雁边落。","垆头酌酒醉黄花，大堤凉月照金沙。","金沙堤上愁为别，一片孤帆度江浙。","若遇三衢见故人，为言白发镜中新。"]},{"t":"题张师夔木石","f":"七言古诗","c":["荒村怪石连树根，古苔蒙茸野棘繁。","蛟龙腾空虎豹蹲，寒霜落月啼清猿。","石门窈窕通仙源，我欲飘飘绝世喧。","栎山老人无复存，往往人间惊墨痕。","梦著银箫亦断魂，垂萝飞鸟如可扪。","石泉泠泠洗心言，白云飞来谁与论。"]},{"t":"赋得鹤山访旧送别余缓自军中还温陵寻许秀才","f":"七言古诗","c":["余生笑结曼胡缨，许子衣褐应逃名。","绿波芳草怨离别，渭树江云今古情。","昨夜城头吹笛声，相思起听落梅行。","梅花江上潮空白，黄鹤山中月自明。","石田茆舍温陵上，饭稻看书亦疏放。","去日儿童半白头，旧时猿鹤今无恙。","念此令人思转悲，乡心已挂刺桐枝。","明朝疋马温陵道，不负秋风鸡黍期。"]},{"t":"送李浩复永宁","f":"古风","c":["对酒击长剑，男儿重横门。","行骑紫缰马，笑结曼胡缨。","常思肝胆沥，竟未嫖姚识。","时来激忠愤，身与鸿毛掷。","尔今年少才堪数，远逐旌麾在行伍。","幕下还教重阿朦，军中已见留孙楚。","七闽自是古秦封，今日温陵镇尚雄。","时平瘴海无边警，天尽琉球见远峰。","往来射猎寒沙碛，住久翻忘异乡陌。","紫荚花深骑影迷，刺桐叶暗炊烟积。","昨日单车奉檄归，过门应得访庭闱。","暂随旅雁云边落，又逐征帆海上飞。","燕然北去南交趾，石刻铜标今尚尔。","为报边头将士知，丹青好在云台里。"]},{"t":"书三山奇观图","f":"七言古诗","c":["七闽山水多奇胜，秦汉封疆古来盛。","无诸建国何英雄，赤土分茆于此中。","荒城野水行人度，细柳青榕旧宫路。","浮世空歌逐鹿时，断矶不辨屠龙处。","忽从图画见三山，正在无诸故垒间。","丽谯官署人烟积，塔庙琳宫野照閒。","琳宫塔庙相辉映，平远清泠海天迥。","落叶霜传鸟外钟，垂萝月隐烟中磬。","东城西郭骑纷纷，旌节朝朝候使君。","谁拂尘衣访仙迹，独淩三岛望孤云。"]},{"t":"送释大冶归省还西塔兰若","f":"七言古诗","c":["西峰塔影连青汉，天半铃声度飞雁。","朝散灵花世界香，夜悬灯火星河烂。","此僧年少著袈裟，手持木杖口楞伽。","身寄空门如槁木，心将秋水植莲花。","两峰宴坐谈空寂，何事家山动遥忆。","定里啼乌返哺声，别时春草忘忧色。","学道由来不顾乡，道成应复念高堂。","衲衣暂借斑斓舞，寿酒唯倾般若汤。","清风溪上回轻舸，红叶吹霜向人堕。","愿结三生石上期，只恐他生复无我。","此别悠悠几日逢，回风暮雨送行踪。","孤云野鹤悠悠去，目断金鳌一片峰。"]},{"t":"送华石上人还樵阳西塔","f":"七言古诗","c":["金天向西多佛祖，宝筏东来多梵语。","直指单传悟者稀，沙门衲子徒辛苦。","初闻祇苑布黄金，复有袈裟入少林。","夜雪齐腰将见性，霜刀落臂始安心。","西峰法侣多僧气，曾与空门掌书记。","半偈应超最上乘，万缘只合西来意。","白云乡馆去迟迟，忆得从前别母时。","今日重寻故园树，几回落叶又抽枝。","秋风野水黄花路，浮世相逢偶相聚。","玄度清谈不复期，道林笑别知何处。","去去沧波难重陈，青山明月与谁邻。","连天塔影空青外，唯将法雨谢时人。"]},{"t":"题会稽吴汉津远游卷","f":"古风","c":["骥足小千里，鹏飞搏九州。","唯应星轺使，得以穷周游。","騑騑四牡今何往，秦汉山川古风壤。","圣主恩绥下国时，王人位列诸侯上。","官船昨夜广陵秋，二十四桥闻棹讴。","长淮柳色迷津吏，一片扬州带驿楼。","单车又发闽关道，九曲溪山旧来好。","沈剑波深历历云，钓龙矶断青青草。","君不见主父西游久不归，苏秦金尽故交稀。","宁持使节衔君命，出入臣藩复帝畿。","春风太液花如雾，夜月瀛洲访仙侣。","白下亭西卖酒家，凤凰台北吹箫处。","故园迢递会稽山，镜水仙舟也梦还。","若使功成拂衣去，此心长在五云间。"]},{"t":"奉寄浮丘郑助教兼柬董记室","f":"七言古诗","c":["西胶博士金门客，白马青袍夹城陌。","天池种藻上林花，身受皇恩不顾家。","春风几见桥门柳，禄米唯应足沽酒。","囊无一物寄妻孥，箧有空书示僚友。","忆昨骊驹未别乡，新宁山水竞风光。","县人争揖芭蕉馆，墨客都寻柿叶房。","六平山下秋同屐，半占峰南夜联席。","别后相思何处寻，凤台碧草连天色。","王门记室最情亲，官暇相过德有邻。","飞札定应思漫士，因风也或寄樵人。"]},{"t":"答黄嗣杰兼柬王介轩先辈","f":"古风","c":["沙馆忽归梦，枫州空月明。","与君别来凡几日，相思不觉闻秋声。","来清小苑霜初肃，扶留叶大甘蔗熟。","青山绕舍云半间，黄菊吹香酒千斛。","瀛洲仙侣久忘机，昔时骢马今布衣。","共君兄弟日携手，閒看孤鸿天外飞。"]},{"t":"书漫士为陈拙脩绘沧洲别墅","f":"七言古诗","c":["金堤沙北镜湖东，前窥筹岭后炉峰。","沧洲老人年七十，朝朝宴坐于其中。","葛巾竹杖何萧散，卧爱清晖不知晚。","魏阙青云梦里过，谢池碧草吟中满。","五岳仙游去路深，击鲜子舍费千金。","如何白发沧洲上，野鹤閒云一片心。","龙涎酒盏鸬鹚勺，远胜仙家大玄酪。","送客天明水鸟啼，弹弦夜静檐花落。","龙门高士扫新图，挥霍霜毫倒墨壶。","京国浮丘亦知己，题诗早晚寄东湖。"]},{"t":"送林彦衡子婿游汉赴嘉禾吉期","f":"七言古诗","c":["蜀葵初黄柳飞雪，棹歌声里行人别。","别思空随海上波，客心已醉吴中月。","嘉禾山水盛繁华，才子今游若到家。","金屏射中双栖鸟，红烛争开并蒂花。","问君今年二十几，大颡疏眉有如此。","少君不愧鲍家郎，乐广应期卫公子。","冰玉相亲情更多，泮林官况近如何。","为言白首甘藜藿，岂望青云到薜萝。"]},{"t":"空江秋篴浮丘郑助教索予赋之","f":"古风","c":["桓家野王弄秋玉，流落秋亭半枝竹。","君山老人何处归，梦入潇湘洞庭曲。","浮丘仙客五湖心，复向沧波学凤吟。","不吹玉塞梅花调，不奏青楼杨柳音。","商声迟迟羽声急，寒苇飞花露香入。","水灵解佩撇波来，山魅吹灯倚云泣。","万事无心一叶舟，夜寒星斗落船头。","数声绝岛鱼龙曙，三弄澄潭雁鹜秋。","初闻凤在冈，倏尔鼍吟水。","天籁风泉何处鸣，落木寒狷一时起。","浮丘子，通灵仙，汗漫终悬魏阙情。","曲终又欲蓬莱去，日抱云璈朝玉京。"]},{"t":"酌陈师贡","f":"古风","c":["云卧碧溪里，别来凡几春。","口中独未言声利，身上何曾染市尘。","君家兄弟多逢掖，吐论遥轻二千石。","高蹈宁耕数亩田，折腰耻作诸侯客。","倾盖逢君惜未深，见君同调复同心。","祗今交游重朱绶，何人贵义轻黄金。","世人共笑悠悠者，击刺狂歌孟诸野。","万事秋空一片云，得钱且醉黄垆下。","闻道朝廷礼数优，衣冠阙下尽名流。","爱君更欲君先达，顾我沧江空白头。"]},{"t":"耽犁子歌为长乐郑友众赋","f":"七言古诗","c":["新宁才人心不羁，腹中三礼犹耽犁。","生事常怀汶阳北，梦游未识灞陵西。","青山白野閒来坐，离黍吹花向人堕。","潇洒还同谷口耕，风流也学南阳卧。","谁知宣室聘雄才，不使遗贤滞草莱。","使者飞书催上道，郎官立马送离杯。","几回待诏金门里，枥上华骢末由试。","甲第歌中少故人，五侯宾从无知己。","以兹翻忆鹿门春，却向清时便乞身。","匹马行辞白门柳，群公饯出秣陵尘。","故园独树闽川道，数亩山田半秋草。","孺子应知食力安，渊明况及归来早。","入门长啸复长歌，仍把春衣换薜萝。","自言林下耽犁好，不道天朝荐剡多。"]},{"t":"题高漫士为王明府绘吴航胜览","f":"七言古诗","c":["无诸故国新宁县，西控雄藩古侯甸。","文物遥通汉职方，河山旧入秦封建。","霸气荣光几百秋，卉衣椎髻变中州。","清朝礼乐弥寰宇，比屋弦歌见鲁邹。","六平远树烟中出，百里清晖趣非一。","一片沧波海屿秋，千门霁色扶桑日。","沧波东逝日悠悠，忆昔英雄驻采舟。","御国归龙何处在，太常云去至今愁。","伸蒙岩头桂香晚，中丞石上苔花满。","陈迹空馀野鸟飞，英声不逐浮云散。","我侯远抱连城璧，僚佐相辉应籍籍。","近郭行春露冕时，古台下马弹琴夕。","风流墨客龙门士，挥霍霜毫寄深意。","都将胜槩纪方舆，更喜贤侯重民事。"]},{"t":"白马篇","f":"古风","c":["宛马如雪色，青丝鞴来好。","五陵侠少年，骑向长安道。","长安道上花正香，吴姬垆头红粉妆。","翩翩白马系高柳，据坐胡床唤酒尝。","自矜出入金门里，立在殿庭谁敢视。","武皇升天去不归，人马萧条翻被欺。","不及田翁学种谷，日日村中抱黄犊。"]},{"t":"老将行","f":"古风","c":["生小事边州，罢归头尽白。","玉门逻逤别来深，云鸟鱼丽旧曾历。","三尺吴钩两斛弓，絓在閒门高阁中。","羽林一二少年辈，昨日封侯欺老翁。","翻思战场里，秋霜断人骨。","髑髅夜夜声满天，尽是长平旧降卒。"]},{"t":"长相思","f":"古风","c":["长相思，相思春复秋，秋风扑帘霜入楼。","卷帘见月令人愁，鹤关音信长悠悠。","络纬夜鸣声断续，梧桐萧飒寒棕绿。","秦筝独抱咽繁弦，为君弹作相思曲。","相思复相思，思君君不知。","愿为鸳与鸯，双飞向天池。","岁岁年年无别离，君不来，长相思。"]},{"t":"行路难","f":"古风","c":["古镜蟠龙野苔色，赭颜欲改青须白。","三尺鱼肠烛下看，玉壶击碎心未寒。","悠悠漳水轮台树，信陵平原渺何处。","骑射纷纷杜宛儿，骄嘶紫燕跃青骊。","铜驼陌上春风煖，田窦门前客应满。","白头执戟不迁官，尽日草玄门自閒。","雪风萧萧面如割，史云桁上无全褐。","君不见羊肠九折坂，覆辙相寻岁华晚。","君不见瞿塘滟滪滩，败蓬如舞落惊湍。","田文失势冯驩去，廷尉门空鸟啼树。","二君所见何太迟，署门谢客徒尔为。","食客满堂尽珠履，剖胆输肝竟谁是。","阶前车马若云屯，倏忽苍苔生满地。","感激令人气不平，中宵起坐待天明。","唯有君家梁上燕，秋去春来无世情。"]},{"t":"东楼歌","f":"古风","c":["东楼美酒黄金杓，客子迎霜葛衣薄。","西楼朝饭盘有鱼，客子家林无斗储。","他人方寸那堪托，倾倒三杯吐然诺。","咫尺相看隔九疑，不待明朝异山岳。","君不见牙签缃帙满床头，不及雷塘百亩秋。","君不见诵诗三百徒为尔，秦青一弄倾人耳。","沧波去去堪乘兴，野鹤孤云本无定。","毛生自荐祗徒劳，鲁连岂顾千金赠。","行路难，难重陈，史云只合长苦辛。","落拓还骑少游马，往来嵩华青山下。"]},{"t":"代闺人答轻薄少年","f":"古风","c":["繁华啸芳年，蔓草对幽思。","妾本赵燕姿，误身任侠子。","长安任侠矜少年，五花白马黄金鞭。","平明驰逐新丰市，日晚吴姬垆上眠。","玉骢一别知何处，可惜佳期梦中度。","筇竹丁香起暮愁，枕屏十二巫山雨。","落尽冬青犹未回，转头黄叶委苍苔。","空帘尽日无人见，寂历黄昏月又来。"]},{"t":"水墨鸲鹆","f":"古风","c":["山鸲鹆，羽㲯毵，声断续。","不逐雌雄向空谷，何事孤枝抱寒独。","山桃野竹更芳菲，纵有虞罗也见机。","红香落尽忽飞去，深山古木行人稀。"]},{"t":"孀妇吟","f":"古风","c":["开箧见珠翠，思君前日情。","祗言恩爱长相顾，岂误音容隔死生。","东流逝水何时返，倏忽青天綵云散。","铜镜妆台不复窥，罗襦绣被荒尘满。","月明穗帐凉如水，灯火荧荧照虚位。","寂寞空帘鹊影閒，萧条穷巷虫声碎。","东邻车马如云屯，西邻歌舞日纷纷。","不羡他家夫妇好，宁甘守节在君门。","新坟峨峨倚山麓，春去秋来草应绿。","夜半伤心不忍啼，天明独抱孤儿哭。"]},{"t":"送陈沧洲游浯水便登方广岩","f":"七言古诗","c":["闽山西来多法园，溪西一道通仙源。","林花贝叶相辉映，道林凿齿皆清言。","遥岩二月霜花积，千丈垂萝袅烟碧。","水帘风卷半空寒，石室云来万山白。","真僧不见宾头卢，片月孤峰色相癯。","六时天乐闻钟磬，百尺风潭写画图。","仙舟此别饶佳趣，岂学悠悠向平去。","林僧定扫壁间苔，山人况有惊人句。"]},{"t":"书闽宪淮安陆公骢马朝天卷","f":"古风","c":["骢马新凿蹄，翩翩锦障泥。","朝鸣柏台下，莫走金陵西。","金陵西上连双阙，白门秋风桂香发。","手中玉斧绣为衣，马上霜威面如铁。","故园淮水望犹赊，心念王程不顾家。","阊阖九重归使节，炉烟咫尺诵皇华。","朝回月隐南宫树，梦里犹听七闽雨。","一道风霜露冕时，几年红海星轺曙。","圣主恩深念远臣，穷荒今日赖咨询。","功成毕竟登台辅，应继贞元第一人。"]},{"t":"题新宁陈叔谟留耕别墅","f":"七言古诗","c":["识子青年未官禄，闭户看书心亦足。","南亩东皋厌远寻，退耕却在灵台曲。","灵台一道自通天，中有冷冷几窍泉。","犁牛钱鏄知何用，仁作春苗义作田。","大田多稼多为尔，岂必流传到孙子。","何似君家方寸中，子孙食力垂无穷。"]},{"t":"奉赋佥宪陈公鹤峰亲舍","f":"七言古诗","c":["柏台使者金门吏，家住惠阳万山里。","青山历历孟家邻，乔木苍苍郑公里。","黄鹤连峰入翠微，白云亲舍对清晖。","山厨日送茅容膳，野服时逢莱子衣。","别来久矣怀乡国，身受皇恩归未得。","林鸟频闻返哺声，萱花几变忘忧色。","七闽露冕肃秋霜，揽辔唯应忆范滂。","会使乡人看昼锦，惠阳山水有辉光。"]},{"t":"题张少尹淳溪燕居卷","f":"七言古诗","c":["溧阳咫尺金陵道，行人尽说淳溪好。","美髯公子未归时，饱食河鱼饭粳稻。","公子青年气最豪，身长七尺锦宫袍。","清寒玉露金茎直，萧洒云天海鹤高。","别来倍忆淳溪柳，密叶青青覆虚牖。","爱日堂中五綵衣，春风席上连枝秀。","三年佐县得哦松，官舍萧然多好容。","应待乡林归省日，又从霄汉沐恩浓。"]},{"t":"赠黄典幕修筑堤防","f":"古风","c":["君不见召公埭白渠，叔敖郑浑功最殊。","年丰粒米多嬴馀，闽州属县沧海隅。","筑海为田农力劬，炎风赤日秋草枯。","漫漫斥卤连荒芜，民饥不足供王租。","我公到来人复苏，鸠工筑防备不虞。","滨涧严湖水可潴，污邪瓯窭变膏腴。","禾黍油油接桑榆，公田有谷兵有储。","春风二月花满途，村北村南开酒垆。","黄堂白叟但劝娱，驯雉不惊雄哺雏。","红莲宝幕瑩冰壶，玉树掩映青珊瑚。","讼庭无事鞭用蒲，功归令尹名不沽。","政成秣马朝京都，便当发轫青云衢。","愿作霖雨霈九区，非但小邑蒙沾濡。"]},{"t":"赠照磨瑞桃歌","f":"七言古诗","c":["成周嘉禾纪王瑞，一茎芃芃连九穗。","汉家宫殿发灵芝，金光晔晔生铜池。","紫文缃核浮香来，复见君侯府庭内。","王母仙根岂浪传，玄都佳种今犹在。","繁花并蒂玉交柯，异体同苞孕太和。","非关雨露生成别，自是公门佳气多。","红莲幕下开仙馆，何必天台羡刘阮。","鹦鹉斜飞不敢窥，祥乌欲下空偷眼。","锦袍朝觐又承恩，采摘唯应奉至尊。","宸居玉食天齐寿，九节昌阳何足论。"]},{"t":"送闽县尹松江张公秩满之天官","f":"古风","c":["吴苑梨华赤，关闽霜度时。","輶轩首京路，蹀躞嘶青骊。","郎官旧隐松江口，门前种得先生柳。","忽逢明主垂衣裳，肯使遗贤滞陵薮。","三年制锦动香名，千丈澄潭照眼清。","日与同官俱坐啸，顿令豪吏尽销声。","君家文献非常调，健笔雄词世应少。","卓茂何妨密县卑，鲁恭岂谓中牟小。","凤台西上雪花飞，琴鹤翩翩也自随。","云霄相逐夔龙远，留此甘棠去后思。"]},{"t":"歌行奉饯闽守姑苏陆公秩满之京","f":"七言古诗","c":["吴门山水多奇秀，使君独继宣公后。","锦袍新绣鹭丝纹，银印低垂虎头绶。","闽城官柳拂双旗，花里行春五马迟。","讼庭几度闻鸣鵙，仙馆三回见荔枝。","功成又欲朝京去，远心已絓南宫树。","枇杷开花鸿雁霜，此时正及乡山路。","车傍父老持百钱，马上同官惜别筵。","寇恂好借留河内，黄霸终须出颍川。","金陵客舍春还早，快马轻裘满驰道。","使君行箧但萧然，唯有贞元谏书草。"]},{"t":"赠闽藩参政永嘉杨公秩满之天官","f":"七言古诗","c":["春闱战胜得名香，锦袍白马尚书郎。","景星流辉焕霄汉，鸣凤展翼翔朝阳。","承恩出入蓬莱殿，天子殷勤寄方面。","七闽父老候幨帷，八郡诸侯拜车传。","无诸旧国古雄都，更喜明公遂剖符。","千寻泰华悬秋月，一片清冰烱玉壶。","忆从西笑离乡陌，雁荡天台梦中碧。","恋国常思沥寸忠，匡时每欲陈三策。","三年报政出闽藩，千里趋朝觐至尊。","好留召伯甘棠惠，应沐周王湛露恩。"]},{"t":"赠闽郡别驾江右传公考满之京师","f":"七言古诗","c":["豫章才子龙门客，别驾闽州声籍籍。","春帆曾食汉家鱼，秋灯几听南雄笛。","王程迢递不辞难，守道何妨未转官。","白云片片乡山远，风木萧萧陇日寒。","银妆束带乌纱帽，锦作朝衣紫鸾诰。","佐郡长悬魏阙情，归骖又指吴门道。","江亭把酒别同僚，卢橘花深惜去桡。","南宫此度非常调，应接鹓鸾上九霄。"]},{"t":"题陆太守瞿塘日暮图","f":"七言古诗","c":["白帝城头乌欲栖，瞿塘峡里暝猿啼。","山通剑门峨眉远，水落荆门郢树低。","公孙旧业知何处，十二危滩虎须怒。","雁飞愁度百劳关，行人畏到三巴路。","绝壁连峰马道赊，石林残照几人家。","垂萝夹岸迷天影，午夜沧波逗月华。","巫阳缥缈望中开，行雨行云尚有台。","山花不省襄王梦，野鸟何知宋玉怀。","岷江一道向西来，蜀客帆樯逦迤回。","洪涛有时不可下，滟滪当头大如马。","纷纷世路羊肠曲，岂独瞿塘骇心目。","尽知险处重周防，谁肯安流虑倾覆。","使君高谊轻常调，吏散披图但长笑。","明朝身到五云端，下见瞿塘一杯小。"]},{"t":"赋高漫士适安堂题于方壶所寄画","f":"七言古诗","c":["小隐翻成大隐媒，终南捷径近蓬莱。","君家草堂独萧洒，半占峰南松际开。","草堂松际秋声里，四壁清晖映乌几。","卷幔朝眠日出高，野鹤孤云祗如此。","孤云野鹤澹忘形，嬴得丘园养性灵。","飞腾未应郎官宿，嘉遁犹当处士星。","吟诗作画多閒放，心迹悠悠古人上。","玩宇天空豁远怀，啸台夜雪闻清响。","王门记室旧交情，国子先生若弟兄。","清时共逐鹓鸾去，白首谁同鸥鹭盟。","顾余别是沧浪客，蓬荜相逢即相得。","对酒龙门月色秋，放歌鸡屿潮头白。","壶丘仙墨思纷纷，千里神交寄树云。","坐卧草堂时见画，知君不羡北山文。"]},{"t":"送刘宗实被荐之京","f":"七言古诗","c":["先生昔事李轻车，庙略纵横有奇策。","刀头见月夜飞鞍，楯鼻吹霜晓研墨。","露布军中论五兵，前锋校尉尽知名。","纵横出入龙骧幕，长揖经过骠骑营。","承平四海无烽燧，归卧东山兀然醉。","谁知鄂荐下青冥，又卷龙韬赴丹陛。","鸣驺拥路百花香，海燕初飞雁北翔。","分手独怜孙楚别，傍人休道鄜生狂。"]},{"t":"送凤阳开仲贞远省外父复归于建上","f":"古风","c":["客有佩长剑，行趋骠骑营。","入门拜旌节，冰玉仍双清。","门前系著青丝骑，冬青吹花香拂袂。","上马谁怜矍铄翁，东床正忆风流婿。","军中置酒气偏豪，红烛金杯虎帐高。","奴子平头摇羽扇，美人纤手送车螯。","家临帝苑长淮树，芳草萋萋望乡处。","又逢海水动离情，却指芝城是归路。","芝城梅水接蛮烟，两地惊心惜别筵。","自愧临行无可赠，何人更有绕朝鞭。"]},{"t":"感怀","f":"古风","c":["不弹贡禹冠，不结萧朱绶。","几处移家任转蓬，半生失路唯耽酒。","兔园挟策也徒然，欲逐长沮学种田。","秋风四面相如壁，旧物空馀子敬毡。","异乡沦落无朋友，论交昨日今何有。","误将偃蹇对时人，岂谓新知不忠厚。","万事萧然一布衣，白头梦想故山薇。","抱琴欲奏猗兰曲，目送云天一雁飞。"]},{"t":"偶书","f":"古风","c":["片善不敌金，万言一杯水。","谁为枯鱼叹，邈矣南华子。","今人结交希结心，古人贵义轻黄金。","麦舟与人不复见，捐廪轻囷何处寻。"]},{"t":"送别曾伯刚归青浦","f":"七言古诗","c":["太常峰南正雪飞，严公湖上梅初发。","遥天片日下沧波，断鸿声里人将别。","借问君家若个山，白云携得杖头还。","碧罗旧业连青浦，高卧心閒梦亦閒。","看君意气非常调，未肯逢时发西笑。","萍梗长留沧海踪，诗书不作青云料。","客里相逢情最亲，离居自愧家常贫。","旧游冠盖今谁在，白首襟怀有几人。","念君此行何草草，岐路吞声不能道。","遥传掬泪到麟峰，伤心为吊方山皓。"]},{"t":"题岐阳郑彦林家藏五马出浴图","f":"七言古诗","c":["天皇雪消冰始开，天寒赐浴皆龙媒。","奚官剪拂荷君宠，为惜流沙大苑种。","房精夜照荣河水，灵物蜿蜒尽飞起。","春雷十日绕龙池，赤骠骅骝电光里。","唐家天上宴连枝，花萼楼前初鞴时。","红缨并逐仪鸾去，七旒双旌何足奇。"]},{"t":"送林七洙省亲之休宁","f":"七言古诗","c":["无诸城头春雪飞，臈酒未醉缝春衣。","独怜游子江东去，正值关河雁北归。","江东远树徽州出，羡尔王浑得官日。","白首虽寒博士毡，多才已判文衡笔。","前年买棹问平安，南浦东江正采兰。","新安到后枇杷熟，闽徼归时络纬寒。","还家三径秋声早，故垄松楸不堪扫。","有泪空悲二弟殇，多情更忆双亲老。","兹别蹉跎几度霜，频将飞梦绕高堂。","沙头见月长回首，天畔怀儿更断肠。","儿今亦是儒林秀，寺簿云孙少卿后。","玉堂文献故家声，鱼佩金龟虎头绶。","鲤也青年曾过庭，诵诗三百未成名。","担簦别墅稀同调，记室王门得从兄。","青骊又指宁家处，不比王阳去时路。","山城小店越人烟，夜火残钟楚关树。","千里迢迢候起居，家人日夕念双鱼。","到时早觅新安使，兼寄皆山樵者书。"]},{"t":"长歌赠别高漫士赴召天京","f":"古风","c":["故人垂钓沧浪矶，故人雄词天下稀。","故人今辞?鹤去，手持白璧登王畿。","白驹皎皎离空谷，振鹭飞飞出林木。","晨劳睿想叹淩云，夕感宸衷梦操筑。","虽云耕种食为天，未许清时隐大贤。","薜萝旧结山中赏，符印今看腰下悬。","知子过吴会，所遇多同声。","为我道离别，相思但钟情。","五年顿隔浮丘面，昨日灯前梦中见。","八口相随赴辟雍，一官又转陪同辇。","鲁筵记室久分簪，前度书来怅远心。","几时走马山东去，汶水寒流兖树深。","当年共结渔樵伴，星离雨散肠堪断。","千里沧波一片云，东飞玄鸟西飞雁。","忆昔相逢乐事偏，沧洲堂上酒如泉。","题诗醉扫岩泉壁，枕籍山僧膝上眠。","此时欢乐应难再，屈指同心几人在。","云壑风泉半是愁，碧空片月悬秋海。","白头樵子真堪笑，落拓何曾迈常调。","握手频为倾盖欢，多情竟作分飞鸟。","闽州山水送离觞，荔枝垂花卢橘黄。","輶轩欲发逢梅雨，祖道骊驹不堪驻。","待子东门供帐时，我乘款段沙头路。"]},{"t":"书郑克刚云泉清隐卷","f":"古风","c":["伯阳居柱下，曼倩金马门。","大隐朝市间，玩世非避喧。","何如小隐云泉里，黄裳竹杖青丝履。","白云为伴去还来，石泉泠泠洗心耳。","云本无心犹为君，吟边卧内共氤氲。","泉飞隐处偏清响，雪夜凉天梦亦闻。","道人解作山林事，兴入丹青老将至。","一饭王门不愿留，归来岂负云泉意。","道人家本住西镛，何事因栖海上峰。","我欲寻山采芳去，云泉深处候高踪。"]},{"t":"夏日同龙门高漫士游棋山寺","f":"七言古诗","c":["逸人共结萧朱绶，六月闽天火云厚。","觞熟梅边告我行，欲行且尽垆头酒。","棋山海上古招提，银瓮丝绳兴复携。","三峰直下几千丈，仙人奕处清猿啼。","知君平生爱灵境，为君拂拭青萝影。","野殿杯浮蕙草香，石渠水浸甘瓜冷。","祇园树里贮行庖，暂解尘衣挂竹梢。","诗成破却山灵胆，醉倒倾翻老鹤巢。","回岩积翠连飞阁，遥海苍苍暮潮落。","舞影争嫌白日斜，歌声未道离情恶。","拟从方外寄馀欢，云是山僧谒县官。","野鹿回看避仙佩，沙禽何意讶儒冠。","千金流水犹能注，陌上离驹不堪驻。","愿君身到五云端，莫忘棋山送行处。"]},{"t":"赠严校尉复职","f":"古风","c":["还镇东校尉，家林若个边，桐柏苍苍际淮水。","居巢城下范增乡，放桀山前橐皋里。","忆昔军中独数奇，壮心每遇嫖姚知。","骑射曾矜羽林子，纵横不数并州儿。","时来忽领偏裨将，肘后铜章百夫长。","唾手封侯未有期，刮目逢人已相让。","霜蹄暂蹶气犹豪，雕鹗低飞铩羽毛。","孤营错莫三秋梦，一剑空馀百战劳。","升沈去去何须叹，圣主恩深迈刘汉。","始知燕颔岂徒然，莫把龙韬等閒玩。","银带雕弓匹马归，木棉花发鹧鸪飞。","夫人堂上收残泪，稚子门前捉锦衣。","闽州水镇梅花寨，祖道骊歌动江介。","酒尽沙头双玉瓶，幕中主将遥相待。"]},{"t":"和高漫士梅江谣","f":"古风","c":["梅江水，流浩浩，居人尽说梅江好。","自从海上筑城池，使车络绎无昏早。","梅江水，深复深，行人一见怀千金。","老夫平生爱江水，日饮一石无贪心。","青萝盘盘数峰色，兜高望见扶桑白。","蜃气朝凝鲛女宫，珠光夜照天吴宅。","居人生小住江皋，架壑梯岩结构牢。","沙鸥不省逢机事，江叟何曾识县曹。","峨峨百雉连山郭，夷岛清宁无摽掠。","将门子弟解逢迎，大侄儿郎谈礼乐。","有时江上渔歌发，捩柁抽向江空阔。","蹒跚竹篓紫蟹肥，拨刺金盘素鳞活。","龙门子，何处来，向予西指凤凰台。","京行此别三千里，怅饮应须数百杯。","谢公好为苍生起，山中猿鹤徒为尔。","到日秦淮有鲤鱼，尺书先寄梅江水。"]},{"t":"送鍊师张铭新归上清","f":"古风","c":["羽人重周游，踪迹半天下。","渡海窥蓬壶，寻云历嵩华。","朝登徂徕顶，夕眺琅琊台。","盘桓三珠树，酝藉九霞杯。","长生大道应无外，婴儿姹女遥相待。","金鹅结蕊养神丹，玄牝垂根长脐带。","学道何妨暂出山，收琴卖药到人间。","五侯七贵希相问，抱得瑶笙鹤上还。","还山宴坐璚林久，龙虎峰南一回首。","秋风入洞雁蹄霜，忽忆乡山菊花酒。","归来宛是辽城鹤，满面犹酣太玄酪。","仙歌未了泪纵横，残日潇潇陇树声。","谁知云水烟霞性，也动松楸霜露情。","寒冬别我无诸郭，遥指仙都在寥廓。","横天鹤影佩声微，惟见千山雪花落。"]},{"t":"高漫士为许宗显作山水图","f":"古风","c":["水墨有远态，醉来常讶真。","烛前瞥见三湘意，便欲牵裳行采蘋。","满堂飞翠疑可掬，眼花忽堕愚公谷。","主人捧觞我不闻，但觉啼猿与秋瀑。","林间巾舄如有情，谁向沧浪唱濯缨。","飒然片雨归彭蠡，恍惚孤云还赤城。","醒来始误双毫妙，我与龙门昔同调。","世人观画不观神，老夫兴在丹青表。"]},{"t":"许宗显椰子杯歌","f":"古风","c":["君家一双椰子杯，远从交广带将回。","剖开瘴水蛮烟腹，割断玄霜玉露胎。","乌梨木柄银錂口，若比匏尊应更厚。","莲房半侧碧筒深，中有黄流汎郁金。","最怜竹里泉中洗，不厌松边石上斟。","人言此杯能辟蛊，倾银注玉空论富。","少陵未许称木瓢，谪仙且莫誇鹦鹉。","山人心爱口不言，肯遗还山酌白云。","君不见丰城双宝剑，当年知己亦平分。"]},{"t":"王氏牧隐卷","f":"七言古诗","c":["山人不种亦不耕，买山放犊应逃名。","閒吹一曲无宫调，高卧千峰不世情。","瑶琴在床书在箧，河汾到君今几叶。","懒随时贵竞簪缨，耻逐浮人尚渔猎。","五月南风陂水深，白云将兴满山阴。","人牛看到相忘处，始是山人一片心。"]},{"t":"送陈孟敷牧潮阳","f":"七言古诗","c":["别久相逢不问官，握手且尽平生欢。","腰间金带懒不系，壁上虎符人自看。","醉来借问今何职，皂盖朱幡二千石。","郢上行人有去思，潮阳父老遥相忆。","作郡休令五马迟，须知明主爱茕婺。","行春鳄渚沧波晚，浇酒韩山落木时。","槟榔叶暗蛮天雨，吏散公庭鸟啼曙。","带印虽云案牍劳，怀人莫忘渔樵似。","樵人偏辱使君知，为惜交情在布衣。","他日诸郎如问绢，应传清节到林扉。"]},{"t":"书邓子静耕隐","f":"七言古诗","c":["阿翁隐处何潇洒，竹屿南头凤丘下。","守道偏将谷口人，养拙应同汉阴者。","而今发白老丘樊，带经也或究微言。","生平不梦五陵道，嘉遁羞过七贵门。","世人未解此翁意，此翁心迹孤云是。","低头不肯揖陈蕃，食力何曾愧徐稚。","脱略凡机无世情，幽人野鹿伴经行。","秋风别墅黄花酒，夜火山厨绿芋羹。","有时濯足苔溪晚，放犊寒陂不知远。","几片青山荷蒉歌，半林落叶同僧饭。","盘石悬萝地更偏，独携高兴寄秋田。","且喜琴书应有托，蔡邕虽老仲容贤。"]},{"t":"海上酬三峰诸友","f":"古风","c":["晚家大堤曲，几见大堤春。","开门对三峰，宛若平生亲。","别来沧海东，倍忆三峰好。","眼前不见同心人，梦飞只在三峰道。","早晚归来大堤曲，三峰垆头酒应熟。"]},{"t":"山水扇头","f":"楚辞体","c":["山苍苍兮白云，谷窅窅兮夕氛。","鸿高飞兮远逝，蝉薄暮兮空闻。","汎木兰兮容与，隐薜荔兮氤氲。","纷吾老兮既拙，担相从兮夫君。"]},{"t":"题梁氏家藏十牛图","f":"古风","c":["渴莫饮污渠水，饥莫食衰草根。","孟诸桃林春正绿，洞庭笠泽多清源。","五侯枥上皆骢马，笑杀田翁事耕稼。","阴山劲卒气偏豪，几日销兵卖宝刀。","群行聚散无迹远，遥望长洲日将晚。","不闻宁戚歌，不见百里奚。","猛虎当头向前去，空村尚有绿林儿。"]},{"t":"答陈伯坚蝤蛑并诗见寄之作","f":"七言律诗","c":["郭索蹒跚隐深泽，百尺寒丝谁钓得。","双鳌落刃碎青霞，满壳流脂泛金液。","感君特寄到沙堤，竹篓乘来不涴泥。","尊前正值霜橙熟，堪笑吴王一蟹低。"]},{"t":"书陈果之阜阳亭","f":"七言古诗","c":["阜阳山水多佳致，亭子幽幽翠微里。","雁池梓泽不须论，绿野平泉只如此。","平泉绿野多乔木，未胜君家阜阳曲。","书幌遥临雪海青，饮缸倒浸南山绿。","石门沙岭竹边房，同谷方池映橘霜。","霜煎夕照松声远，云际飞泉月影凉。","耕童牧叟閒来去，草衣笋笠还朝暮。","主人尚拟鹿门居，坐客都迷辋川野。","羡君三十著儒衣，潇洒亭中独下帷。","殷勤且毕青云事，他日还应画绣归。"]},{"t":"书倪氏经锄堂","f":"七言古诗","c":["西邻无牛长苦辛，东邻多牛今家贫。","儿孙生小不识字，头白终为畎亩民。","君家累叶皆儒雅，岂学邻翁但耕稼。","数亩荒畦手自锄，一卷遗经坐仍把。","厨中有粟床有书，万事浮云心澹如。","向人懒掉仪秦舌，避世翻轻沮溺徒。","方今圣代多推毂，玉帛戋戋贲幽谷。","我亦休耕汶上田，与尔相期在乔木。"]},{"t":"澄清歌为闽宪佥孙公赋","f":"古风","c":["骢马何处来，翩翩下霜台，七闽大道无尘埃。","袖中明月连城价，腹里琅玕柱石材。","闽山青峨峨，闽水净如练，露冕巡行历州县。","手持白简绣作衣，胆落金吾铁为面。","佐理由来有政声，纲纪百粤共澄清。","清如金茎云间之露白，澄似冰壶秋夜之月明。","山亦收其雾，川亦敛其滓，泰阶荧荧悬六星。","秋毫遥遥洞千里，列郡官曹亦如水。","忆昨霜威遍齐鲁，汶阳泰岳沾时雨。","又持玉节按闽荒，乡心几度梦浔阳。","方今天子多殊渥，暂遣遐陬访民瘼。","早晚功成列上台，令人更忆孙弘阁。"]},{"t":"题小米水墨","f":"古风","c":["寒山深，白云萧萧枫树林。","岚烟瀑雨生衣簪，绿萝袅袅悬我心。","灵源中，石齿齿。","散发轻舟弄云水，欲得风飘洗双耳。","茆屋荒冈绝四邻，青林残叶少行人。","苔边僧磬连孤鸟，竹里仙家隔素尘。","布衣未了生平事，愧尔双毫写幽思。","白头遥想米家风，梦落濡须墨池里。"]},{"t":"送郑克复睢阳军","f":"古风","c":["空山忽鸣鵙，露白秋草寒。","离居感物候，况有行路难。","从征睢阳里，饮马黄河水。","孤剑二十年，寸心五千里。","朅来问乡馆，捧檄仍徵兵，戚戚慈母恋，依依兄弟情。","行当辞复去，悠悠念王程。","黄云白雁秋萧索，野水西风汴城郭。","洛苑初霜赤叶飞，大梁古道黄花落。","戎衣此去勿迟迟，莫向清平叹数奇。","白头好遂还乡计，姜被重欢綵重戏。"]},{"t":"送林洙之徽州省亲","f":"七言古诗","c":["去年沙头柳堪折，与尔严君惜离别。","今岁沙头复送君，柳条拂面花如雪。","新安今去问平安，莫叹严君尚冷官。","胡瑗由来布衣士，郑虔不厌坐毡寒。","看君亦是奇男子，白面疏眉有如此。","怀里琅玕人未知，手中结绿谁堪比。","别后秋风归未归，他乡应复念慈闱。","经过莫上滕王阁，辛苦须缝莱子衣。"]},{"t":"连江陈氏春晖堂","f":"古风","c":["谖花媚凉秋，慈竹后霜色。","春草同生雨露荣，寸心莫报阳春泽。","以兹感激念春晖，薄俗如君孝养稀。","三时每供茅容膳，五色都缝莱子衣。","他人朝夕唯甘旨，温凊何曾得亲喜。","菽水而今不尽欢，萧萧风木徒为尔。","知君閒门野水滨，青山独树孟家邻。","清时正尔观风教，锡类唯应及里人。"]},{"t":"书渔樵耕牧四画 其一","f":"七言律诗","c":["扁舟夜唱沧浪曲，朝饭兰皋爨湘竹。","垂杨轻拂鲤鱼风，千丈春潭晓未绿。","日暮双双得紫鳞，渔家生计任长贫。","豪门绮席银丝脍，愧尔渔郎多苦辛。"]},{"t":"书渔樵耕牧四画 其二","f":"七言律诗","c":["山人岂是悠悠者，何事樵歌孟诸野。","萧条茆舍住寒村，生小何曾识县门。","东邻作商走风雪，西家为郎叹离别。","人生未必胜樵夫，朝朝暮暮对妻孥。"]},{"t":"书渔樵耕牧四画 其三","f":"七言律诗","c":["石田新雨苔花碧，禾黍秋香百馀石。","谁教酿作瓮头春，醉里看山了残帙。","读书何必问时清，纵有荒年莫废耕。","鹿门精舍青山里，春去秋来无宦情。"]},{"t":"书渔樵耕牧四画 其四","f":"七言律诗","c":["耕童生小无所知，惯骑牛背度晴陂。","横吹紫竹无宫调，笑杀五陵游侠儿。","荒林野水凉萧瑟，山叶吹霜鸟边落。","信陵坟上草青青，几见残碑砺牛角。"]},{"t":"书岱峰先墅卷为邑曹掾陈氏作","f":"七言古诗","c":["岱山连云转林麓，中有山人旧书屋。","春风独树孟家邻，垂萝野鸟愚公谷。","山人去后馀泉扃，落木寒猿那可听。","阶藓犹存故行迹，檐峰不改别来青。","后人戚戚悲霜露，竟日凄凄感风树。","啼鸟空闻返哺声，白云况是关心处。","寸禄休嗟名位卑，多才又喜际明时。","萧曹事业应须继，林壑光辉会有期。"]},{"t":"题陈沧洲家藏王甥至之山水图","f":"七言古诗","c":["公乃王郎之舅氏，昔年遣兴沧洲趣。","白水应同万古心，青山不尽平生意。","初疑衡霍乱峰回，石廪芙蓉天上开。","又疑瀑布香炉顶，飞红沓翠空中来。","连林杂树纷隈澚，屋头清晖霁人目。","片片春云带鹤还，淙淙野水流冰绿。","云间鸡犬更谁家，云际风泉半落花。","回岩积霭天梯小，绝壁悬萝鸟道斜。","白头久叹同声远，临水看山梦犹懒。","濯足矶边月自明，弄琴石上苔应满。","不见羊昙四十春，西州云物几回新。","丹青此日堪惆怅，岂必山阳笛里人。"]},{"t":"屿南林公谷寿自号云外道人上清方壶为写茂林云外图索余题其上","f":"楚辞体","c":["屿南山水新宁少，况是君家茂林妙。","林间潇洒薜萝衣，双舄飘然淩翠微。","连岚过雨看城黛，片片云来度沧海。","谁识孤云是此心，此心更在孤云外。","萧散无心任去来，因风几度到瑶台。","暝随西顶龙飞去，晴带空江鹤共回。","自言放浪云林久，大道由来贱刍狗。","曲几冥看老氏书，衡门静对先生柳。","乐山楼上兴悠悠，遥惟却卷横湖秋。","一声长笛飞霜里，云影离离半寒水。","壶公醉墨天下闻，况是仙都鸾鹤群。","而余大梦独未觉，不知云为君兮君为云。"]},{"t":"赠凤阳王将军时镇平津","f":"古风","c":["王将军，凤之雏、骥之子，武弁承家佩金紫。","春风早食金琅玕，昨日长鸣渥洼水。","玉帐遥临剑水清，少年白晰又专城。","尊前醉墨歌千首，案上军书论五兵。","故园久别临濠路，忽忆先茔感风树。","鼎湖龙去凤西飞，扳鳞附翼今何处。","君家叔父爱文章，风流亦羡紫罗囊。","须知七叶功名在，应继三槐德业昌。"]},{"t":"国子先生郑孟宣以赐告归省丘墓暇日访余新宁之沙堤余因载酒于沧洲野堂以宴之适文墨友方外交翕然来集酒酣乐甚分韵赋诗余得酒字时庚辰孟秋七月","f":"古风","c":["上客何处来，系马堂阶柳。","马头尚带秣陵尘，衣上犹香白门酒。","宁知此地重携手，张灯复话昔年旧。","问我萧条但布衣，念我栖迟向田亩。","沧洲地主忘年友，把酒相欢两情厚。","鸟外晴波对急觞，天边白月当虚牖。","山林已是忘形久，更喜支公说空有。","旅思休惊一叶秋，佳期况及双星候。","狂歌击筑君知不，痛饮何须问牛斗。","明日相思壁水遥，唯有新诗满人口。"]},{"t":"题吴氏养拙卷","f":"古风","c":["世人竞巧智，子独尚浑朴。","世人机事有机心，子独无机心亦乐。","闭门山水少逢迎，曲几琴尊隐姓名。","太羹玄酒无滋味，标枝野鹿俱忘情。","世人大笑延陵拙，不学仪秦谩饶舌。","作室翻嫌樗里谋，悬樽却羡蒙人说。","东邻少年取锦衣，西邻歌舞日光辉。","清时何用嗟沦落，饮水看云谁是非。"]},{"t":"吴云归兴送别王明府子侄还姑苏","f":"古风","c":["何处发归兴，吴江多白云。","晴教积水青枫合，寒带空洲远雁分。","游子前年别张掖，酒泉南头夜霜白。","扁舟忽过钓龙台，回首姑苏是乡陌。","小阮曾为叔父知，十年应负竹林期。","参差雨雪遥相问，迢递关河又别离。","羡君兄弟东归去，白马双嘶首前路。","行人未听虎丘钟，春风已绿吴门树。","莱衣重戏莫迟迟，百里邦君有所思。","悬知旧国看云处，不比甘州见月时。"]},{"t":"书乐邑长史高凉黄公性成六平清致","f":"七言古诗","c":["轩丘之人何坦荡，奋身拟在萧曹上。","三语曾闻作掾名，一言尚遇知音赏。","谁云枳棘不栖鸾，暂屈长才向小官。","月俸持还酒家去，春衣犹似帝京寒。","六平峰下开仙馆，案牍閒时任萧散。","南涧飞泉卧内清，西林爽气朝来满。","自从下马少鞭笞，邻邑争传赞画奇。","遂使郎官唯坐笑，每逢才子即联诗。","有时独上横琴石，万水千峰起遥忆。","金马长悬魏阙情，铜鱼不记乡山色。","南营考绩待朝天，莫笑行囊但一钱。","应知太史求循吏，籍籍声名继颍川。"]},{"t":"题高漫士水墨图","f":"七言古诗","c":["高君兴发泉石间，含毫挥霍写云山。","白云无心去复还，青山对人閒更閒。","垂萝飞鸟疑可扳，浅浅石濑流潺湲，岚烟瀑雨清心颜。","迩来京国推名画，片纸应论百金价。","啸台声响人竞闻，不道无声更潇洒。"]},{"t":"题马自牧水墨山水","f":"七言律诗","c":["鸟外悬萝青几峰，红泉翠壁花蒙茸。","人间不见问津者，林下空馀避世踪。","昨夜山中度凉雨，落木寒猿半窗曙。","日夕天空镜水深，不辨仙源在何处。"]},{"t":"题梁董教岁寒亭","f":"七言古诗","c":["君家结亭乐幽栖，佳树阴阴唯鸟啼。","横经不知白日转，搴帏坐见青山低。","城南城北春风满，陌上春容正堪玩。","白马朝穿桃李蹊，朱轮夜过金张馆。","臈月寒天雪更深，看君亭上独行吟。","眼前草木俱摇落，知尔青青松柏心。"]},{"t":"奉答陈先海先辈","f":"七言古诗","c":["朔雪寒鸿半江海，五侯池馆谁相待。","支离王粲身未达，落拓苏秦舌还在。","梅陇霜前早识君，三溪花畔又论文。","柏山夜雨闻钟梵，华馆清灯对水云。","今年复过沙京下，百丈峰南是君舍。","衣冠萧洒辋川人，山水依稀鹿门社。","别后那能寄远书，秋风空钓雁池鱼。","狂歌酒店墩头月，思尔桃枝湖上居。"]},{"t":"题屿南林遵性学圃轩","f":"七言古诗","c":["君家书室依林坰，日夕清辉多在庭。","出户时看花屿近，卷帷唯见董山青。","苍苔古木连深曲，悬萝石上孤云宿。","露叶垂篱菘薤香，水藤拂槛瓠瓜熟。","任是閒门客到疏，自甘萧散学犁锄。","新凿小池宜抱瓮，时閒高馆复携书。","纷纷甲第皆粱肉，何事丘园未干禄。","稚子能羞苜蓿盘，家人解压葡萄绿。","寂寂林扉绝四邻，角巾野杖亦容身。","公门若更栽桃李，先数林泉种圃人。"]},{"t":"题周家山水图","f":"古风","c":["野人不到山中久，见山若见平生友。","咫尺相看解有情，几番别去仍回首。","石林精舍小茆庐，便欲牵萝学隐居。","周郎拍手向予笑，云是吾家山水图。","角巾野杖行潇洒，又似商颜采芳者。","瀑水淙淙岛外飞，岩花寂寂云中下。","潭声树，凉萧萧，世人何必轻渔樵。","霜枝可薪鱼可食，时来不负金台招。"]},{"t":"题山水图","f":"七言古诗","c":["忆昔扁舟过南楚，飘泊潇湘洞庭浦。","积水寒天梦泽深，疏钟淡月巴陵曙。","君山独上思悽然，竹树苍凉绕暮蝉。","空陵草没皇英骨，古井苔荒柳毅泉。","一别湘江向十秋，披图远忆旧时游。","青枫寂历烟中烧，远岫依稀鸟外愁。","云帆去去寻仙岛，我欲因之拾瑶草。","再三招手呼不来，令人独立伤怀抱。"]},{"t":"题画马二幅 其一","f":"古风","c":["世人徒爱马，不解与马知。","长鸣倦刍秣，力殚翻箠之。","饲以玉山禾，饮彼清泠池。","龙性复矫矫，始知真权奇。","荷君剪拂君门里，厮养年深亦知己。","感激羞怀伏枥恩，常思一日行千里。"]},{"t":"题画马二幅 其二","f":"七言古诗","c":["素练漠漠风沙黄，画者得母东丹王。","圉人牧马山阴口，曾是边头射雕手。","紫骝连钱白鼻騧，蹴沓霜蹄来汉家。","岂知物变长安道，人马伤心对秋草。","迩来御里貌青龙，独数天闲飞越峰。"]},{"t":"书琴高跨鲤图","f":"古风","c":["焚香礼瑶席，远望空悬伫。","翩翩列仙人，骑鱼撇波去。","忆别人家二百秋，暂来复去谁能留。","冀山青青涿水绿，相思不见令人愁。","华阳亭下秋风晚，应教嵇生广陵散。","何处重期太古音，荒城落叶苍苔满。","赤鲤迢迢海上行，春风几度到瑶京。","笑予亦是谪仙者，未得骑鲸归上清。"]},{"t":"奉饯林思和秩满之天官","f":"七言古诗","c":["三月闽州柳堪折，泮林上客来作别。","自言官满欲朝天，不向家山卧明月。","君家兄弟并承恩，冠盖联蝉共一门。","看君已是丈夫行，况复少卿贤子孙。","太常峨峨綵云里，君见才名亦如此。","黄鹄高飞隘九州，骅骝一蹴行千里。","倾盖逢君惜未深，相看又动别离吟。","兴回暮雨孤尊酒，目送南鸿一片心。","吴樯积水丹枫坝，淮树青山秣陵社。","白下亭中醉墨时，凤凰台上弹琴夜。","故园迢递白沙堤，榕叶青青拂石猊。","功成早著还乡绣，毋令睇望空云泥。"]},{"t":"书松陵夏尚忠王明府道斋故人也明府绘望云图令其子归遗之索余题其上","f":"七言古诗","c":["毗陵客舍洮湖里，乡心祗忆吴江水。","关门千树别来青，笠泽孤云望中起。","孤云迢递故乡山，也似梁公马上看。","肤寸任随零雨散，飞扬还带莫天寒。","看君已抱连城璧，何事犹怀兔园笔。","朝饭歌残苜蓿盘，春衣梦绕斑烂色。","王郎此去揖清芬，明府缄书远念君。","他时好在青云上，回首姑苏是白云。"]},{"t":"牛上翁","f":"古风","c":["时既和，年既丰，乐莫乐如牛上翁。","短衣半湿杨柳露，长笛吹老棠梨风。","君不见苦竹岗头淇塾水，鹧鸪相呼作人语。","马上郎官攒两眉，海北天南路何许。","翁家有粟牛有莎，世人造物如翁何。","牛饱归来浩浩歌，江上儿孙雨一蓑。"]},{"t":"为陈必宗题高漫士山水","f":"古风","c":["水墨不求似，意在丹青表。","前朝独数僧匡然，后有方壶可同调。","龙门此日发天机，挥霍霜毫亦神妙。","遥林积水湛清晖，金削芙蓉连翠微，中有白云朝暮飞。","云飞尽逐青山去，山灵笑谢红锦衣。","主人原是幽栖者，乔木苍苍此山下。","我亦沧波淡荡人，醉里閒寻有声画。"]},{"t":"为陈必尚题山水图","f":"古风","c":["太常积飞翠，朝夕侵我庐。","严公湖上水，色映灵台虚。","雁峰屋上三山峭，散帙鸣琴亦高妙。","半榻閒云鹤梦醒，一帘初日藤花笑。","顾余性癖爱清晖，终日相过尽醉归。","几度离家声别调，何时恩许卸朝衣。","黄花九月高楼酒，无那明朝又分手。","座中应感去年人，马上空攀未霜柳。","酌酒看山兴暂同，君家兄弟气如虹。","萍踪自愧无南北，聊寄相思水墨中。"]},{"t":"题高漫士为周仲器作黄山书室图","f":"古风","c":["海上见空翠，黄山积扶舆。","连林结幽构，中有千卷书。","白日但垂帷，抱琴常晏如。","何必邺侯家，于焉董生庐。","有时岩际书声起，天籁泠泠拂流水。","清响遥传野衲禅，馀音半落鲛人耳。","芸草春香静掩门，河汾洙泗共谁论。","閒将活水澄心镜，向人大笑翻忘言。","翰林墨客拈双笔，挥霍新图兴偏逸。","寒松满屋疑有声，白云卷帘怕飞出。","轩佩追随入泮林，玉堂天路五云深。","白头为尔伸长句，直是渔樵一片心。"]},{"t":"赋得幔亭峰送人之建上","f":"七言古诗","c":["鹤岑戛然开洞门，仙翁骑龙宴曾孙。","曾孙大醉仙翁别，木魅鲛童吊溪月。","葛花濛濛簝竹荒，石云紫蕨参差凉。","银湾逗帆啸苍突，玉函千年蜕金骨。","峰头药草九节香，胡麻作饭与君尝，待君骑鱼还故乡。"]},{"t":"题侯明府河阳满县花卷","f":"古风","c":["君不见河阳潘郎花作县，茏葱千树行人羡。","县南县北正花开，二月三月花如霰。","拄笏香浮按牍清，摇鞭色映宫袍茜。","看君为政应不烦，还如桃李竟无言。","成阴共借阳和力，结实都含雨露恩。","莎庭吏散心如水，山鸟舍花下厅事。","花底时闻宓贱琴，花边或驻王乔履。","前年玉斧将绣衣，胆落金吾铁面威。","今年复把郎官笔，可怜铜墨生光辉。","河阳只爱芳菲色，未胜君家曾种得。","春风早食金琅玕，岁寒莫负淩霜柏。"]},{"t":"美朱嶙为仲弟诉冤","f":"楚辞体","c":["北门天霜秋草衰，南山桂树青连枝。","鹡鸰低飞声正悲，弟急难兮兄痛之。","边头军帖严有期，将作辽阳征戍儿。","阿兄含冤摧两眉，誓将生死长相随。","天门九重龙虎威，逞鳞猛须谁敢窥。","以额扣阍天始知，天始知，事还白，不使全家隶兵籍。","君不见同胞纷纷日相訾，行义之人乃如此。"]},{"t":"为郑可久题漫士画","f":"七言古诗","c":["龙门画史多神墨，纷纷见者谁能识。","自从走马入鸾坡，片纸人间求不得。","高堂素壁洒林泉，王屋嵩丘远岫连。","对榻长飞洞庭雨，开檐欲放苍梧烟。","玉融才子中林士，脱落尘机爱山水。","想是龙门大醉时，挥霍含毫为君起。","猿鹤山中那可招，暂时看画忆渔樵。","长安莫道终南近，自古云林远市朝。"]},{"t":"送王借之永嘉训迪","f":"七言古诗","c":["谷口离歌动行箧，马首西风卷残叶。","芹水今看释菜严，棘闱旧睹穿杨捷。","东嘉形胜古名州，雁荡峰回浙水秋。","驿馆莫投菰米饭，山城寒过木绵裘。","广文官舍江天里，官暇弹弦聊隐几。","抱膝休歌梁父吟，传经且授毛苌义。","权门要路四时春，念尔官卑禄更贫。","闻道此乡多大布，不须遥寄到樵人。"]},{"t":"书少尹陈思孝松庭清晓卷","f":"七言古诗","c":["官署双松何彩翠，吏散人稀苔满地。","独坐松间是阿谁，才子风流太丘裔。","薄晓松枝清露繁，公庭无讼寂无喧。","常思佐理苏民瘼，不分端居愧主恩。","乃翁倜傥龙头客，曾事先皇佩铜墨。","京使争传德政碑，邑人共说郎官泽。","枯鱼肆索几何时，倏尔空愁风树悲。","莫言累叶仍州县，九棘三槐应有期。"]},{"t":"长乐陈士宜三桂堂","f":"七言古诗","c":["七闽南宋旧繁华，乔木朱门非几家。","新宁甲第开三桂，云是中山有妫裔。","拖金跃马绾银章，兄弟蝉联被宠光。","绣箧黄绫官诰重，银勾华扁御书香。","儒英门对千峰秀，三树蟠根日应厚。","密色三时绿覆檐，飞霜九月凉侵牖。","阴阴丘木护泉宫，岁岁云孙尚扫松。","秋菊春兰时祀别，褒衣博带古人同。","故家文献今如此，累叶犹能拾青紫。","请君回首赵家陵，大梁落叶秋声里。"]},{"t":"陆推府望露思亲卷","f":"古风","c":["陆侯东胶士，家林西楚乡。","别来念亲舍，目极孤云翔。","孤云飘飘洞庭渚，梦飞不到三湘浦。","天门西望数峰遥，澧水东流寸心苦。","昨日承恩别紫宸，闽州父老候车尘。","争看壁水环林秀，来佐朱幡皂盖臣。","莫言束带恒推府，韩琦赵抃多殊遇。","三尺探知犴狱情，一帘隔断苞苴路。","朝朝讯谳不辞烦，名宦由来古所言。","若待锦衣归省日，夫人含笑问平反。"]},{"t":"赠新宁陈五处士大初应召","f":"古风","c":["祖道百壶酒，千人歌送君。","玉壶击宝剑，壮气横孤云。","玉壶击断歌声作，远海春潮为君落。","别路行看指凤皇，青山不得随猿鹤。","主父西游感慨多，马周辛苦遇常何。","何如高卧东山顶，一上金门解绿萝。","问君今年几十霜，须眉稍白发半黄。","长松岁寒起淩厉，良骥老大方腾骧。","龙肿好为苍生出，莫爱丘园长隐逸。","作县还堪鲁卓齐，为邦尚可龚黄匹。","君到皇州春正深，龙池柳色动乡心。","白门酌酒看花醉，青琐闻莺委佩吟。","同游倏尔皆朱绶，笑我蹉跎空白首。","玉堂西掖故人多，相逢为问平安否。"]},{"t":"唐主簿陟屺图","f":"楚辞体","c":["陟彼屺兮何所思，日眷眷兮心不夷。","望雷阳兮不可见，返余辔兮首中逵。","雷阳一发春无际，浩荡鲸波数千里。","匹马天涯思故园，夫人堂上悲游子。","子有园林瘴水滨，家人曾浣綵衣尘。","槟榔花下红谖草，别后纷披几度春。","自云薄宦沾微禄，梦飞不到雷阳曲。","乞身归养应及时，莫比前人叹风木。"]},{"t":"送闽藩从事吴景从考满赴铨科","f":"七言古诗","c":["闽藩大府多从事，延陵公子非凡吏。","簿书八郡览清名，刀笔千人让初试。","南宫今去考功名，迢递河山入帝京。","画省堂中拜方伯，丽樵门外别同声。","纷纷祖道螺江口，午日蝉声市门柳。","丹荔高堆玛瑙盘，玉壶满载葡萄酒。","官船击鼓离歌发，一片炎云海波阔。","彭蠡惊心楚树秋，白门买笑吴门月。","西游毕竟沐恩多，应与群公接佩珂。","若对韩休高待诏，道予问讯今如何。"]},{"t":"龙龛龙集并序","f":"古风","c":["莲宇最高处，青萝隐丹梯。","钟鸣海色动，四壁闻天鸡。","簝竹苍梧野翠分，石林阴洞未归云。","香炉峰小开窗见，水乐声寒隔坐闻。","回风飒飒吹松栝，落日澄潭见毫发。","龙眠水底呼不醒，千岁寒漦雨苔滑。","而我发遐想，兴来随所之。","缘云踏鸟道，披荒上天池。","天池色映黄姑水，手接飞藤洗双耳，鬼谷仙源杳霭间，雁荡天台只如此。","望海亭中载酒来，石楠花气拂金杯。","葛衣醉倒翻经榻，纱帽狂歌施食台。","龙龛法似心无垢，宴坐禅扉说空有。","玄度难酬支遁词，凿齿曾于道安厚。","浮梁少尹欲朝天，群从相看惜别筵。","遥想五云双阙下。","时时飞梦绕林泉。"]},{"t":"书陈思中钟山草堂","f":"七言古诗","c":["东人结庐云水间，有时飞梦游天关。","西人白马长安道，身寄玉堂心在山。","草堂只在钟山口，石门南头岱溪右。","古木垂萝绕四檐，红泉翠壁当虚牖。","怜君白面鲁诸生，却爱幽居隐姓名。","兴来满载东山酒，春至还寻谷口耕。","卷幔横经坐曲房，穿林著履采芸香。","天寒煮茗僧同榻，月出弹弦鹿近床。","岩扉近舍多幽处，向子何须更长去。","心远能忘朝市喧，机閒自得烟霞趣。","独鹤孤云任此身，至人舒卷道为邻。","草堂亦有山灵在，莫学周颙却笑人。"]},{"t":"题高漫士为果之绘阜阳别墅","f":"古风","c":["吾爱龙门子，解作无声诗。","今为玉堂客，留此粉墨奇。","满堂山水多佳处，何限清辉阜阳曙。","百道泉声缥缈间，几片云来欲飞去。","石门沙径逗微曛，飞红沓翠长氤氲。","仙人炼处丹梯近，野衲行边鸟道分。","房栊正对钟山色，龙龛苍茫岱溪白。","槃谷重逢李愿居，辋川复见王维宅。","主人兄弟俱好奇，酌酒鸣琴更下帷。","客至频移剡溪棹，兴来或赌山阴棋。","龙门绘事今无价，千里相思五云下。","我是林泉一布衣，为尔翻为有声画。"]},{"t":"题?鹑","f":"七言律诗","c":["山禽奔奔好羽毛，翼短飞低恋榛莽。","荒原野径薜荔稀，莫惮王孙便飞去。","原头八月起秋风，寒菊初花枸杞红。","雌雄相随莫相斗，官里频将锦衣绣。"]},{"t":"书三山造士刘恒哲挹翠轩","f":"古风","c":["三山苍苍冶城里，楼台十万歌钟起。","君家正在冶城西，门对千峰翠如洗。","黛色空濛连翠微，和烟著雨又霏霏。","澹随野鸟偏宜梦，浓带孤云欲染衣。","日出尘歊满城陌，羡君开帘见山色。","九衢鞍马市声喧，羡君游心竹素园。","君莫爱张仲蔚，遁迹空山避朱绂。","君莫爱陶弘景，自甘泉石烟霞病。","五岳名山竞远寻，那知城市有山林。","泮池来往堪乘兴。","终是云霄万里心。"]},{"t":"题陈敬山晋安丹室","f":"七言古诗","c":["丹室人间那可寻，嵩丘王屋五云深。","先生结茆在何处，坐令九转成黄金。","芙蓉出鼎秋花吐，曲密房幽夜窗曙。","阳遂光中结坎离，方诸影里交龙虎。","早服还丹变羽翰，弱流东逝任漫漫。","秦皇汉武徒辛苦，骊山茂陵荒草寒。","有时买药春城暮，门掩西林杏千树。","相逢稽首长桑君，与君竹木枝头露。"]},{"t":"题龙山归隐卷","f":"七言古诗","c":["山人在山心自閒，偶逐无心云出山。","云飞飘飘落江海，忽讶山人何得还。","山人旧是霜台吏，曾与绣衣掌书记。","八州郎吏揖清芬，三尺儿童识名字。","万事人间转眼非，山人大笑拂衣归。","昔时猿鹤今无恙，别后杉松又几围。","林泉未胜功名好，羡君忘机一何早。","每因京使买琴弦，屡向词人借诗藁。","兴来蹑履到僧家，竹里焚香白日斜。","合屿壶山落天镜，五峰百丈横秋霞。","我昔逃禅此山里，日坐灵花咽潭水。","夜半龙鸣万籁声，四五沙门忽惊起。","几年奔走愧尘颜，欲借金梯复再攀。","愿留十日与君饮，醉倒白云秋半间。"]},{"t":"书高漫士为道人游月窗作水墨图","f":"七言古诗","c":["兹山连峰势磅礴，空翠濛濛坐中落。","始悟方壶醉里涂，复讶商公兴时作。","竹涧堂临溪水滨，龙门墨客问通津。","相逢大醉仙家酒，戏墨持归鹤上人。","鹤上仙人与山好，每见此山应绝倒。","云断嵩丘少室閒，龙鸣华顶天台早。","我亦平生苦爱山，尘缘未割竟何颜。","愿随飞落花源去，一见秦人遂不还。"]},{"t":"送宪吏郑彦林考满赴吏部","f":"七言古诗","c":["我昔维舟东上潭，见君家住岐阳南。","门垂栗里先生柳，身著柏台从事衫。","前年寄诗沙头道，去年期我山中庵。","匹马今朝又离别，斗酒何年共笑谈。","今去皇州霜正落，况逢淮树叶初酣。","吴女当垆卷细袖，白门烧酒破红柑。","人人尽道山公好，于尔长林无不堪。"]},{"t":"题高漫士逸墨山水","f":"七言古诗","c":["古人逸笔多大意，寿岩宝晋方壶是。","今之画史谁最奇，玉堂待诏予知己。","此君别自有天机，恰似张颠草圣时。","醉来也解头濡墨，醒后翻言画者谁。","满堂积翠横仙峤，主人坐听苏门啸。","万籁天声发指头，百道风泉出心窍。","欲借岩扉隐鹖冠，绿萝青壁共谁攀。","江云渭树悠悠别，聊寄相思水墨间。"]},{"t":"秋夜宴集濮阳别墅","f":"七言古诗","c":["逸人家住千金水，别墅閒耕濮阳里。","人言此水直千金，尔独丘园厌声利。","莫爱西堂梦草时，羡君亦有好连枝。","河东三凤只如此，田氏一门谁更奇。","荒林野水金沙路，曾是先人旧行处。","满月寒花色自幽，断肠风木声偏苦。","禾黍登场酒复篘，断壶剥枣宴同游。","满堂醉舞多年少，愧我猖狂今白头。","云间片月悬秋汉，遥海星沉夜将半。","感君兄弟苦留人，谓我天明莫分散。"]},{"t":"题林遵性墨竹","f":"七言古诗","c":["屿南山人心不羁，含毫醉扫苍筤枝。","斩钉截铁何怪怪，兔起鹘落偏奇奇。","国初始重方壶笔，若比湖州更飘逸。","丹丘金错未足誇，吴兴籀法应难匹。","临榻由来失本真，当场落墨要惊人。","山人独向灵台悟，信手拈来如有神。"]},{"t":"九峰贞隐卷为道人游月窗作","f":"古风","c":["君不见闽关西来剑水东，连峰九个青芙蓉。","吾师若个峰头住，物表孤高淡忘虑，三花五粒常满树。","焚香阅遍五千言，云笈七签玄又玄，太素既雕师自然。","庄周列子书满箧，宴坐丹房不交睫，霞步云裾风猎猎。","大道窅窅复冥冥，神谷不死忘我形，泥丸宫中可通灵。","世人习隐只是隐，饮酒何曾悟玄牝，尘劫纷纷师一哂。"]},{"t":"牧牛图","f":"七言律诗","c":["禅客观心如牧牛，人牛两忘心即休。","恰如牛上小童子，百虑不关神自由。","黄桑贯鼻素丝索，水浅莎长草衣薄。","驯扰由来任本贞，倒行逆拽空牢落。"]},{"t":"题南岳夫人图并序","f":"楚辞体","c":["彼美人兮何得仙，鍊太和兮保长年。","驮白牛兮降朱鸟，心黄庭兮口不言。","质姱嫭兮心澹静，巧靥辅兮体轻便。","发鬓云驻兮肤瑩雪，规脩蛾兮目成■。","曳霓裳兮结罗袜，被纹縠兮云锦鲜。","错木难兮佩明月，丹胡卢兮腰下悬。","挟两婴兮先僮婢，负躨跜兮如远邅。","萼绿婉娈，麻姑比肩。","幽渺沕穆，委蛇蹁跹。","倏鸾翔兮千仞，忽龙游兮九渊。","御祥飙兮复褰举，仙之人兮俨若旋。","衡山岩㠂，㟏岈层颠。","绛楼彤楹，泥丸丹田。","独舂容兮于大道，众莫知其玄之又玄。","余既觌芳仪而自失兮，神恍恍而内迁。","邈灵爽兮不予顾，山寂寂兮水溅溅。","荒唐诞幻不可测，漫汗丹青那可传。"]},{"t":"答黄嗣杰","f":"七言律诗","c":["来清小圃堪娱客，主人迩来閒不得。","朝到县门夕到家，山风吹落栀子花。","竹边石上烧茶处，与君别来几朝暮。","我有相思一片心，为君臈日抱瑶琴。"]},{"t":"高凉梁惟正爱日堂","f":"七言古诗","c":["来日短短去日多，百龄悠悠易蹉跎。","事亲不可得而久，日短心长知奈何。","帘前白日閒来度，强半光阴夜中去。","长日须教十二时，时时好在承颜处。","游宦因兹想故乡，铜鱼山色对高凉。","家临电白城头树，走马别来凡几霜。","忆昨西台著绣衣，今为花县亦忘机。","寥寥廨宇秋灯下，海阔天遥有梦归。"]},{"t":"海上逢陈生","f":"七言古诗","c":["陈生拜揖当路岐，未道姓名那得知。","别离不觉二十载，倏忽相逢如有期。","忆子年才十五六，负笈朝朝向予读。","我今须鬓已皤然，子亦形容过半宿。","别路萧条霜正深，无钱沽酒又分襟。","到家若见平生友，为我慇勤达远心。"]},{"t":"宪从事新宁陈氏归隐卷","f":"古风","c":["识子何太迟，谁家见颜色。","胡瓶臈酒介轩楼，红烛离堂孔彰席。","忆昨见君毛骨奇，白面虬须秀两眉。","九苞凤羽朝阳日，百鍊鱼肠出匣时。","清署淹留凡几载，百司共喜文无害。","何意翻捐从事衫，到家偏著斑斓綵。","阶下红萱映白茆，活鳞香稻遍山庖。","帘前肆伍淩霜竹，借与慈乌来作巢。","莫言村西一丘壑，小山松桂长如昨。","心远能教地自偏，何必庐阜天台有猿鹤。"]},{"t":"书新宁高鲁仲心远堂","f":"古风","c":["门外有人事，门里无俗声。","超然心境静，邈尔尘虑清。","宛如林下安禅客，身寄蒲团意空寂。","又如仙客味丹经，玄牝门中澹而嘿。","有时拂几独鸣琴，希声忽度缁帷林。","猗兰掩抑东归思，沂泗春波千丈深。","横经只在閒堂里，浩荡真源了无际。","卧想羲皇轩后时，坐梦无怀葛天氏。","松桂青青半占山，泮林多暇日应还。","谁知一片灵台曲，更在孤云杳霭间。"]},{"t":"王克刚碧萝山房","f":"七言古诗","c":["醉樵醉樵家何处，垂萝拂窗泉绕户。","屋头万万翠微峰，巷口千千石楠树。","寂寂垂萝翳古松，萦烟摆月又丰茸。","花飞晚榻僧同坐，叶作秋衣手自缝。","山人直是幽栖惯，来往红尘亦萧散。","采樵时少醉时多，在泮日长归日短。","归去山中百虑消，芭蕉叶长蕨初苗。","狸香玉面时登馔，酒熟黄精屡洗瓢。","草书逸兴如涛涌，满城见者神皆竦。","铁限年来踏又穿，霜毫岁久埋成冢。","羡尔幽居对绿萝，青云高兴近如何。","还将墨客龙门画，来觅皆山樵者歌。"]},{"t":"书梅江陈汝畴家藏古画","f":"七言古诗","c":["吴丝半幅无全缕，越树淮云楚天雨。","兵燹流传不记年，丹青漫灭空存古。","绝壁连峰窈窕间，剑门迢递对荆关。","疏钟远火褒斜谷，落叶秋风子午山。","西游去去羁尘绶，草衣笋笠今何有。","箕山不见弃瓢人，渭曲难逢钓鱼叟。","君家父子爱林丘，静里乾坤不著愁。","南塘耕毕閒看画，醉倚千金水上楼。"]},{"t":"书黄士杰来清亭","f":"七言古诗","c":["太常东来凡几峰，仙山独削金芙蓉。","君家作亭此山下，坐听秋声连万松。","仙床石室垂萝畔，何限清晖落飞幔。","北阙青云梦里閒，西山爽气朝来满。","少饮翻能学醉翁，草玄何必似杨雄。","讨论未悟天人理，啸傲还将麋鹿同。","玉堂争识傅岩子，簿领香名亦如此。","君有灵台一片清，来时不在清晖里。"]},{"t":"为林中州书棠梨白头","f":"古风","c":["有鸟有鸟头雪白、羽离披，一雄啾啾挟两雌。","高飞畏弹射，栖宿不分离。","山果熟时无苦饥，哂彼炎州翠，杀身徒尔为。","何如此鸟之智如愚痴，老向林泉谁得窥。","棠梨结子竹花谢，春去秋来同一枝。"]},{"t":"高凉梁惟正贤妇歌","f":"古风","c":["君不见铜鱼山高崒嵂，蜿蜒下有龙湫窟。","神秀清泠杳蔼中，散落谁家作英物。","清门女大初嫁夫。","射中金屏与梦符。","勉郎也似乐羊妇，怀节偏同曹大家。","郎骑骢马西台客，妾向空闺侍姑侧。","朝吟刘向列女篇，夜诵曾参孝经策。","愿为王雎不顾情，愿夫天路受恩荣。","铜鱼山崩海水竭，世上应磨贤妇名。"]},{"t":"奉题清远伯水墨图中写松竹梅","f":"古风","c":["君不见徂徕峰顶秋涛作，琅琊台上天声落。","君不见黄陵庙前千万枝，楚云湘雨青离离。","不知何树临寒水，冷蕊空香拂征骑。","乍逐吴歌曲里残，又向边人笛中起。","君侯受钺下闽藩，草木还沾雨露恩。","山中亦有淩霜柏，思向侯门深托根。"]},{"t":"题龙虎将军凤阳童公思亲卷","f":"七言古诗","c":["将军少年论五兵，刀头几岁成功名。","腰悬鹊印行分阃，令严虎帐居专城。","望乡更在云飞处，思亲梦绕临濠树。","羽檄星流恐后期，綵衣日远那能顾。","忆昨鸣珂出帝京，一门兄弟被恩荣。","谁知略地攻城手，偏动瞻云陟屺情。","上流浇酒三军醉，半菽饥分苦留意。","应嫌食子徒徇名，却笑辞亲空齧臂。","南镇闽川胜玉关，唯将忠节慰慈颜。","由来葵藿倾心处，只在春晖寸草间。"]},{"t":"题剑溪上人坐禅卷","f":"七言古诗","c":["释子安禅何处山，镡津溪上薜萝间。","身将鹤畔松同古，心与岩头云共閒。","九峰禅观通云月，百六滩声广长舌。","翠竹黄花总是禅，西来直指何言说。","磨砖作镜无光彩，刻舟求剑知何在。","吾乡兄弟刹那间，若问江湖三十载。","戒刀禅尺与蒲团，定里休将色相看。","直教铁铸脊梁骨，不用安禅禅自安。"]},{"t":"书林景时墨竹二首 其一","f":"古风","c":["水墨扫金错，每惜柯丹丘。","鹘兔互起落，复爱文湖州。","吴兴老人已仙去，纷纷作者谁能悟。","石室流芳何处寻，壶丘羽客心偏苦。","虚白子，通仙灵，三湘雨色閒青青。","皆山樵人酒半醒，晚风吹梦秋冥冥。","明朝飞上君山去，一曲璚箫龙为听。"]},{"t":"书林景时墨竹二首 其二","f":"七言律诗","c":["楚山脩玉淩云起，影落谁家画屏里。","断粉残香夜不收，寒枝只是生秋米。","多情遗牒度湘皋，别有篬筤节更高。","为君饮尽上池水，看此毵毵长凤毛。"]},{"t":"西昌邓奉使安泰堂","f":"古风","c":["楚国多秀士，邓君如凤凰。","刷毛霄汉上，览德岐山阳。","君家文献犹存古，安泰堂中如乐土。","开帘时听九江潮，酌酒晴看五峰雨。","散帙断弦绝世情，坐来心地自然平。","夫人堂上无愁色，稚子阶前同笑声。","东城南陌何凄断，绿野平泉也凋换。","三湘窜逐怨江蓠，万里羁危对秋雁。","此际问君谁似君，日高犹卧半床云。","只言永结烟霞想，何意今随鹓鹭群。","使车到处争迎送，乳酒青丝白银瓮。","西上金门自此升，山中茆屋空多梦。"]},{"t":"送郑居仁以楷书赴召","f":"七言古诗","c":["尔家山房多柿叶，架上床头饶古帖。","柳骨颜筋手屡摹，王廙钟繇每精猎。","兔园挟策几经秋，不见将名干五侯。","一瓢只谓山中隐，匹马那堪西上游。","河桥酒幔青青草，祖帐离歌满官道。","行箧春衣莫畏贫，上将权门与君好。","高阁阴阴绕凤池，紫花鸾绫光陆离。","擅场点笔须经意，莫比家林醉墨时。"]},{"t":"九鹭鸶","f":"古风","c":["属玉何翻翻，群飞向空阔。","非无霄汉心，暂尔弄流沫。","绿水几片云，青山半行雪。","有时寄芦花，相将乱明月。","此鸟清臞绝世尘，往来烟波不属人。","若教尽逐鸳鸾去，谁共沙头鸥鸟亲。"]},{"t":"渔樵耕牧图","f":"七言古诗","c":["山水相逢任疏散，孟诸日夕歌声远。","大野春苗叶未齐，长川水草香犹短。","峡口泉萝隔世尘，云间鸡犬是秦人。","重林峰壑无归路，流水桃花几度春。","白头未悟丹砂理，纵酒狂歌鹖冠子。","一片孤云野鹤心，秋来梦著青青里。"]},{"t":"水墨横图为姜养恬书","f":"七言古诗","c":["梗树重林隔花远，仙源一道缘溪回。","太常峰顶千秋雪，石门洞中万古苔。","石门隐映灵湫窟，积水澄波洞毫发。","龙鸣午夜发天声，僧定空山见秋月。","美人家住石门东，散帙垂帷杳霭中。","千嶂云来窗户白，半岩雨过野泉红。","美人自是儒林秀，叔父风流今白首。","醉来莫赌山阴棋，兴在宁陪竹林酒。","门前水硙霜花米，席上春盘脍鲜鲤。","何意匡庐四五峰，飞落君家画屏里。","君今见画思隐沦，谓我年来得句新。","谁知纸上千章富，不换仓中五斗陈。"]},{"t":"赋得沙堤送别造士王克刚赴召入翰林","f":"七言古诗","c":["新宁海边沙作堤，人烟两岸草萋萋。","潮归鹅鹳印行迹，雨到枫州沙更白。","沙山缭绕大堤平，故老虚传宰相名。","渔梁晚波牛渡浅，堰口春泥马蹄软。","新水还流旧水声，古人过尽今人行。","青幔红桥几回别，官柳秋风不堪折。","才子辞乡近九重，衔杯堤下动别容。","遥知草诏明光里，沙上空流送别踪。"]},{"t":"总赋山阴十咏","f":"七言古诗","c":["泮林才子多爱山，吏书共往青萝间。","洙泗河汾恣探历，天根月窟穷跻攀。","振茏玉树分岚岭，一室寥寥是心境。","龙吟绝涧静琴声，雁落曾标慧灯影。","石林精舍梵钟微，垂萝叶暗桐阴稀。","负薪扣角非同调，解听书声忘却归。","有时散帙烟霞表，澹澹长空际飞鸟。","江心潮没一峰浮，石首云间众山小。","青幔红桥酒瓮香，江蓠初绿棹歌长。","相逢白发非春事，忆昔金门是夕郎。","倾壶采秀多狂趣，世人那得知其故。","赤霄麟凤伫翱翔，莫忘山阴读书处。"]},{"t":"东溪精舍杂咏为吴中美作","f":"古风","c":["延陵精舍东溪口，六曲屏山对虚牖。","绝壁连冈入万松，一涧盘陀大如斗。","盘石垂萝密更偏，黄精潭上写冰弦。","化成水月三千界，古洞烟霞小有天。","烟霞杳微茫，水月澹忘知。","谁知鲁中叟，发彼川上喻。","溪水东流接泮林，云泉佳处萃青衿。","金门旧隐时同屐，白头老樵来听琴。","孤亭五月秋声起，列坐柽阴爱流水。","借君矶畔濯尘缨，何必箕山洗双耳。"]},{"t":"雪溪行旅歌为古县陈齐之赋","f":"古风","c":["君不见燕代城头雪花白，片片飞空大如席。","居庸关口秋即寒，白翎冻损地椒乾。","骆驼淩竞马不发，卷发虬须胆欲折。","公主琵琶苦调多，都护狐裘冷如铁。","行旆遥遥出柳林，贾胡车上尽驮金。","葡萄十斗饮不醉，瀚海层冰千丈深。","回看宫阙连天起，万岁山高玉华里。","雪散春回宫草青，百年王气东流水。","江南春早雪声残，行客休高行路难。","西游大道青天上，不比居庸关外看。"]},{"t":"题前给事陈行四读书室","f":"七言古诗","c":["给事先朝罢官日，拂袖还山坐虚室。","牙牌角带厌羁縻，大布乌巾任閒逸。","邺侯架上五车书，玄宴床头万卷储。","心中有悟即大笑，怀里无钱常澹如。","忆昨逢君领乡贡，何限居人走相送。","南陌看花日几回，春闱得桂今成梦。","君家面面好林泉，莫把荣华记昔年。","一瓢且醉山中月，数亩还收江上田。","江田潮满春苗绿，瓜地秋香橘林熟。","古洞云龛鹤共行，石门沙岭僧同宿。","玉轴牙签半草堂，閒教子弟竞三场。","经旬不出蟏蛸户，见月唯开薜荔房。","西风黄叶何萧瑟，镜里秋霜数茎白。","壁间犹挂汾亭琴，扁上时看紫阳墨。","知君守道更忘贫，缃帙恒开绝四邻。","垂帷闭户且安命，未必琴书付别人。"]},{"t":"无声诗趣赠林质斋画史","f":"七言古诗","c":["风流摩诘居辋川，在官也或思材贤。","兴来解作有声尽，醉后无声诗更玄。","长林才子非常调，却与蓝田共心窍。","乾坤意气转清冷，散落天机发神妙。","居庸雪花凝不开，紫云二室连嵩台。","萧条三峡流泉去，倏忽空江秋雨来。","夕林返照缘原骑，残叶疏钟隔村寺。","郎官湖上酒满船，浣花溪口驮驴醉。","权门列戟揖清芬，众史骈肩迥不群。","朕墨远过曹氏子，羸裎偏动宋元君。","閒居委巷尘踪少，藐视千金一毫小。","耻随延寿枉蛾眉，懒学边鸾媚花鸟。","湘山湘水别来深，忆昔王门遇赏音。","白首回家无长物，黄花满径与孤琴。","别离已久重携手，自笑无钱可沽酒。","扫素含毫不作难，为貌山林布衣丑。"]},{"t":"题林逸人水竹居巷中州逸人隐于横塘所居环树脩竹凿池以通潮汐暇日常宴坐其中与道徜徉澹如也因以水竹居自名其堂且索予长句诗就主人击节而歌歌竟请书为赠文","f":"古风","c":["清莫清如金塘之碧筱，澹莫澹如玉溆之澄澜。","红泉一道写天影，青林五月惊秋寒。","草堂宴坐如空寂，远过山阴子猷宅。","初疑飞梦落湘皋，彷佛苍梧起瑶瑟。","磷下苔边好濯缨，看书高枕谢浮名。","白鸥小艇沧浪调，黄鹤孤琴静夜声。","閒门永日无车骑，半榻清风兀然醉。","动处偏澄静者心，晚节方知此君意。","客来呼酒共论文，烧笋烹鱼每夕曛。","自耽老兴工长律，更喜儿郎书八分。","忆昔闻君访仙岛，壶丘员峤多灵草。","九转黄金祗浪传，数茎白发归来好。","如今高蹈隐乡山，学得刘伶善闭关。","只愁西伯非能猎，忽到滋泉水竹间。"]},{"t":"寄题灵武王孟扬南湖草堂","f":"七言古诗","c":["湖南小山谁结茆，潮阳使君归避敲。","五马行春何处在，空梁落月多神交。","后人此地还庐墓，日望寒松叹风树。","损庵画坐想音容，密斋夜起悲霜露。","阿翁曾与石为邻，今见盘陀若大宾。","阿翁当年与山好，仰止今朝思古人。","澄湖积雨秋波净，菱叶荷花落天镜。","出户唯将鸥鸟亲，罢琴也逐渔樵兴。","君家事业何可当，兄弟联翩如凤凰。","新制文章行满箧，旧藏袍笏尚堆床。","溪藤歙砚相辉焕，金薤琳琅映华翰。","秘阁图书出晋唐，故家彝鼎超秦汉。","我昔登龙候使君，满堂宾客正论文。","南阳醉墨今何在，太史清诗久不闻。","前朝冠盖多如雨，谁共使君同日语。","地下逢人不愧心，人间有泪空传古。","三十年来别永阳，白头无复更登堂。","心随辋口栾家濑，梦落盘中李氏庄。","看君岂是悠悠者，昨日桥门动声价。","合浦初还照乘珠，流沙远致空群马。","到家又结草堂期，曾对山灵发誓辞。","名遂古来应税驾，南湖谁假北山移。"]},{"t":"吴航高鲁仲将赴春官同学友绘其乡龙门胜槩离为十咏分题于上余独裒众目总而歌之以识其别","f":"七言古诗","c":["清晖高楼连翠微，清晖主人常下帷。","春帘半占和烟卷，秋笛三江带月吹。","楼扉正对三江水，半占青山落乌几。","文笔浮峰雁影边，夏云夕照天声里。","岱阳千树拂晴霏，迢递风帆鸡屿归。","绿波芳草潮头白，空翠濛濛来湿衣。","竹枝歌断瀛洲渡，渡口行人自朝暮。","江心船若送僧钟，何限年光此中去。","有时蹑履闻天籁，樵夫牧叟非余类。","吴岭三山只暂窥，青云北阙遥相待。","北阙青云西上游，龙门今夜发仙舟。","明年桂枝君应得，还忆家山醉倚楼。"]},{"t":"赠别曾君伯刚游广东访陈潮州","f":"七言古诗","c":["曾君远游何所亲，潮阳太守君故人。","豪士满堂皆赆别，嗟予四壁常家贫。","看君岂是弹冠客，闻道芹边久虚席。","网罟宁加纵壑鳞，樊笼不掩冲霄翼。","家林别去且迟迟，道过温陵谒旧知。","司校閒堂连别墅，参军遗像有新祠。","清漳山水旧城池，罗氏繁华昔在兹。","驲路停骖空吊古，河桥买醉更题诗。","双旌出迓韩山口，未话乡心即携手。","远道休愁馆谷稀，故人俸禄堪沽酒。"]},{"t":"九日燕集题高牧隐清晖楼画壁","f":"七言古诗","c":["我昔大醉清晖楼，烛前醉眼如沧洲。","九华五老将心远，七泽三湘随梦流。","湘纹卧簟清如水，纨扇平头小奴子。","黄叶声声枕上来，白云片片床前起。","酒醒楼扉曙月凉，青绫犹觉茝兰香。","向来水木通幽处，始悟丹青落醉乡。","兹晨看画重携兴，更喜仲容初战胜。","黄门给事此同游，玉堂待诏曾留咏。","九月黄花酒满槽，主人洗盏客持螯。","风流笑傲清晖里，到处争传牧隐高。"]},{"t":"瓢所应召指所居喧中寂索诗为别","f":"古风","c":["博陵有道者，生事唯一瓢。","触目尽扰扰，冥栖独寥寥。","傍人笑问何能尔，云是灵台本如此。","云海天虚夜月閒，霜林木脱秋声起。","有时斋沐坐禅床，复爱真人曲密房。","鼻端有白分明见，腔里无机自在忘。","草玄更倚扬雄席，饮酒不愁元亮壁。","吟思千重境又玄，凡情一洗心皆寂。","旧隐东林野水边，暂辞猿鹤谢兰荃。","玉堂冠盖思同调，沧海渔樵写赠言。","仙舟腊月闽川道，大雪飞花遍江岛。","稽首喧中别故人，他年来访商山皓。"]},{"t":"书皎白处士墓表后","f":"七言古诗","c":["少微经天何烨烨，处士不言情亦惬。","仙源渤海出清河，南宋尚书今几叶。","人言处士曾怀宝，脱略凡机一何早。","仲举空怜徐稚高，王弘未识渊明好。","三十儒衣鬓尚玄，萧条元季事戈鋋。","金天厌见搀抢动，洛邑长愁郏鼎迁。","谁似当年独高洁，清风飘飘洒兰雪。","仙客神交碧落游，仙人口受青囊诀。","别墅閒堂野水滨，日长高枕道为邻。","龙门月出翁山晓，鸡屿花明宰岭春。","堂前玉树惊摧折，颜巷俄闻丧贤哲。","天上文章记玉楼，人间皎白传清节。","况有承家伍桂芳，若为黄鹄叹孤房。","伤心忽洒亡人泪，丸胆曾留教子方。","生平约契归同穴，百岁何曾昩成说。","宦游令子远辞天，千里家林泣归血。","福山原上草离离，地下焚黄会有期。","黄阁词臣书墓碣，白云居士赋哀诗。"]},{"t":"送长乐池二鲸之春官","f":"七言古诗","c":["京行二千八百里，马上青云帆下水。","平时送客使人愁，此度离歌为君喜。","自从鼓箧凡几载，踏槐一旦香名大。","青袍士子羡英声，白面诸生让先辈。","我亦爱君毛骨殊，九苞威凤空群驹。","秋闱笔下若流水，鲁史胸中如贯珠。","愿君此行无草草，百步穿杨即飞报。","西望青云不可攀，来往空歌鹤岑道。"]},{"t":"赠龙门高十六沂应会试","f":"古风","c":["龙门高生倜傥磊落英妙年，春秋五道落笔顷刻如流泉。","胸中云梦已八九，腹里琅玕俱洒然，昨日战胜如登仙。","仙棹西游拾青紫，巨眼青春阅才子。","五色云中得桂枝，联袂看花杏园里，君家叔父闻应喜。"]},{"t":"阜阳陈全果之将赴春卿远来索别遂作长句兼简郑林三二先辈","f":"七言古诗","c":["新宁造士谁最奇，阜阳说诗多解颐。","散帙长歌小山桂，垂帷或梦金明枝。","凉秋别我游乡试，寸晷风檐初得意。","垂棘悬黎又远投，淡墨毡书拟高第。","腊雪飞花满路岐，送君南浦亦凄其。","古来离别生亲爱，若问傍人那得知。","仙舟几宿经吴楚，水绿蘋香酒如乳。","扬子空江晓上潮，白门远树春含雨。","冠佩纷纷集凤台，千人角斗骋雄才。","宫花拂帽琼林醉，银烛朝天紫禁回。","君家大阮春坊客，宗弟金门早通籍。","退食应悬霄汉心，趋朝好献天人策。","一别云泥怅望深，看君此去得联簪。","倘逢梅雪凭相问，若得浮丘道远心。"]},{"t":"赠吴易平还温陵","f":"七言古诗","c":["延陵家住温陵东，南窥大海连空濛。","五夜扶桑气先白，四月刺桐花正红。","延陵自是黄冠客，名姓几时隶兵籍。","案头庄列万馀言，箧里孙吴二三策。","一著戎衣又十年，三时讲武复谈玄。","閒教弟子六七辈，朗诵黄庭千百篇。","寥寥一室梅花寨，钟磬冷冷发天籁。","鲛女闻经罢泣珠，渔人听法争持戒。","心本孤高绝世嚣，有时飞札问三茅。","醉磨夜斗七星剑，梦斩秋潭独角蛟。","昨夜营门领飞檄，秣马徵兵远行役。","道过乡山得到家，松门霜雪回春色。","我昔青年爱游衍，席帽肩舆不知远。","金栗峰头鹤共眠，清源洞里僧同饭。","云树荒台秋草蕃，温陵大姓几家存。","繁华不见今头白，待尔重来仔细论。"]},{"t":"送金鲁仲省亲赴滇南","f":"古风","c":["汉武祠，碧鸡遣使下滇池。","舆图既混一，岂必论华夷。","山川遥遥隔中夏，椎髻何曾沐王化。","鸟度犹愁中庆春，梦飞不到昆明夜。","九月凉秋百草凋，孤臣畸士共魂销。","风霜但觉南冠冷，雨露那知北阙遥。","子行悠悠赴绝国，心恋严君多感激。","八千里外怨暌离，十九年中断消息。","念此令人欲奋飞，遂将行箧卷征衣。","鹡鸰原上分秋影，谖草堂前叹夕晖。","闽关西上连吴越，独树淮山青一抹。","野饭朝行云梦钟，棹歌夜渡巴陵月。","輶轩几日到云中，万碛千山路不穷。","青山好处休停骑，白首营门望阿戎。"]},{"t":"云峰歌送闻上人归","f":"七言古诗","c":["七闽山多如蜀川，千崖万岭疑登天。","六华峰高雪作顶，五月夜半闻寒蝉。","芙蓉石室人稀过，莲宇香台尚经火。","无字碑横任鹿眠，摩香石冷从猿卧。","忆作法园初布金，三千缁锡绕丛林。","径行龙象诸天影，禅寂鲸鼍万籁音。","杉枝青青低拂地，木人也悟西来意。","五百年光转眼休，重见真僧出凡世。","镡津法侣解楞伽，却下九峰登六华。","枯木庵前挂如意，留香堂上搭袈裟。","朅来下界相逢处，幸接微言沐甘露。","凿齿由来识道安，远公自是奇玄度。","法舟今去几时逢，尘世空瞻象骨峰。","归见住山烦问讯，西江一派是禅宗。"]},{"t":"书高翰林绘闽峤归云送周扩泰还长乐","f":"七言古诗","c":["一风东来吹海山，南云北云飞度关。","北云毕竟从龙去，何意南云将鹤还。","云飞适与飘风遇，片片经天散仍聚。","但见无心出岫閒，宁知变态为霖去。","周子辞天便拂衣，龙门解薜上金扉。","吴钩入水疑双化，赵璧连城喜独归。","归来海上还耕钓，食稻安眠开口笑。","白首谁同晚节高，黄山独契归云妙。","闻道龙门怅别深，为君双笔绘家林。","秋天夜夜多归梦，应羡孤云还故岑。"]},{"t":"赠温陵王玉坚游京师","f":"七言古诗","c":["王郎解剑还乡里，六年不梦军中事。","垂竿静钓鳌江云，买舟忽过梅城水。","自说年来爱远游，束装今去上皇州。","溪行笋笠三山雨，水宿蒲帆五月秋。","棹歌明日过京口，我亦西游今白首。","分手前程莫叹嗟，白门相过应沽酒。"]},{"t":"题高待诏为用衡作水墨图","f":"七言古诗","c":["延陵逸人偏爱山，梦飞一室窈窕间。","仙舟往往弄溪月，幔亭绿水声潺湲。","别来林下多幽思，乃与图中偶相似。","蕙带荷衣绝世嚣，孤亭对坐说前朝。","白头晚悟青晖意，醉里援毫为君起。","借问风流画者谁，玉堂待诏高廷礼。"]},{"t":"书董景和家藏高待诏山水图","f":"七言古诗","c":["我昔杨舲过彭蠡，香炉瀑布空青里。","浔阳渡口买江鱼，落帆酌酒看潮起。","吴楚归来静掩门，旧游山水共谁论。","伸蒙岩头醉秋月，太常峰前闻夜猿。","林扉只爱长潇洒，那知忽尔天书下。","何日东还遂隐心，抱琴来访垂帷者。"]},{"t":"题佥宪山东高公永思堂卷","f":"七言古诗","c":["临淄城头风树悲，东流汶水归何时。","愁看风树将流水，因思亲没无还期。","蘼芜堂下秋霜色，日夕焄蒿动精魄。","三时悽怆想音容，一气幽明本无隔。","佳城遥望郁苍苍，春去秋来宿草长。","此日丰碑应表墓，他年幽壤定焚黄。","绣衣玉节承恩厚，乡县枌楸别来久。","藁荐东还未有期，柏台西上频回首。"]},{"t":"海上赠陈汝机","f":"七言古诗","c":["君家海上如栖遁，食鱼饭稻应无闷。","兴来满酌任天真，醉后忘言乱方寸。","古貌清严躯干微，隐侯体弱不胜衣。","昂霄耸壑皆先代，樗散空疏无是非。","贤郎藻思今希有，古诗诵得三千首。","迹远谁同方寸交，心知岂在杯中酒。","客里相逢两度霜，对君无计学佯狂。","自怜落拓钟情者，爱君父子情俱忘。"]},{"t":"书王景撝丽泽书室卷","f":"七言古诗","c":["东邻贩缯为贾衒，西邻握笔趋州县。","北邻金多家富豪，笑我儒生事书卷。","君家住近翠微峰，屋里芸香户外松。","朝经暮史有馀暇，饮水曲肱无戚容。","永日垂帷坐佔毕，复喜朋来同散帙。","活水旁通丽泽回，真源直向灵台出。","逐句寻章失本真，端居谁复贯天人。","鸢飞鱼跃无穷趣，云淡风轻总是春。","以兹学究幽玄理，浩气弥浸小天地。","四壁犹堪薄万钟，一瓢自可轻千驷。","开门合屿带壶山，一片清晖几席间。","家僮洗砚沧浪近，稚子晒书篱落閒。","阿翁今年七十五，鹤发飘然映章甫。","绣衣骢马焕林泉，禅室香床度花雨。","綵服翩翩日过庭，羡君容鬓未星星。","常因益友开三径，不负传家教一经。","自愧贫居破茅屋，土中白蚁何其毒。","万卷床头一蠹休，明日从君借书读。"]},{"t":"金陵送人落第归江南","f":"五言律诗","c":["凤台寒日莫，千里送君还。","别梦愁京雨，乡心絓楚山。","落花偏拥棹，归雁独临关。","应醉家林月，青云好是閒。"]},{"t":"野望","f":"五言律诗","c":["极浦遥山外，荒江瘴海头。","夕岚松叶暗，孤屿鸟声幽。","塞笛飘寒泪，邻讴起莫愁。","连天秋草色，归思日悠悠。"]},{"t":"送郑浮丘被诏重赴京师","f":"五言律诗","c":["关河残叶下，征棹复西游。","远火台城迥，微霜禁苑秋。","诏书天上出，宣室夜深留。","浩荡论经史，时时近冕旒。"]},{"t":"送刘逸人还山","f":"五言律诗","c":["天高寒日莫，念念独还山。","绿树悬心远，孤云入望閒。","水流侵石榻，落叶拥柴关。","别后分遥想，诸峰杳霭间。"]},{"t":"梅江夜泊","f":"五言律诗","c":["卸帆依暝渚，带酒宿沙头。","戍鼓严更漏，寒钟落钓舟。","霜明城下水，月暗海西楼。","薄晓啼猿罢，苍苍远树愁。"]},{"t":"山人入城","f":"五言律诗","c":["行行别翠微，迢递入城扉。","故旧多零落，人烟半是非。","清霜寒使马，落日动军麾。","薄莫遥钟起，还寻旧路归。"]},{"t":"题无诸庙壁","f":"古风","c":["野庙大江干，萧萧树色寒。","断碑荒草没，画壁古苔乾。","龙去春潮在，?鸣海月残。","英雄那可问，东逝更漫漫。"]},{"t":"客中闻子规","f":"五言律诗","c":["关路草凄凄，枫林杜宇啼。","思深湘岸曲，声断郢云西。","故国春归尽，他乡客去迷。","凄凉听渐近，疲马亦长嘶。"]},{"t":"春莫田家","f":"五言律诗","c":["野藤垂谷口，林径少人行。","茅屋先春补，沙田候水耕。","篱深孤犬吠，树密一鸠鸣。","花落家僮扫，寥寥远市声。"]},{"t":"江楼闻笛","f":"五言律诗","c":["纤月絓枫林，晴楼覆夕阴。","谁家吹凤管，永夜作龙吟。","杨柳边头恨，梅花客里新。","天明汉江上，唯见水云深。"]},{"t":"古镜","f":"五言律诗","c":["匣里菱花镜，摩挲恨转深。","土花浮绿晕，秋月闭寒阴。","汉女曾窥貌，秦人己照心。","蛟龙今剥落，徒尔折黄金。"]},{"t":"翡翠","f":"五言律诗","c":["羡尔炎州翠，双栖羽翼微。","雨香红玉觜，风飏碧罗衣。","避鹘藏深竹，衔鱼上钓矶。","吴宫矜首饰，莫道网罗稀。"]},{"t":"送人从海城军","f":"五言律诗","c":["从军江海上，征棹去微茫。","瘴雨孤城白，秋风大野黄。","旌旂连蟹舍，烟火近鲛房。","但使封侯贵，何须忆故乡。"]},{"t":"送人还岭海","f":"五言律诗","c":["别君沧海上，况是暮秋天。","乱叶惊离席，孤云逐去船。","荔枝瘴雨外，椰叶夕阳边。","回首风尘隔，相思共渺然。"]},{"t":"松寺清秋","f":"五言律诗","c":["迢递青莲宇，云边事事幽。","松花山路晚，鹤梦寺门秋。","黄叶僧前落，清泉屋上流。","所嗟尘累久，那得此淹留。"]},{"t":"秋日游山寺","f":"五言律诗","c":["荒山残日晚，秋思正凄凉。","野鸟啼花径，溪泉溜竹房。","钟声云外远，树色雨中黄。","更与询休辈，焚香坐石床。"]},{"t":"送衲子游方","f":"五言律诗","c":["乞食向人烟，心閒处处禅。","浮杯江上月，浣衲涧中泉。","蜀道峨眉远，庐山瀑布悬。","孤云自飞去，谁得扣玄玄。"]},{"t":"闻刘一敦擢监察御史","f":"五言律诗","c":["几年游璧水，一旦候金扉。","敕赐骑骢马，人看著锦衣。","天连枫陛晓，霜借柏台威。","此际如相忆，毋令尺素稀。"]},{"t":"挽邢逸民","f":"五言律诗","c":["流落衣冠没，他乡几度春。","青山行卖卜，白首坐忘贫。","昔爱林中酒，今为草下尘。","平生数行泪，为尔独沾巾。"]},{"t":"老将","f":"五言律诗","c":["发白未侯封，休论旧日功。","酬恩空有剑，锡宴岂无弓。","关塞孤愁外，风霜百战中。","太平应弃掷，流落灞桥东。"]},{"t":"挽僧","f":"古风","c":["人间?久住，只履独西归。","夜雨虚禅座，寒山葬衲衣。","鸽栖青草塔，猿吊白云扉。","从此无期会，空令泪欲挥。"]},{"t":"夜到渔家","f":"五言律诗","c":["渡口集昏鸦，缘村径路赊。","枫青迷野水，竹密暗江沙。","远火人声绝，孤帆日影斜。","扣门惊犬吠，如入子陵家。"]},{"t":"宫人入道","f":"五言律诗","c":["雨露恩宁薄，烟霞思独迷。","向人披鹤氅，无分卷龙衣。","女伴愁将别，君王梦亦稀。","他年青鸟使，衔表到金扉。"]},{"t":"经漂母墓","f":"五言律诗","c":["寂寞淮阴路，荒城接楚原。","谁能怀漂母，曾此饭王孙。","孤冢今犹在，千金不复论。","自惭非国士，兹去向何门。"]},{"t":"昭君怨","f":"五言律诗","c":["掩泪向边州，君恩此日休。","身随塞上远，心是汉宫愁。","雁塞春难度，龙堆草易秋。","玉容何足贵，翻作羽林羞。"]},{"t":"山路见落花","f":"古风","c":["野花垂岭口，无主亦芳菲。","色映林僧帽，香随木客衣。","凄凉?折去，零落鸟衔归。","日暮行人绝，山风吹更飞。"]},{"t":"送林山人入城","f":"五言律诗","c":["林栖无外事，访旧入东城。","渐失闻猿处，多逢结驷行。","古榕藏驿舍，残柳拂军营。","薄暮遥钟起，纷纷薜荔情。"]},{"t":"题王孙挟弹图","f":"五言律诗","c":["金衣骑小驷，迢递茂陵山。","接鹘花边过，鸣鞭柳外还。","断猿惊羽箭，过雁落金丸。","归醉琼楼夕，天街雪正寒。"]},{"t":"秋暮寄山中人","f":"五言律诗","c":["水国催寒早，霜风几夜砧。","怀君隐居处，落叶乱山深。","野鸟无遗迹，孤云不系心。","悬知灯火夕，闲坐听猿吟。"]},{"t":"书江山别意图送羽人还神乐观","f":"五言律诗","c":["羽人何处去，归事玉宸君。","飞佩花间别，横箫鹤上闻。","过关闽树断，絓席楚江分。","想到斋宫夕，圜丘候五云。"]},{"t":"同故人曾伯刚燕集陈家楼","f":"五言律诗","c":["偶作山阳会，翻惊梦里逢。","盍簪怜草色，携手叹萍踪。","雨暗楼中树，云閒鸟外峰。","故人湖海气，应不愧元龙。"]},{"t":"书谷口云深图","f":"五言律诗","c":["连峰转幽邃，竟夕白云多。","峡里非人境，春深但女萝。","仙源空翠远，香界断钟和。","鸾鹤飘飘去，尘踪独奈何。"]},{"t":"题黄声玉环清楼","f":"五言律诗","c":["楼虚千瘴合，水木澹清华。","积雨仙源白，归云鸟道斜。","褰衣凌野翠，捲幔拂秋霞。","想见横经夕，苍藤落数花。"]},{"t":"题郁判官望云思亲卷","f":"五言律诗","c":["吴岳片云横，偏关远宦情。","乡林孤望断，客路寸心倾。","带雁迷亲舍，缘霜度客旌。","太行曾按节，千古重怀英。"]},{"t":"题陈孟敷耕图","f":"五言律诗","c":["野情鱼鸟边，孤兴寄秋田。","霜降黄花酒，山空白日眠。","云根缃帙散，林杪桔槔悬。","予亦栖栖者，遥知沮溺贤。"]},{"t":"拟唐储光羲题陆山人楼","f":"五言律诗","c":["爱尔幽栖处，楼居水木清。","松高清鹤梦，竹密助猿吟。","帘捲山光入，窗虚日色明。","独惭官府系，临眺不胜情。"]},{"t":"拟唐祖咏江南旅情","f":"五言律诗","c":["支离那可道，摇落倍凄然。","归梦将秋月，愁心对暮天。","吴山苍霭断，楚树白云连。","日夕凉风动，乡原若个边。"]},{"t":"拟唐祖咏题韩少府水亭","f":"五言律诗","c":["少府爱清晖，孤亭近翠微。","石林娱晚坐，池水净风扉。","野鹿衔花过，溪云带鸟归。","何须谢缨冕，临眺始忘机。"]},{"t":"拟唐祖咏苏氏别业","f":"五言律诗","c":["忘机依别墅，丰水带南山。","野竹连孤屿，溪云伴独閒。","鹿鸣花外去，鹤梦雨中还。","寂寂何人到，年年但掩关。"]},{"t":"拟唐王仲初边上送故人","f":"古风","c":["羌笛与铙歌，相逢奈别何。","关河孤梦断，边地几人过。","沙碛鸿声小，轮台雪片多。","看君马上去，?取醉颜酡。"]},{"t":"寒夜拥炉有怀","f":"五言律诗","c":["拥炉寒夜坐，寂寞对閒居。","冻雪千山白，情人万里馀。","京南无过雁，汶上少来书。","愁绝残灯里，横窗片月虚。"]},{"t":"送人奉使市马","f":"五言律诗","c":["使节向宛西，承恩出御堤。","千金求骏骨，万里得霜蹄。","汉武思神骥，燕昭重駃騠。","归朝应早计，苜蓿苑中齐。"]},{"t":"送僧游金陵","f":"五言律诗","c":["金陵维帝里，宫阙五云间。","师到是何日，禅西若个山。","浣衣天界晓，清梵紫金閒。","早晚门人念，东林定里还。"]},{"t":"上巳游五云寺","f":"五言律诗","c":["诗酒兰亭会，如何共远公。","行看五云里，绝似虎溪中。","清梵花台雨，名香竹径风。","未须论祓禊，自觉万缘空。"]},{"t":"暮春送人还温陵","f":"五言律诗","c":["斗酒惜分襟，温陵驿路深。","关河孤客棹，沧海故人心。","荖叶迷行旆，桐花醉客簪。","清源仙洞好，知尔日登临。"]},{"t":"征妇怨","f":"五言律诗","c":["夫婿远从征，云中路几深。","作旗馀帐帛，买剑断钗金。","被绣香兰浅，妆奁凤影沉。","年年衣上泪，随恨寄寒砧。"]},{"t":"挽黄蘖大休上人","f":"五言律诗","c":["只履复还西，令人忆我师。","空门了生灭，尘世漫凄其。","驯鸽栖新塔，灵花落故枝。","愁来双树下，空有泪如丝。"]},{"t":"送人之云雨","f":"五言律诗","c":["云中路不穷，迢递入乌蒙。","马上看山别，天涯见月同。","昆明波淡淡，金齿树朦朦。","异域空相忆，音书几日通。"]},{"t":"送人从温陵军","f":"五言律诗","c":["温陵南海上，孤剑独横行。","策马经花县，看山到柳营。","明珠来市舶，荖叶遍山城。","长揖嫖姚幕，从容论五兵。"]},{"t":"赠倭僧","f":"五言律诗","c":["参方离日本，乞食向中州。","沧海无行迹，浮天但法舟。","扶桑孤岛曙，贝叶旧房秋。","借问西来意，无言坐石头。"]},{"t":"送人使重驿","f":"五言律诗","c":["奉诏浮东海，鱼龙护去舟。","双星别鳷鹊，几日过琉球。","绝岛夷王拜，重番使节游。","归朝应早计，休起见京楼。"]},{"t":"梅花戍观练兵","f":"五言律诗","c":["笳吹动江城，将军练五兵。","水摇金甲影，风度角弓声。","戎幕斜连海，军麾绕下营。","时平严武备，非欲树功名。"]},{"t":"夏日游棋山寺","f":"五言律诗","c":["载酒空门下，林幽暑气清。","半天闻梵语，双壁隐钟声。","野鸟知禅意，孤云薄世荣。","何应谢尘事，从此学无生。"]},{"t":"夏夜泛江因造澹山","f":"五言律诗","c":["画舫宜凉夜，沧江酒气清。","星河分棹影，鸥鹭起歌声。","海旷天低水，潮平月到城。","澹山有佳处，遥见蚌珠明。"]},{"t":"送中州逸人归龙塘","f":"五言律诗","c":["幽栖何处是，积水近柴扉。","樽酒沙头别，輶轩月下归。","竹深林鸟待，村远故人稀。","遥想斋居里，狂吟竟落晖。"]},{"t":"挽林医敬仲殁爪蛙图","f":"古风","c":["君怀秦缓术，埋骨向扶桑。","昔卖人间药，今修地下方。","魂飞随汉使，客葬感夷王。","此日龙门道，清?益断肠。"]},{"t":"寄衣曲","f":"五言律诗","c":["秋风飞虏尘，闺里捣衣频。","拭泪逢边使，缄情寄远人。","不辞劳妾手，未省称君身。","莫待封侯日，归来但著新。"]},{"t":"题渔舍秋烟","f":"五言律诗","c":["茆宇邻鲛室，青山落钓舟。","菊潭霜渐冷，枫树叶皆流。","酒醒闻边雁，机閒见海鸥。","烟波随处好，妻子亦无忧。"]},{"t":"山居春晓","f":"五言律诗","c":["仙源隔几尘，林馆更宜春。","叶暗青连雨，云孤白近人。","浣衣溪沫绿，濯足野苔新。","余亦无机者，诛茅愿卜邻。"]},{"t":"都门即事","f":"五言律诗","c":["都门閒望处，车马满香尘。","禁绕龙池树，钟残凤阙春。","衣冠三辅客，剑履五侯宾。","唯有扬雄宅，门前草自新。"]},{"t":"奉赋闽藩参政凤阳张公忠孝堂","f":"五言古诗","c":["淮右多卿族，天朝重缙绅。","东胶呈彩凤，左辖应祥麟。","荒服资文化，名藩寄大臣。","一官忠孝在，三调渥恩均。","恋阙瞻天迥，荣亲爱日频。","怀英云独望，令伯表深陈。","乡远龙飞处，堂高鹤发新。","涂山青历历，濠水绿津津。","衣彩趋庭梦，腰金报主身。","甘棠何彩萃，风木忽悲辛。","霜露思泉壤，云霄睇玉宸。","心随葵藿尽，情感蓼莪真。","堂搆仍先志，纲常激后人。","所希登宰辅，特此赞皇仁。"]},{"t":"寄三衢陈八董教","f":"古风","c":["怀君属秋暮，离思满凉天。","百越孤云外，三衢独雁边。","?鸣飞楚叶，潮落见湖田。","泮水横经绿，柯山卷幔连。","醉吟官舍雨，兴扫墨池烟。","旧业闲三径，移家恋一毡。","风霜怜宦薄，雨露喜生全。","交态今寥落，相思独惘然。","逢秋惊发变，怅别使心悬。","欲拜桐溪墓，因行雪夜船。"]},{"t":"书宋儒陈烈官诰后","f":"五言古诗","c":["吾爱陈夫子，名高庆历中。","官卑心独古，迹遁道弥通。","屡荐金门剡，难羁璧水铜。","七闽沾化雨，百代仰儒风。","芸阁丝纶在，芹宫祀享同。","云孤怜故物，应复继高踪。"]},{"t":"欧阳明府弦歌亭","f":"五言古诗","c":["令尹文忠后，卢陵世代深。","青年宜带印，白日但鸣琴。","浩荡春阳泽，雍容太古音。","一亭崇礼教，百里动讴吟。","露冕朝氛净，褰帷午树阴。","风云飘逸气，山水写冲襟。","桃李清官舍，棠梨罥客簪。","昔闻常衮化，今识子游心。","高士恒分榻，贫人屡赐金。","所希金石刻，千古作佳箴。"]},{"t":"美宪佥陈公重修玉融天宝陂","f":"五言古诗","c":["咨访代宸聪，霜威八郡中。","褰帷询潦旱，按俗悯年凶。","地古潴防失，江流斥卤通。","绣衣亲计粟，玉节坐鸠工。","瘴海秋腾隼，关河晓驻骢。","已兼修废坠，非但慰疲癃。","陂水寒仍绿，鹾田岁又丰。","永贻饘粥惠，宁忘我侯功。","利泽思王景，恩波感白公。","铭心那可报，镌石纪无穷。"]},{"t":"书黄典幕磐石书室记","f":"五言古诗","c":["盘石邻幽构，青山独下帷。","别来乡望断，心远宦情微。","官舍羁黄绶，亲闱念綵衣。","秪应悬魏阙，那得恋春晖。","故国铜鱼杳，音书白雁稀。","家林唯有梦，时绕薜萝归。"]},{"t":"题新宁陈叔永环秀楼","f":"五言古诗","c":["胜地三峰峙，名家几叶繁。","太丘联远裔，沩水接长源。","飞搆冈峦入，连甍紫翠樊。","楼开孤鸟上，人语白云根。","爽气朝来合，清晖夕更繁。","旁窥冠德秀，前眺太常尊。","萧寺香林旧，隋朝古木存。","烟空遥见雁，秋杪近闻猿。","葭菼平临海，凫鹥宛在亹。","棹歌回竹浦，渔笛带枫村。","幔卷霞生席，檐虚瀑照门。","尽携山水兴，全隔市朝喧。","鱼沫吹帘影，藤花映履痕。","机忘泉满听，琴静月当轩。","萧洒衣冠里，栖迟竹素园。","境超扬子宅，人拟谢公墩。","静赏疑盘谷，幽寻讶陆浑。","高谭皆玉屑，列坐总瑶琨。","自笑东山隐，叨逢北海樽。","丹梯期再会，重与了心言。"]},{"t":"林景时云山图","f":"五言古诗","c":["鹫岭积蒙茸，连山翠几重。","险疑金粟洞，高讶玉华峰。","溪迥云藏屋，林深雨翳钟。","客帆秋外小，仙佩鸟边逢。","梦绕三花树，歌残五粒松。","考槃多在涧，惆怅独迷踪。"]},{"t":"题姑苏吴文刚中和堂","f":"五言古诗","c":["吴君有道者，隐处入松陵。","堂构中和在，人将太古称。","箕裘今奕叶，簪绶世飞腾。","榻有留徐稚，门多候季膺。","兴来书满案，欢极酒如渑。","山水长招隐，琴樽或聚朋。","桃溪春涨小，笠泽晚波澄。","芳草帘频捲，孤云几独凭。","松江全带雨，苕水半流冰。","琳馆闻霜磬，香台见夜灯。","茆亭深絓月，雪洞尽垂藤。","贤圣惟心到，乾坤一气凝。","仲尼嗟已远，兹道更谁徵。"]},{"t":"书沧州翁家藏高漫士山水图","f":"五言古诗","c":["草屋带沧波，连峰扫黛蛾。","路疑盘谷入，门讶辋川过。","野杖依松桂，春衣换薜萝。","弄琴鱼鸟近，卷幔水云多。","机静都忘世，槃成遂永歌。","纷纷人代里，缨冕欲如何。"]},{"t":"送客之扬州","f":"七言律诗","c":["广陵西上路悠悠，此日怜君赋远游。","吴岳晓钟迷远骑，楚天凉雨到孤舟。","琼花观里春何在，炀帝宫前叶渐秋。","二十四桥歌酒夜，玉箫吹断使人愁。"]},{"t":"经鄂王坟","f":"七言律诗","c":["疋马南行度浙河，汴城宫殿远嵯峨。","中兴诸将思恢复，负国奸臣主议和。","黄叶古祠寒雨积，青山孤冢夕阳多。","六和塔影西风里，陵树萧萧野鸟歌。"]},{"t":"送僧试经赴金陵","f":"七言律诗","c":["奉诏西游说梵经，秋风应到石头城。","帆飞楚水舟中饭，梦落淮山树里行。","一锡独携空界月，三车遥对广庭声。","禅心彼此随缘住，尘世空惊远别情。"]},{"t":"赠别友人之长沙牧","f":"七言律诗","c":["青年作郡被恩荣，五马萧萧向楚城。","关外叶飞乡舍远，湖南草绿吏人迎。","岭云漠漠空离恨，津树依依若送行。","君到长沙应暇日，定怀贾谊不胜情。"]},{"t":"送人游庐山","f":"七言律诗","c":["庐峰天外丽清晖，金削芙蓉合翠微。","石镜倒明华顶曙，香炉遥絓瀑泉飞。","谪仙吟处苔应没，惠远门空客到稀。","此度山人多邂逅，为君谈笑拂尘衣。"]},{"t":"江城春尽偶作","f":"七言律诗","c":["郭外空林带夕霏，海天离思远依依。","流年又逐残春去，华发空惊两鬓稀。","啼鸟落花孤梦断，白云芳草旧游非。","家园此日堪惆怅，况是天涯客未归。"]},{"t":"逢废冢有感","f":"七言律诗","c":["败圹崩茔不记时，况逢寒食最凄其。","天阴燐火沉荒树，雨积苔花入断碑。","尘世谩伤千古事，人生谁是百年期。","白杨风里堪惆怅，日暮闻猿但益悲。"]},{"t":"甲戌岁九日旅怀","f":"七言律诗","c":["客里凄凉欲暮愁，忽逢佳节倍离忧。","西风白发惭乌帽，旅舍新寒忆敝裘。","千里故人同落叶，十年归梦隔沧洲。","别来记得家林赏，黄菊花时醉不休。"]},{"t":"䝾野寺残僧","f":"七言律诗","c":["古寺萧条绝四邻，寺前松柏几回春。","月明下界犹闻磬，年老荒山少见人。","贝叶旧听双树法，衲衣孤坐两朝身。","秋风已烂蒲团草，悟得西来意自真。"]},{"t":"送人贬海南","f":"七言律诗","c":["官亭几度饮离觞，此日怜君谪远方。","马上看山椰叶暗，津头沽酒荔枝香。","秋深岭表犹多瘴，腊尽天南尚少霜。","憔悴更须怀直道，临岐何必泪沾裳。"]},{"t":"送越山隐士","f":"七言律诗","c":["怜君久住在空山，寂寂岩扉昼不关。","落木寒泉青嶂里，素琴孤鹤白云间。","五陵年少何曾到，三径秋来秪独閒。","欲问尘中何事业，青云能有几人还。"]},{"t":"温陵留别陈方山先辈","f":"七言律诗","c":["温陵雪后雁声寒，芳草青青客未还。","千里离情江上月，十年乡思梦中山。","荒城对酒应难别，远路逢春好是閒。","沧海故人零落尽，临岐那忍听阳关。"]},{"t":"题郭韩臣家藏赵大年汀渚秋烟卷","f":"七言律诗","c":["大梁公子写沧洲，几百年中墨尚留。","芳草秪疑韦曲社，青山多是洛阳秋。","天边积霭鸿初断，浦口微霜叶尽流。","遥想繁华何事业，汴河东去更悠悠。"]},{"t":"题长乐林生叔达湖山幽处","f":"七言律诗","c":["楼前积水映丹枫，清隐林扉趣不穷。","人影迥临飞鸟上，书声遥在翠微中。","青山对酒闻猿断，花屿横琴与鹤同。","此日长安凤城内，五陵车马正匆匆。"]},{"t":"题墨梅烟月景","f":"七言律诗","c":["林下花时雪更繁，萧条苔径共谁看。","空香半入高僧定，霜影全侵梦鹤閒。","任逐邻歌江上发，恐随边笛月中残。","故人天外遥相忆，欲寄南枝愧独难。"]},{"t":"喜林崇高见过","f":"七言律诗","c":["十年萍梗愧西东，千里佳期此日同。","图画秪今追北苑，衣冠谁复识南宫。","乡心几度春云外，诗思千峰暮雨中。","欲把酒杯留醉赏，沙头归佩莫匆匆。"]},{"t":"和林孔逸见寄之作","f":"七言律诗","c":["淮阴漂泊叹王孙，生事萧条一剑存。","春草閒堂思旧业，暮云孤馆寄荒村。","月明野寺同栖鹤，落叶寒山听断猿。","倾盖相逢谁似者，且陪歌舞倒芳樽。"]},{"t":"次韵陈九狂客西岩见寄之作","f":"七言律诗","c":["黄金沙界绕岧峣，钟磬微微下九霄。","禅榻鸟啼残雨过，香台经尽落花飘。","心持半偈缘应浅，身寄迷途恨独遥。","堪笑此生何住著，期君天路远相邀。"]},{"t":"赋磐石秋风送别","f":"七言律诗","c":["磐石苍苍入翠微，秋风袅袅碧罗飞。","凄凉半度谁家笛，飒沓全吹野客衣。","孤嶂断猿声渐远，荒岗残树叶将稀。","由来此处堪乘兴，何事同心又远违。"]},{"t":"次韵答高漫士 其一","f":"七言律诗","c":["萍梗飘飘未遇时，此怀唯有故人知。","离心几度曾相梦，交态于今更不疑。","黄菊青樽谁共榻，白云高馆独垂帷。","遥知玩宇楼中月，应怪登临每负期。"]},{"t":"次韵答高漫士 其二","f":"七言律诗","c":["林馆深秋黄菊残，微霜枫树叶初丹。","浮生秪解刘伶醉，失路应怜范叔寒。","落日断鸿愁里听，故园衰草梦中看。","龙门知己能相问，欲和阳春愧独难。"]},{"t":"寒夜宴别陈叔晦","f":"七言律诗","c":["县城高馆宴离觞，共对寒灯别意长。","孤嶂啼猿惊落叶，谁家残笛度微霜。","云山驿路遥相送，鱼鸟沧洲旧莫忘。","知尔怀人何处是，秣陵春树远苍苍。"]},{"t":"送林彦宾之淮上省兄","f":"七言律诗","c":["斗酒何须惜路岐，此行偏感鹡鸰诗。","青山野店淮南暮，孤棹微钟雪后时。","猿断晓关惊落叶，鸿飞沧海忆连枝。","十年官冷英山下，几度看云怅别离。"]},{"t":"玉融谢生见过","f":"七言律诗","c":["客里留君喜盍簪，天涯携手便同心。","青山旧业何须叹，野馆残尊且共吟。","沧海断鸿将落叶，夕岚疏雨带寒砧。","他乡况是交游少，萍水相逢思转深。"]},{"t":"哭陈叔晦","f":"七言律诗","c":["祗道青云定有期，忽闻长逝使人悲。","尊前握手难重会，客里论心更与谁。","月隐屋梁愁独夜，魂飞淮海梦归时。","青山何处荒坟树，未絓吴钩泪已垂。"]},{"t":"留别冯公鲁兄弟","f":"七言律诗","c":["海国微霜叶已丹，玉壶清酒夜漫漫。","天寒客路鸿声晓，月落芳江树影残。","情在不堪分手去，兴来犹恋故人欢。","惠连群从偏能赋，一曲骊歌欲和难。"]},{"t":"送蒋节庵鍊师还建上","f":"七言律诗","c":["十年江海慕清芬，何事逢君又别君。","花屿到来应几日，茆山归去独寻云。","清溪碧水琴边落，黄叶秋声鹤上闻。","自愧萍踪无住著，欲将飞佩息尘纷。"]},{"t":"送林思礼岁贡成均","f":"七言律诗","c":["十年漂泊故人稀，岁晏逢君又远违。","候馆莫鸿惊别梦，粤河残雪照行衣。","潮生楚岸风帆夕，树绕淮山驿路微。","此度桥门应早达，莫忘书札问林扉。"]},{"t":"病中喜郑浮丘见过","f":"七言律诗","c":["煮药烟中静掩门，泮林官暇动行轩。","天涯踪迹惭多病，客里心期忆共论。","空馆乱虫孤烛夜，荒原残叶数家村。","相逢未久还分别，愁倚秋风独断魂。"]},{"t":"早秋怀林良箴因忆东峰诸上人","f":"七言律诗","c":["正月孤帆别远津，秋风林下忽沾巾。","他乡久住愁双鬓，故国遥看隔几尘。","江海又逢初下叶，关河同是未归人。","坐来更忆东山赏，共对閒僧话夙因。"]},{"t":"为陈谷骏赋东墅閒居","f":"七言律诗","c":["习静何须隐翠微，一閒心远便忘机。","窗临绝屿云来近，门掩荒洲客到稀。","禾黍露寒秋酿熟，兼葭霜冷夜渔归。","知君悟得幽栖趣，却向清时■布衣。"]},{"t":"寄三衢董教陈孟敷","f":"七言律诗","c":["离别中年梦亦惊，未应王谢独关情。","家林久已无音信，江海今馀几弟兄。","浙水断鸿秋半影，粤河残叶夜中声。","遥怜姑篾千峰里，何处相思月自明。"]},{"t":"奉饯郑浮丘赴召天京二首 其一","f":"七言律诗","c":["三楚文衡忆重持，泮林宁厌一官卑。","论经已被先皇诏，怀策今逢圣主知。","长乐曙钟宫漏永，蓬莱宵烜佩声迟。","承平正尔需贤佐，莫对乡山怅别离。"]},{"t":"奉饯郑浮丘赴召天京二首 其二","f":"七言律诗","c":["黄叶山中把酒杯，行人西上凤凰台。","关河马色迎寒度，江郭鸿声带晓催。","三礼才名天下少，九重丹诏日边来。","悬知此别云泥隔，拟欲弹冠愧不才。"]},{"t":"与连川吴彦器夜酌","f":"七言律诗","c":["延陵才子旧知名，今日应怜好弟兄。","客里襟期疑是梦，天涯萍水况多情。","清秋一叶琴中落，黄菊孤尊月下倾。","倾盖相逢还又别，不堪江上断鸿声。"]},{"t":"送陈平叔归黄山","f":"七言律诗","c":["沙头宴别酒微醺，客里那堪独送君。","蓬鬓相看浑似梦，萍踪无定又离群。","黄山草圣谁同调，处士香名世共闻。","莫叹蔡邕今已老，仲容年少总能文。"]},{"t":"题玉融郑可久游建溪卷","f":"七言律诗","c":["谷口閒耕岁不丰，烟波何处寄行踪。","孤舟夜泊镡津度，九曲朝看玉女峰。","残叶市桥溪上酒，夕阳萧寺鸟边钟。","远游知有怀亲梦，应到乡山第几重。"]},{"t":"逢杨珣感旧","f":"七言律诗","c":["十年萍梗愧相违，我尚飘零子未归。","江国鸿声惊别棹，河桥草色照行衣。","他乡共叹生涯薄，往事空怜故旧知。","日暮临岐倍惆怅，伯劳东去燕西飞。"]},{"t":"近体留别杨二高隐客三山","f":"七言律诗","c":["别情羁思共何如，迢递乡山梦有馀。","仙井碧泉思旧业，客庭芳草对离居。","关河夜笛鸿飞外，海国春帆雪霁初。","愧我萍踪无住著，知君终食故江鱼。"]},{"t":"寄蒋节庵鍊师","f":"七言律诗","c":["观门迢递碧萝阴，尘迹空怀物外寻。","沧海月明人去远，瑶池秋晚雁来深。","孤云野鹤悠悠别，积水江枫夜夜心。","遥想山中多胜事，相思时复寄瑶琴。"]},{"t":"赠别王董教弟归沔阳","f":"七言律诗","c":["白酒黄花醉共驩，景陵归思又漫漫。","愁看南浦连枝别，况是西风落叶残。","三楚帆飞湘雁远，五华人去海霜寒。","故乡却恋多鱼米，应念贤兄尚冷官。"]},{"t":"送林彦时谢得圭之建上","f":"七言律诗","c":["才子溪行秋兴深，仙舟同汎复同心。","也知王粲偏能赋，谁识稽康更解琴。","驿馆夜残明候火，市楼霜晓度寒砧。","遥怜别后阳春调，客里何人为赏音。"]},{"t":"书建宁守宣城苪公敬亭山房","f":"七言律诗","c":["宛陵南面敬亭峰，山水青青思万重。","雪霁双溪寒对酒，风来远岫夜鸣松。","窗临太白看云处，门对玄晖玩世踪。","闻道一麾今出守，未应林下独从容。"]},{"t":"题宋王驸马西园雅集卷","f":"七言律诗","c":["西园簪佩日联翩，共爱风流戚畹贤。","金将池台连帝里，玉堂词翰蔼宾筵。","机閒羽士弦中意，心静林僧竹下禅。","莫向繁华惊物换，大梁宫树也萧然。"]},{"t":"闽江别意送陈伯武服阕之天官","f":"七言律诗","c":["无诸故国柳条新，折柳空江怅远人。","残雨绿芜分别路，断云归雁送行尘。","孤舟荡漾家林梦，双阙依稀帝里春。","遥想仲容终宦达，定应风木更悲辛。"]},{"t":"暮春寄曾伯刚","f":"七言律诗","c":["红烛深窗独梦君，十年多难愧离群。","愁看青浦无来雁，吟对沧波见夕曛。","枫树几回秋外落，竹枝谁忍夜中闻。","相思况是残春雨，目尽遥天漠漠云。"]},{"t":"同高漫士夜集陈叔谟山庄","f":"七言律诗","c":["倾盖相逢意转亲，六平高馆醉残春。","流年白发看花尽，几夜青灯对雨频。","心逐断鸿犹惜别，兴随芳草更留人。","龙门知己情何限，飞佩应怜寂寞滨。"]},{"t":"莫春邑中与漫士别时沧洲叟命邀不果来","f":"七言律诗","c":["县城春莫雨纷纷，歌罢骊驹厌独闻。","蓬鬓相逢俱未达，萍踪无定又离群。","绿芜客路风将远，黄鸟官亭酒半曛。","江上草堂谁倚和，杜陵白发更思君。"]},{"t":"赠别林伯予召天京兼柬郑助教董纪善 其一","f":"七言律诗","c":["蓬莱荐剡五云深，才子囊书赴上林。","双涧野僧留别偈，七岩山色寄离心。","广文官舍期同饮，记室王门待盍簪。","明到秣陵应话旧，为言江畔独行吟。"]},{"t":"赠别林伯予召天京兼柬郑助教董纪善 其二","f":"七言律诗","c":["青云知己半京华，沧海逢君又别家。","莫雨独瞻原上柏，春风遥泛日边槎。","吴门渺渺江波晚，淮树苍苍驿路赊。","闻说九重怜孝念，未应辜负旧烟霞。"]},{"t":"寄曾伯刚赵景哲","f":"七言律诗","c":["鸿雁南飞不寄声，暮云春树远含情。","白湖高馆何年别，青浦孤帆几日行。","香界竹深僧共隐，市楼花满酒同倾。","谁怜白发沧江上，閒倚东风听晚莺。"]},{"t":"为樵僧赋閒云轩","f":"七言律诗","c":["城郭纷纷静者稀，野云多恋定僧衣。","依微乍入灵花去，潇散仍随法雨飞。","心寄虚空忘色相，身将生灭悟禅机。","世人未识孤寒意，遥听经声礼翠微。"]},{"t":"秋夜陪郑助教苍林宴集分得深字","f":"七言律诗","c":["沙堰云归半夕阴，露荷烟筱净烦襟。","明河一叶秋声早，红烛虚庭醉影深。","璧水旧游千里会，青山归兴故园心。","沧洲况与苍林近，此地应期重盍簪。"]},{"t":"挽陈方山先辈","f":"七言律诗","c":["清朝遗老旧参军，几处移家远世纷。","白马公孙何事业，青袍书记向来闻。","西风野水山阳笛，秋草黄花郭外坟。","零落异乡空有泪，凭谁书记岊江云。"]},{"t":"岁暮岱峰同龙门漫士留别高景度先辈","f":"七言律诗","c":["龙门岁晚惜同心，迢递龟峰远更寻。","残雪乱山频对酒，白云芳草又分簪。","离堂夜烛猿声断，别路江枫雁影深。","名下只今多俊逸，临岐高唱比南金。"]},{"t":"送严主簿罢官归黄州","f":"七言律诗","c":["罢官归种故侯瓜，乡国苍茫楚望赊。","湘水无情空吊古，江蓠初绿暂还家。","鸾栖野棘谁同调，玉点青蝇未是瑕。","宣室他年思贾谊，更持黄纸到长沙。"]},{"t":"闽江别意赠丘孟政服阕之天官","f":"七言律诗","c":["锦袍纱帽去飘飘，风木声中思转遥。","春树暮云愁对酒，绿波芳草暂停挠。","白门月曙闻孤笛，杨子江寒见落潮。","此度宦游须补报，未应空荷圣明朝。"]},{"t":"山水图为造士陈叔能书","f":"七言律诗","c":["屋上群峰旧隐居，澹云凉月午窗虚。","满庭芳草人稀到，半亩黄精手自锄。","积水断桥寒鸟外，夕阳鸣磬夜霜初。","泮林莫羡苏门啸，未许寻山共结庐。"]},{"t":"辛巳九月邑大夫率僚佐及群士燕六平峰","f":"七言律诗","c":["薜萝迢递隐仙都，簪佩登临载玉壶。","关树早霜秋外落，奥河寒笛雁边孤。","红泉翠壁人皆醉，绿酒黄花晚更须。","此会明年谁最健，重寻山水采茱萸。"]},{"t":"奉和国子先生郑孟宣退朝听莺之作","f":"七言律诗","c":["蓬莱佳气满瑶京，禁柳青青听曙莺。","辇路乍闻千啭晓，春风遥度万家声。","近随天仗和鸾驭，散入云门间玉笙。","不独清平歌此调，高台还有凤凰鸣。"]},{"t":"书闽郡照磨江右曾公秩满之京便道省亲卷","f":"七言律诗","c":["欲赋莱衣未有期，且将簪弁恋明时。","三年考满孤琴在，千里宁亲一鹤随。","建水暮帆钟杳杳，楚城寒雁树离离。","过家暂醉西江酒，莫遣都门疋马迟。"]},{"t":"送陈乐舞省墓归闽复还天京","f":"七言律诗","c":["宫县声绕凤台春，万舞雍容对玉宸。","华表忽惊千岁别，恩波遥借一归人。","边淮独树斜连海，故陇寒楸远入闽。","莫向尘中成久别，太平天子重明禋。"]},{"t":"题姑苏王仲瑚松陵展墓图","f":"七言律诗","c":["花县宁亲著綵花，松陵回首念荆扉。","乡心正逐吴云断，离思偏逢朔雁稀。","丘陇蓬蒿随处没，边头风雪几人归。","明朝疋马姑苏道，遥望松楸入翠微。"]},{"t":"题玉融郑伯勋龙江环翠楼","f":"七言律诗","c":["旧游西上久从官，何事楼居尚考槃。","近郭雨深千树绕，沧波云尽数峰寒。","帘前落叶兼秋听，笛里飞鸿拂曙看。","好是瑞岩僧磬晚，满衣清露更凭栏。"]},{"t":"玉融潘原润将义葬其师黄山陈平叔一日持广赙集过予愧贫不能助遂赋此以赠之","f":"七言律诗","c":["布衣相对两忘贫，共忆黄山泪满巾。","高士姓名因有传，中郎书籍与何人。","墨池雨冷苔空积，笔冢秋深草自新。","惆怅一杯何所寄，唯应高谊独悲辛。"]},{"t":"简曾伯刚","f":"七言律诗","c":["逢君倾盖转销魂，多少离心不忍论。","白首异乡无旧业，青山衰草闭閒门。","关河夜雨频惊梦，雕鹗秋风久负言。","莫向樽前同感慨，旧游能有几人存。"]},{"t":"屿南宿别贡士林执中","f":"七言律诗","c":["红烛离堂酒半醒，骊歌今夕若为听。","故人好是身随桂，浮客空嗟迹类萍。","花屿晚钟湖上别，凤台春树梦中青。","应知昼绣长林下，白首还来到玉瓶。"]},{"t":"癸未元日简龙门高漫士","f":"七言律诗","c":["喜得春回共酒期，醉来持镜转堪悲。","年惭伯玉知非晚，身笑相如见遇迟。","衰鬓又逢残腊后，劳生几度改元时。","遥怜小隐龙门下，应对椒盘独咏诗。"]},{"t":"赠林士仁服阕赴京师","f":"七言律诗","c":["秋衾铜辇梦来稀，墨绶新县映赭衣。","风木不堪寒夜听，寒鸿偏向别时归。","晴天入楚千峰出，积水边淮独树微。","想到凤台朝觐后，宦游何处念春晖。"]},{"t":"题萧将军家藏山水图得青字","f":"七言律诗","c":["十年身被白云留，见尽青山到白头。","微雨数峰孤磬夕，半林残火几家秋。","风波不系袁宏棹，鱼鸟相怀谢尚游。","闻道将军戎暇日，偏能看画想沧洲。"]},{"t":"越山秋色送秦校尉还观海军","f":"七言律诗","c":["稽峰閒望赤城标，霞气苍茫水雾消。","独树过江吴地尽，断云归海楚山遥。","空林木叶惊秋雨，极浦鸿声带晚潮。","相约买舟寻贺老，知君终事霍嫖姚。"]},{"t":"送林叔仁计阶之京","f":"七言律诗","c":["泮林官满欲趋朝，况值金门早见招。","粤国青山江上别，秦淮秋水雁边遥。","砧催帝苑霜初落，马度官城叶渐飘。","若得浮丘书信便，为言衰老尚渔樵。"]},{"t":"赠林汉孟赴召天京","f":"七言律诗","c":["七峰岩下旧逃名，何事輶轩赴上京。","白首相逢萍梗别，青山谁共薜萝情。","疏烟野火丹阳骑，远树春风白下莺。","想到都门知己在，南宫西掖有逢迎。"]},{"t":"题吴景元江皋云卧","f":"七言律诗","c":["宦游西上正纷纷，何事江皋独卧云。","梦里杜兰随意绿，镜中鱼鸟向人分。","潮归沙馆当窗见，渔唱枫洲卷幔闻。","身外浮名都不系，唯应林叟得逢君。"]},{"t":"和林孔逸见寄之作","f":"七言律诗","c":["西岩爽气乱峰头，此地曾陪静者游。","雨霁珠林芳草遍，春深兰若落花幽。","清池白石俱禅意，野服黄冠半道流。","自愧浮生无住著，飘然江上一孤舟。"]},{"t":"送刘监生还京","f":"七言律诗","c":["官船一棹大江流，才子还京赋远游。","帆带夕芜依御苑，梦随凉月到家楼。","长淮雁影催寒曙，近郭砧声报晚秋。","此度金门应早达，莫令乡舍久淹留。"]},{"t":"送浮丘郑先辈被命重赴京师","f":"七言律诗","c":["丹阳京口暝烟收，几度劳歌送客游。","吴岳晓连秋雨碧，御河寒带雁声流。","衣冠召对金门里，文翰周旋玉案头。","闻道汉庭深顾问，承平不遣贾生忧。"]},{"t":"赠别林孔逸从蓟丘军","f":"七言律诗","c":["越城砧杵暮纷纷，多少閒情此送君。","别路寒山惊落叶，深秋孤雁忍离群。","苏门日照霜中树，羌笛寒凄塞上云。","闻道汉南曾独立，也将书剑去从军。"]},{"t":"寄凤池故人钟大","f":"七言律诗","c":["谷口遥钟半掩门，疏灯空馆住荒村。","棕榈叶上惊新雨，砧杵声中忆故园。","多难未销豪杰气，长贫难荅旧交恩。","凤池月色歌钟里，应念残山独听猿。"]},{"t":"书延平王将军闽山胜览卷","f":"七言律诗","c":["远携兵印镇南州，山水青青马上游。","玉帐醉看华顶溜，雕弓閒挂剑潭秋。","双溪树底泉声合，九曲花边瘴雨收。","自是承平多胜事，七闽应许擅风流。"]},{"t":"寄沧洲狂客","f":"七言律诗","c":["三年憔悴得君怜，君上青云益惘然。","客里思乡何日到，天涯见月几回圆。","未期岁晚同携手，预恐新正对别筵。","贫贱独惭无可赠，临岐空忆绕朝鞭。"]},{"t":"奉荅陈沧州","f":"七言律诗","c":["白发沧洲似者稀，瑶华应愧寄林扉。","每怜独客如萍梗，更有何人惜布衣。","梧叶满庭残暑退，青山对酒小凉归。","莫愁璧水音尘远，早晚关河候雁飞。"]},{"t":"寄刘大","f":"七言律诗","c":["閒宵灯里梦刘郎，梦觉还惊是两乡。","孤馆几回江上月，流年空度镜中霜。","青蒲野水林扉静，黄鸟山亭酒瓮香。","遥想丘园多乐事，也应飞札慰离伤。"]},{"t":"留别黄山周氏兄弟","f":"七言律诗","c":["候馆逢霜落叶深，更堪憔悴对青衿。","荒村野水残阳路，远树孤云故国心。","绝地也怜频送酒，情多谁忍更分襟。","惠连群从皆清俊，别后相思总解吟。"]},{"t":"文笔山房为延平郡造士朱员赋","f":"七言律诗","c":["文笔山深隔翠微，清晖迢递映书闱。","门临绝涧逢人少，帘捲孤峰见雁飞。","四壁泉声喧午梦，半檐藤影落秋衣。","镡津自昔多才俊，词翰如君世所稀。"]},{"t":"挽黄山周正卿","f":"七言律诗","c":["与君相识便相知，却叹相逢最后时。","沧海几回明月夜，黄山终负薜萝期。","秋风野水寒猿断，落叶荒原吊客悲。","遥想泉台今不恨，传家应有凤毛奇。"]},{"t":"书番阳戴氏侍萱堂卷","f":"七言律诗","c":["乐平才子旧知名，曾是清朝被宠荣。","萱草别来应有梦，白云频望不胜情。","关河迢递娱亲舍，铜绶淹留近海城。","他日锦衣归省去，故园鄱水有馀清。"]},{"t":"欧阳明府江上草堂","f":"七言律诗","c":["青原山上草堂开，竹杖黄冠日往回。","雨过新潮低卷幔，云连孤嶂落衔杯。","闻棋每忆林间榻，静钓还思石上苔。","佳政秪今人共说，未应陶令赋归来。"]},{"t":"题晦之城南秋堂","f":"七言律诗","c":["汾阳孙子久忘机，万卷经书隐翠微。","闭户不知秋叶落，卷帷时见白云飞。","岩花色映乌纱帽，涧水声寒薜荔衣。","想是过庭趋讲暇，也应城市往来稀。"]},{"t":"题郑浮丘碧蕉书馆","f":"七言律诗","c":["郑老心閒却忘官，泮林唯对碧蕉閒。","盈轩色映乌纱帽，拂几凉生苜蓿盘。","半榻秋声寒外落，一帘幽梦月中残。","杜陵野老时相问，应遣题诗叶上看。"]},{"t":"玉融陈氏怡怡堂","f":"七言律诗","c":["魏帝连枝不共荣，淮王斗粟若为情。","风霜况是同根蒂，骨肉应怜好弟兄。","山色晓帘沙雁白，海天秋屿雪鸪鸣。","合欢也似姜肱被，长奏埙篪酒共倾。"]},{"t":"题江山烟雨图","f":"七言律诗","c":["梦渚苍苍入楚烟，岳阳南面雨如悬。","人家寂历青枫外，仙峤空濛独雁边。","飞阁迥临闻笛处，微钟遥到钓鱼船。","孤帆莫向潇湘浦，云暗苍梧水泊天。"]},{"t":"次韵答黄嗣杰","f":"七言律诗","c":["满林乌桕飘残臈，独客关心漫倚楼。","几处移家惊落叶，十年归梦在孤舟。","青塘野鸟当窗白，积雨寒山卷幔幽。","何似董湖高隐处，朝朝巾舄与同游。"]},{"t":"题郑克曼复睢阳军手卷","f":"七言律诗","c":["绿发辞乡白发归，远因行役问庭闱。","离心又惜连枝别，愁思仍随独雁飞。","汴河霜落寒砧早，梁苑烟空晚树稀。","行到洛阳秋色后，柳营长是忆春晖。"]},{"t":"题澹游雨竹图","f":"七言律诗","c":["孤舟凉雨楚溪头，叶叶寒声镜里秋。","湘水夜传金奏响，郢云朝拂玉英流。","空香暗逐王孙梦，残粉深关帝子愁。","鸣凤不来春杳杳，为谁遗牒向中洲。"]},{"t":"送粮长林思器赴召京师 其一","f":"七言律诗","c":["王贡曾稽夏禹篇，汉庭输饷独推贤。","遐方已献编民数，大姓应操赋粟权。","千里山河趋魏阙，一帆秋水入吴天。","枫墀若听纶音后，归兴西风白雁前。"]},{"t":"送粮长林思器赴召京师 其二","f":"七言律诗","c":["酒尽沙头白玉瓶，海云关树远行经。","孤舟落叶丹阳渡，残笛秋风白下亭。","三楚人烟天外小，六朝山色雁边青。","怜君此去应观国，行听韶音到广庭。"]},{"t":"送林思隐之金陵","f":"七言律诗","c":["布衣何事欲朝天，螺渚霜空见发船。","闽树晓关分楚泽，越城寒火接吴烟。","白门酒熟谁同醉，华馆灯孤笑独眠。","阙下名公多旧识，莫令归兴后春前。"]},{"t":"同沧洲翁答高漫士兼寄高牧隐","f":"七言律诗","c":["多病文园兴未休，沧洲鱼鸟待君游。","花边复扫留徐榻，矶畔空期访戴舟。","渤海诗名今独步，蓝田牧兴世争求。","悬知牧隐风流在，共醉清晖半占秋。"]},{"t":"耿将军具庆堂","f":"七言律诗","c":["曾逐嫖姚立战勋，汉庭方识耿将军。","千钟已遂荣亲愿，一剑常思报主勤。","花拂莱衣春尚早，月明姜被夜初分。","东吴此乐应稀少，忠孝于今几处闻。"]},{"t":"秋日寄王介轩先辈","f":"七言律诗","c":["林下萧条隐角巾，黄花时节忆同人。","陶潜解印宁辞倦，苏晋长齐岂是贫。","华发流年看独变，青山明月梦来频。","近闻筹谷多仙赏，忘却沧洲野水滨。"]},{"t":"寄林彦衡训迪嘉禾","f":"七言律诗","c":["欈李山川接上腴，鱼盐粳稻满东吴。","横经不道官犹冷，禄薄还堪酒屡沽。","霜落乡林思旧橘，秋深江郭忆寒鲈。","绨袍别后情何限，莫惜新吟寄野夫。"]},{"t":"次韵答王介轩 其一","f":"七言律诗","c":["曾是天池缀晓班，绣衣行郡远人欢。","秋风忽梦柴桑柳，故畹还歌楚泽兰。","匣里吴钩谁复羡，尊前郢曲和皆难。","佳期忆在来清馆，共对榕霜五夜寒。"]},{"t":"次韵答王介轩 其二","f":"七言律诗","c":["懒慢唯应漉酒巾，鹑衣无计合时人。","一瓢陋巷谁能问，四壁秋风独忘贫。","北阙青云随梦远，西山明月忆归频。","卜邻幸与沧洲近，又欲移家住海滨。"]},{"t":"送郁判官秩满之天官","f":"七言律诗","c":["东胶冠盖旧称贤，佐郡曾分刺史权。","官署到来应似水，礼闱今去独朝天。","家临故苑长洲树，钟度寒山半夜船。","遥想五云霄汉上，从容又赋帝京篇。"]},{"t":"书王明府家庆","f":"七言律诗","c":["几年戎马怅分飞，此日君恩赐独归。","张掖寒云行处满，鲁城霜雁别来稀。","西江买棹寻花县，南国趋庭换绿衣。","官满他年应昼绣，吴门乡树碧依依。"]},{"t":"赠邑造士陈汝登之军中","f":"七言律诗","c":["汉家烽火在边庭，才子西行独请缨。","自是寸心怀补报，也将孤剑学从征。","天门久欲陈三策，沙漠今看论五兵。","莫对泮林愁此别，他年还著锦衣荣。"]},{"t":"典幕席上同高漫士奉和王尹元旦密州忆子诗","f":"七言律诗","c":["张掖何人独冠军，远随征骑入边尘。","天涯柏酒愁中断，寒尽椒花客里春。","鲁国山河应独望，甘州风物更谁亲。","斑衣此日棠阴下，骨肉何须叹越秦。"]},{"t":"奉寄龙门高漫士牧隐二先辈","f":"七言律诗","c":["玩宇平临半占峰，清晖遥映翠微松。","云来鸡屿应还倦，鸟下龙门去亦慵。","池草任随吟处长，江花偏待醉时逢。","十年自笑无家别，谁念沧浪远寄踪。"]},{"t":"挽陈方山先辈","f":"七言律诗","c":["七闽冠盖盛繁华，白首温陵独寄家。","爱客尚悬高士榻，隐居唯种故侯瓜。","归魂杳杳乡林晚，旅榇迢迢驿路赊。","谁料别来成叹逝，九原长望使人嗟。"]},{"t":"寄别陈志鸿罢官归高凉 其一","f":"七言律诗","c":["解印行歌出将营，千军流泪共含情。","邹阳书上谁称屈，王粲才高赋谩成。","天连故国铜鱼远，霜落寒江白雁鸣。","自愧神交惊此别，不堪离恨更沾缨。"]},{"t":"寄别陈志鸿罢官归高凉 其二","f":"七言律诗","c":["得官何似罢官閒，闽海秋风一骑还。","五岭黄茆通驿路，百城寒水接乡关。","离心不醉霜中柳，归梦应寻鸟外山。","闻说旧游多鹗荐，未应空老薜萝间。"]},{"t":"浮丘郑公国子助教余病不能饯寄诗以别 其一","f":"七言律诗","c":["成均典教遂忘机，圣主恩深许暂归。","疋马又从江上别，孤舟还向雁边微。","初霜落叶惊吴苑，夜火寒砧入帝畿。","自笑不才逢盛世，故山空老薜萝衣。"]},{"t":"浮丘郑公国子助教余病不能饯寄诗以别 其二","f":"七言律诗","c":["荒居病起对空林，邻笛谁堪折柳音。","白首襟期惊是梦，沧波离别惜同心。","梨关月出鸿声小，笠泽天寒骑影深。","遥想圣朝多雨露，未应官冷解朝簪。"]},{"t":"题松山司警余公海城春意","f":"七言律诗","c":["曾劳弓剑事边尘，复绾铜章领徼巡。","匹马向经吴地雪，一官遥寄越城春。","莺花水镇朝衙静，虾菜江乡夜逻频。","三载铨闱应不负，定知霄汉沐恩新。"]},{"t":"赠琉球典簿程氏赐归番易","f":"七言律诗","c":["冠带趋朝沐宠光，曾将声教化夷王。","扶桑东际非吾土，彭蠡西流是故乡。","白首还家江上骑，青山独对雪边房。","悬知陆贾风流在，不羡裴家绿野堂。"]},{"t":"送陈履中侍大父入京","f":"七言律诗","c":["君家大父远朝京，念尔辞家侍此行。","绿酒红亭西上路，白云乡树故关情。","孤帆夜落秦淮水，双阙时闻禁邸莺。","莫道重闱今别去，乡人遥待锦衣荣。"]},{"t":"挽江山陈仲晋","f":"七言律诗","c":["墨绶新悬鬓己皤，宦游西上易蹉跎。","青山竟掩孤坟在，浮世仍传并秀多。","门柳不堪愁里赋，琴台谁忍醒时过。","愧无公子鱼肠剑，挂向空林野树柯。"]},{"t":"送闽藩从事考满","f":"七言律诗","c":["西游怅饮气偏豪，多少同声惜户曹。","别路断鸿将去棹，乱山残雪送征袍。","蓬莱春近莺声早，阿阁云开凤影高。","明到五门朝觐后，相思空有梦魂劳。"]},{"t":"赠陈逸民","f":"七言律诗","c":["万事忘机一布裘，似君宜向古人求。","秋风几度惊双鬓，夜梦无应到五侯。","多暇兴来犹散帙，老年身倦少登楼。","蔡家尚有文姬在，对酒当歌且莫愁。"]},{"t":"连川赵原沧洲图","f":"七言律诗","c":["冠盖纷纷多宦游，怜君生事寄沧洲。","半池草梦飞残雨，一片荷衣挂远秋。","卷幔云山天外小，近人鱼鸟镜中幽。","遥知霜露松门夕，秋气寒泉兴未休。"]},{"t":"偕陈叔韬宿崇山兰若期少尹陈思孝不至赋得近体一首遂书于壁","f":"七言律诗","c":["化成烟磬晚微微，何事同心也负期。","双树焚香栖鸟定，空山对酒白云随。","风飘仙梵清机远，月隐禅枝夜坐迟。","明发寄声贤少尹，支公浑似郑当时。"]},{"t":"送兵卫从事考满赴铨","f":"七言律诗","c":["几年从事总兵机，千里輶轩入帝畿。","骠骑别时多载酒，故人分处尚留衣。","秦淮远火春鸿断，长乐微钟晚雪稀。","闻道宦游西上好，莫将莼菜忆东归。"]},{"t":"赠张明府入奏","f":"七言律诗","c":["满县棠梨春著花，郎官书奏觐京华。","帆开楚水犹逢雁，道过金坛得到家。","紫禁曙钟云外听，白门春酒日边赊。","遥知马首春归早，不待青门尽种瓜。"]},{"t":"送人代兵后还乡","f":"七言律诗","c":["十年弓马似君稀，到老还乡愿不违。","祖道百壶孤棹别，温陵千里远人归。","江桥夜火霜蚝熟，野馆秋风海菜肥。","好是北堂调膳后，閒看儿女笑牵衣。"]},{"t":"和詹时雨哭永宁许将军","f":"七言律诗","c":["剑锋销尽马啼穿，夷虏凭陵尚寇边。","谁念将军能死国，远持兵印独归泉。","荒城听雨伤秋早，沧海招魂怆暮烟。","忠愤向来同感激，温陵南望泪潸然。"]},{"t":"奉寄齐府纪善郑孟宣召还京","f":"七言律诗","c":["三年书信远寥寥，知在临淄道路遥。","空使多情长忆别，谁知白首得还朝。","曳裙几醉齐门酒，奉使应劳汉使轺。","想到九重频顾问，好陈三策辅唐尧。"]},{"t":"寄陈仲全编修兼左春坊","f":"七言律诗","c":["宛陵曾采泮芹香，一上銮坡被宠光。","禁里疏钟移夜直，花间鸣佩出春坊。","思家几度江田绿，念别休惊陇树黄。","遥羡阿戎同禁苑，朝朝如在竹林乡。"]},{"t":"高待诏自京回必逊王修撰寄声相问赋诗以答之","f":"七言律诗","c":["几年分教向长沙，此日摛文在帝家。","清禁日斜还视草，白门朝退暂看花。","玉壶载酒多同醉，青鬓流年想未华。","近得故人天上别，感君传语问烟霞。"]},{"t":"寄翰林王孟敷兼促皆山樵记","f":"七言律诗","c":["钓鲈桥上惜分簪，别后闻君入禁林。","近道相如能献赋，谁言贾谊少知音。","永阳独树还家梦，魏阙晴云捧日心。","寂寞山林樵采事，何时为记比南金。"]},{"t":"诗寄梁浮丞陈思孝工篆入翰林","f":"古风","c":["故人西上怅离魂，几度封书寄荜门。","别梦正悬江口雁，相思谁那岭头?。","晨朝染翰临飞阁，日夕闻钟出禁垣。","宸睿若教金石刻，知君不久独承恩。"]},{"t":"寄赠林志仁博士","f":"七言律诗","c":["麟经独抱上王畿，宫锦新裁博士衣。","六馆夜凉闻漏起，五门天曙退朝归。","凤凰台上吹箫迥，鳷鹊楼前见雁飞。","西掖环林应不远，相逢休道故人稀。"]},{"t":"寄潘源润因悼黄山陈平叔","f":"七言律诗","c":["偶因行客问潘郎，忆得黄山醉墨堂。","斗酒几回浇宿草，松门何处闭秋霜。","尺书不到边鸿断，三径犹存旧业荒。","何日远寻高待诏，扁舟能过辋川庄。"]},{"t":"寄玉融郑三秀才","f":"七言律诗","c":["空斋病起怯秋声，无那啼鸪向夕鸣。","凉雨一天孤烛夜，断鸿千里故人情。","寒花浥露江蓠白，独树含霜瘴海清。","遥羡胜游多上日，瑞岩僧舍喜逢迎。"]},{"t":"三山林文质索咏鹤骨笛","f":"七言律诗","c":["谁窍青田一片霜，宛疑横吹到山阳。","声兼陇水将魂断，曲尽梅花带髓香。","华表仙歌惊落月，瑶台秋梦怨清商。","唯应吹上天坛去，好伴云璈事玉皇。"]},{"t":"为林中洲题马图","f":"七言律诗","c":["汉家神骥出宛西，凤臆兰筋破月蹄。","冀北群空知汗血，长杨猎罢见霜蹄。","青丝引辔穿花入，黄帕蒙鞍对御嘶。","莫道时平淹栈豆，飞腾思与六龙齐。"]},{"t":"挽鳌峰十二明","f":"七言律诗","c":["伤心叹逝恨千重，云想秋衣月想容。","青草泉门今独闭，绿樽池馆几时逢。","棋山访寺馀残雪，花屿寻春有旧踪。","何处临风堪洒泪，沙头南望见鳌峰。"]},{"t":"谢得圭东岚秋思图","f":"七言律诗","c":["海上仙山连翠岑，夕岚孤树远沉沉。","遥天落叶鸿边尽，绝岛残钟雨外深。","烟火数家馀旧业，渔樵几处动归心。","秋来好是莼鲈美，知尔看图忆故林。"]},{"t":"高要严氏具庆堂","f":"七言律诗","c":["严助閒堂野水滨，每同兄弟日娱亲。","到家几度瞻云迥，恋阙还应爱日频。","山色半帘铜鼓曙，潮声入坐顶湖春。","史臣定写茆容传，笑拂端溪紫石匀。"]},{"t":"海天离思送林生复琼州军","f":"七言律诗","c":["十年弓骑向边州，暂喜还家又别愁。","绿酒江亭乡树晚，断云南雁海天秋。","鲸波万里孤舟远，椰叶千峰片雨收。","明到琼台霜渐冷，知君长夜看吴钩。"]},{"t":"初秋留别石田阜阳诸公 其一","f":"七言律诗","c":["相逢那忍别匆匆，绿酒清诗兴不穷。","病起异乡惊暮雨，坐来高馆见秋风。","关河一叶离声里，江郭千峰醉影中。","堪笑人生多是别，盍簪能得几回同。"]},{"t":"初秋留别石田阜阳诸公 其二","f":"七言律诗","c":["石田佳处阜阳亭，几度清游到玉瓶。","金井夜凉初叶下，石门云尽数峰青。","林间扫榻同僧定，洞里鸣琴共鹤听。","正好欢携仍又别，不堪愁思晚冥冥。"]},{"t":"怀安蒋明府望云思亲卷","f":"七言律诗","c":["马上闽关若太行，白云飞处似河阳。","宁教带雨将归梦，莫更因风度远乡。","亲舍几回空外忆，宦情偏向此中忘。","遥知吏散棠阴下，柱笏行看欲断肠。"]},{"t":"挽梅江陈以仁先辈","f":"七言律诗","c":["龙峰耆旧几人存，独客心悲不忍论。","华表鹤归尘梦远，少微星坠海云昏。","留宾别馆空悬榻，点易寒窗静掩门。","零落为君歌薤露，行人无泪也销魂。"]},{"t":"题宪检校沈公望云图","f":"七言律诗","c":["隐侯家世巽湖阴，何事看云怅别心。","亲舍几年违色养，宦游千里戴华簪。","乌台月暗怀乡远，鹤发秋来入梦深。","自昔忠臣缘孝子，白华歌尽有馀音。"]},{"t":"赠判官秩满赴天官","f":"七言律诗","c":["府僚官满动行轩，西出闽关望白门。","千里独随征骑别，一廉多付路人言。","趋朝不用逢杨意，荐剡于今有巨源。","明到南宫应考绩，政成此外更何论。"]},{"t":"送邑造士萧戴贡胄监兼似国子博士林志仁","f":"七言律诗","c":["西上青云引兴浓，泮林才子蹑仙踪。","边淮独树千峰雪，极浦寒山半夜钟。","璧水到时春雁尽，金门朝退故人逢。","风流博士如相问，白首林泉事事慵。"]},{"t":"暮春宴集海田张氏家楼","f":"七言律诗","c":["谷雨新晴海气凉，远山楼外色苍苍。","烟深野树闻歌鸟，风急飞花落羽觞。","玉屿金塘看月出，锦筵红烛醉宵长。","独怜踪迹犹萍梗，客里挥毫谩自伤。"]},{"t":"赠邑长史高凉黄惟成","f":"七言古诗","c":["赞襄花县独驰名，高论心閒政自平。","寸禄只充沽酒费，一廉谁似到官清。","公馀束带横经坐，吏散空庭著履行。","芹泮下车严释菜，棠阴悬榻待时英。","宦游此日非梅福，宣室他年是贾生。","宛马向来空冀北，吴钩终见发丰城。","高凉月隐乡林梦，淮泗秋深魏阙情。","知尔长才姑小试，不惭黄宪旧家声。"]},{"t":"夏日游棋山寺燕集","f":"七言古诗","c":["尘中何处避炎蒸，静爱空王澹爱僧。","沙界树凉晴作雨，石渠泉响暗流冰。","青山载酒随閒到，飞阁观潮倚醉登。","水绕莲花通宝藏，路回兰若转金绳。","仙人棋局埋幽草，开士禅扉闭古藤。","荒殿鸟啼时近榻，香台狷卧夜窥灯。","老来行止愁无地，病后欢携愧有朋。","明发别离方外去，何时清兴又同乘。"]},{"t":"挽镏牧","f":"七言古诗","c":["龙阳孙子参军裔，簪绂承家世已长。","千里河流通地脉，一天奎壁焕星潢。","衣冠况复明三礼，文采唯应备九章。","华馆朋来秋寂历，枫江云断夜凄凉。","贾生年少人皆惜，李贺才多世共伤。","新垄渐随蒿里没，旧书犹带泮林香。","云迷花屿空飞梦，月暗满江更断肠。","惆怅筹峰峰下路，一回行到一沾裳。"]},{"t":"送刘逸人还山中","f":"五言绝句","c":["落日鹧鸪鸣，遥村送独行。","峰回看不见，望望有馀情。"]},{"t":"秋阴","f":"五言绝句","c":["寒云将远空，落叶与飞鸿。","汉苑秦陵外，悲凉是此中。"]},{"t":"黄叶","f":"五言绝句","c":["带雨飘阶冷，随风著幔凉。","愁心故宫树，片片落寒霜。"]},{"t":"闻渔笛","f":"五言绝句","c":["渔人将楚竹，吹向月明中。","莫奏凉州曲，金河有断鸿。"]},{"t":"归鸟","f":"五言绝句","c":["片影云边没，孤声月下微。","云霄千万里，何似故巢归。"]},{"t":"听?","f":"五言绝句","c":["十年闻笛恨，此夕更沾襟。","别泪三声下，孤愁一夜深。"]},{"t":"柳塘鹭鸾","f":"五言绝句","c":["烟柳拂波声，霜衣汎日明。","青山对孤影，宁倦五湖情。"]},{"t":"访邓山人","f":"五言绝句","c":["飞鸟落藤花，林幽小径斜。","白云深解意，相与到君家。"]},{"t":"踏青","f":"五言绝句","c":["雨晴原草新，黄鸟恋行尘。","年少看花伴，如今有几人。"]},{"t":"草色","f":"五言绝句","c":["拂拂度林坰，霏霏上野亭。","王孙归未得，空向雨中青。"]},{"t":"沧洲十咏 其一 绿湖","f":"五言绝句","c":["云归蘋叶齐，雨积波声小。","日夕水容青，飞来双白鸟。"]},{"t":"沧洲十咏 其二 渔艇","f":"五言绝句","c":["白鸥将野棹，荡漾波光冷。","木落秋气多，孤篷逗霜影。"]},{"t":"沧洲十咏 其三 莲塘","f":"五言绝句","c":["荷静香露圆，波深藕根白。","白晢谁家儿，折花水边剧。"]},{"t":"沧洲十咏 其四 古柳堤","f":"五言绝句","c":["寒潮落沙堰，高柳入荒烟。","莫把长条折，秋来欲系船。"]},{"t":"沧洲十咏 其五 白沙冈","f":"五言绝句","c":["连峰沙似雪，迢递带沧波。","好是残阳外，人稀野鸟多。"]},{"t":"沧洲十咏 其六 钓矶","f":"五言绝句","c":["片石翳云根，隐映波光晓。","君看直钓翁，机静忘鱼鸟。"]},{"t":"沧洲十咏 其七 桃花蹊","f":"五言绝句","c":["幽蹊入林深，仙花满高树。","笑谢沧洲人，来去桃源路。"]},{"t":"沧洲十咏 其八 竹里轩","f":"五言绝句","c":["露叶凝晓烟，霜枝老苔石。","夜半独行时，清凉满巾舄。"]},{"t":"沧洲十咏 其九 瓜圃","f":"五言绝句","c":["烟蔓日已长，露花日已滋。","为问东陵子，何似青门时。"]},{"t":"沧洲十咏 其十 秋香亭","f":"五言绝句","c":["池净秋气寒，黄花日朝露。","卷幔待情人，幽香满林路。"]},{"t":"郑山人幽居","f":"五言绝句","c":["林虚孤鸟白，花落乳泉香。","寂寂垂萝下，图书共一床。"]},{"t":"漫兴","f":"五言绝句","c":["乱山波上远，片片似修眉。","山下蘼芜草，春来感别离。"]},{"t":"苔","f":"五言绝句","c":["要路何曾著，閒门积渐多。","五陵松柏外，随雨上盘陀。"]},{"t":"春原牧马图","f":"五言绝句","c":["芳草满春原，青骊度郭门。","回看天厩上，若个是承恩。"]},{"t":"度白鹤岭","f":"五言绝句","c":["鹤岭翠微分，山行半白云。","停骖不忍去，前路市声闻。"]},{"t":"夏夜山中","f":"五言绝句","c":["静夜月微明，翛然万籁清。","山禽忽飞起，偏傍竹林鸣。"]},{"t":"水墨枯木","f":"五言绝句","c":["色借苍苔古，春随野蔓空。","回看五陵上，无树起秋风。"]},{"t":"宿鸟","f":"五言绝句","c":["深林纤月上，啧啧独栖时。","夜半山风急，惊飞过别枝。"]},{"t":"陈沧洲游方广岩不果行","f":"五言绝句","c":["闻说乘溪棹，寻源过水西。","如何雨花处，欲往路先迷。"]},{"t":"王将军席上赋旧战袍","f":"五言绝句","c":["先皇亲赐锦，著向战场秋。","销尽蟠花色，将军更未侯。"]},{"t":"题鸲鹆","f":"五言绝句","c":["毛衣如涴墨，性慧独能言。","寂寂空山去，休随众鸟喧。"]},{"t":"赠人游北京","f":"五言绝句","c":["胜游何太远，飞佩入燕京。","惟有湾河水，东流是旧声。"]},{"t":"秋猎","f":"五言绝句","c":["猎马向风飞，雕弓白锦衣。","平明射雕去，日暮五陵归。"]},{"t":"落叶","f":"五言绝句","c":["秋风林下起，乱叶正纷纷。","只可醉时看，不堪愁夜闻。"]},{"t":"使客","f":"五言绝句","c":["弓骑猎平原，春衣污酒痕。","经过无旧主，苔闭孟尝门。"]},{"t":"送老兵还乡","f":"五言绝句","c":["解剑辞边将，萧条白发新。","无家也归去，胜作异乡尘。"]},{"t":"初秋寻乌石兰若","f":"五言绝句","c":["不到禅扉久，灵花又早秋。","白云飞欲去，还被远公留。"]},{"t":"为灵武王孟扬题水墨扇头","f":"五言绝句","c":["飞步凌翠微，竦身出林杪。","孤笑不可攀，云边数峰小。"]},{"t":"林良箴溪山秋兴扇面","f":"五言绝句","c":["万叶琴边落，孤云鸟外微。","家林好归去，谁厌薜萝衣。"]},{"t":"题画二首 其一","f":"五言绝句","c":["虚舟泊回潭，烟澹水容夕。","谁解沧浪心，山空月下白。"]},{"t":"题画二首 其二","f":"五言绝句","c":["微风漾花潭，夕景澄天镜。","孤棹信潮回，苍茫海波迥。"]},{"t":"题葡萄","f":"五言绝句","c":["斗酒别凉州，明珠落贝丘。","似将寒露影，添作汉宫秋。"]},{"t":"题东篱晚香图","f":"五言绝句","c":["池上凌霜菊，别来凡几秋。","今朝见图画，忽起故园愁。"]},{"t":"书墨菊","f":"五言绝句","c":["翠叶迎晚烟，黄花过秋雨。","我思柴桑人，西风但延伫。"]},{"t":"书黄桂家画鸽鹑","f":"五言绝句","c":["争饮耻群鸡，高飞谢黄鹄。","落日坡草寒，萋萋惯幽独。"]},{"t":"书墨竹二首 其一","f":"五言绝句","c":["何处动秋声，摵摵筼筜玉。","遥夜清不眠，怀人在空谷。"]},{"t":"书墨竹二首 其二","f":"五言绝句","c":["㲯毵翡翠羽，错落珊瑚枝。","凤鸟久不至，琼箫空自吹。"]},{"t":"书海棠禽","f":"五言绝句","c":["袅袅棠梨枝，珍禽啄花去。","一片落长门，思君恐迟暮。"]},{"t":"书梅花双雀","f":"五言绝句","c":["几欲衔环去，天寒旧路迷。","梅边偶相得，并作一枝栖。"]},{"t":"书林景时效米老","f":"五言绝句","c":["云雨时青枫，寒山野望中。","谁将醉时墨，遥寄米家风。"]},{"t":"书陈平叔山水扇头","f":"五言绝句","c":["鸟没山意寒，渔归水容夕。","长啸望林扉，微风动萝薜。"]},{"t":"题画","f":"古风","c":["白首支离傲世，青山独坐忘言。","长啸一声何处，断云流水仙源。"]},{"t":"书扇头","f":"古风","c":["茅屋垂萝野烟，青山独树凉蝉。","白首岂能忘世，桐江未胜滋泉。"]},{"t":"题水墨小景二首 其一","f":"古风","c":["白鸥门外孤艇，黄叶山中一瓢。","惆怅青云旧侣，相思不到渔樵。"]},{"t":"题水墨小景二首 其二","f":"古风","c":["绝顶閒云翠微，孤琴野杖荆扉。","惆怅同声别远，青山叙日行归。"]},{"t":"墨竹","f":"古风","c":["秋影半枝金薤，上池凉露何多。","谁把玉箫吹断，湘江一夜寒波。"]},{"t":"书山水图为希召作","f":"古风","c":["绿树村边茆舍，暮云江上渔舟。","白发青山归去，玉堂金马悠悠。"]},{"t":"送人从北平军","f":"七言绝句","c":["蓟门霜叶正纷纷，不见燕台只见云。","君去试看台下草，何人更忆乐将军。"]},{"t":"匈奴牧马图","f":"七言绝句","c":["草白阴山朔雪晴，匈奴牧马近燕城。","只今犹有湾河水，日夜东流恨不平。"]},{"t":"兰亭怀古 其一","f":"七言绝句","c":["曲水飞觞迹渐陈，山中花木几回春。","风流内史归何处，空使今人忆古人。"]},{"t":"兰亭怀古 其二","f":"七言绝句","c":["祓禊亭中自渐低，昔人行处草萋萋。","多情最是山阴鸟，啼向春风满会稽。"]},{"t":"杜鹃花","f":"七言绝句","c":["蜀鸟啼来口血深，染成花萼满空林。","芳魂不逐风吹散，还向天涯醉客心。"]},{"t":"西岩兰若","f":"古风","c":["白云深处磬声微，祗树林幽映竹扉。","几度月明禅榻夜，洞?溪鹤也忘机。"]},{"t":"寄山中友","f":"七言绝句","c":["一别青山音问稀，白云流水思依依。","不知老鹤巢边树，几度开花几度飞。"]},{"t":"题方壶道人山房二首 其一","f":"七言绝句","c":["洞门一径入烟霞，九曲溪泉绕洞斜。","铁笛一声山月冷，独骑黄鹤问仙家。"]},{"t":"题方壶道人山房二首 其二","f":"古风","c":["羽人住处是仙源，蔓草藤花掩洞门。","看罢黄庭人不见，唯馀寒溜与霜?。"]},{"t":"题张良归山图","f":"七言绝句","c":["抽却朝簪别汉家，赤松相候在烟霞。","如今悟得全身计，不似从前博浪沙。"]},{"t":"采莲曲二首 其一","f":"七言绝句","c":["吴姬日暮隔云歌，玉腕罗裙采芰荷。","画桨浮空看不见，娟娟微月照湖波。"]},{"t":"采莲曲二首 其二","f":"古风","c":["渡头凉月映罗衣，红藕香深暑气微。","忽见郎船过江去，一双鸂?背人飞。"]},{"t":"步虚词","f":"七言绝句","c":["绿章封事奏瑶京，侍女如花弄玉笙。","夜半朝元人上鹤，九天环佩月中声。"]},{"t":"寒塘曲","f":"七言绝句","c":["玉燕古钗堕寒水，曲塘无波深见底。","茨菰菱叶烂成泥，唯见芙蓉抱香死。"]},{"t":"秋闺","f":"七言绝句","c":["垂帘空见月昏黄，络纬啼来也断肠。","几度系书君不答，雁飞应不到辽阳。"]},{"t":"孤雁","f":"七言绝句","c":["钿弦声里自成行，无那分飞落楚霜。","前侣飘零何处在，青春作伴好还乡。"]},{"t":"挽僧","f":"七言绝句","c":["禅室焚香夜坐同，寺前新塔起悲风。","浮云自是同生灭，空使行人哭远公。"]},{"t":"秋山","f":"七言绝句","c":["绝顶风凄万木黄，露寒云白色苍苍。","夜深一片藤萝月，照见天河水气凉。"]},{"t":"秋江送别","f":"七言绝句","c":["江亭相送欲斜晖，黄叶西风动客衣。","惆怅孤帆今北去，数行白雁又南飞。"]},{"t":"梅花城闻角","f":"七言绝句","c":["何处金笳报五更，梅花零落满江城。","人家久住应惆怅，况是今朝在客情。"]},{"t":"秋色","f":"七言绝句","c":["清晓微茫带远鸿，晚随残照上丹枫。","莫将风笛频吹却，恐落乡园野树中。"]},{"t":"酒旗","f":"七言绝句","c":["半幅青帘柳外新，新丰市上几回春。","只今绿水红桥路，南北应稀买酒人。"]},{"t":"秋荷","f":"七言绝句","c":["西风一夜镜湖秋，零落残春逐水流。","犹有多情双翡翠，月明梦逐采莲舟。"]},{"t":"野塘翡翠","f":"七言绝句","c":["兰苕深处好相依，时向沙塘自在飞。","莫畏黄金收翠羽，吴王宫里美人稀。"]},{"t":"访僧不遇","f":"七言绝句","c":["寺门深闭对青山，何处浮杯更未还。","万壑千峰人不见，满林霜叶磬声閒。"]},{"t":"野花","f":"七言绝句","c":["引蔓离披覆绿苔，碧萝深处为谁开。","自怜冷落山林下，也向春风笑一回。"]},{"t":"芭蕉","f":"七言绝句","c":["叶卷花红色未乾，乳莺啼断雨声寒。","玉栏干畔宫帘侧，不似家林醉里看。"]},{"t":"闰九日赋","f":"七言绝句","c":["昨日龙山把酒杯，今朝还上最高台。","西风不待重吹帽，黄菊何因缓缓开。"]},{"t":"赋得草色寄同袍友人","f":"七言绝句","c":["色借罗衣绿更新，乐游原上几回春。","只今烟雨河桥路，愁对青青忆远人。"]},{"t":"江亭送别","f":"七言绝句","c":["绿杨江上把离杯，君去金陵几日回。","淮岸苍苍吴树远，相思应在凤凰台。"]},{"t":"蚕妇","f":"七言绝句","c":["粉黛无心鬓影凉，十年犹著旧衣裳。","东邻西舍迎鸾日，正是春风陌上桑。"]},{"t":"送人之京","f":"七言绝句","c":["送君南浦饮离觞，官柳青青野水香。","借问风帆何处落，秣陵城下树苍苍。"]},{"t":"江上闻篴","f":"七言绝句","c":["江上遥闻吹篴声，荻残枫冷最关情。","断肠况是凉州曲，何异山阳客里行。"]},{"t":"秋城闻雁","f":"七言绝句","c":["海国凉秋白雁声，行人一骑发边城。","故乡闻此肠堪断，况复今朝在客情。"]},{"t":"客舍闻捣衣","f":"古风","c":["山馆?啼碎客心，恶闻何处响孤砧。","数声惊觉还家梦，一夜挑灯忆故林。"]},{"t":"同友人寻梵宇","f":"七言绝句","c":["清溪一道出寒林，莲宇萧条野树深。","无数青山看不厌，白云芳草两同心。"]},{"t":"村居","f":"七言绝句","c":["枫林草屋半苍苔，寂寂柴扉映竹开。","啼鸟数声春自好，五陵年少不曾来。"]},{"t":"春山对酒","f":"七言绝句","c":["山顶春泉带雨香，数声啼鸟近壶觞。","遥怜曲水兰亭下，寥落风流野草长。"]},{"t":"新燕","f":"七言绝句","c":["海燕双飞下柳塘，主家台榭已荒凉。","玉窗绣户春云外，不忍翻飞过别墙。"]},{"t":"老僧","f":"七言绝句","c":["寺前萝径尽荒苔，懒向人间再渡杯。","阶下双松今百尺，青青曾是少年栽。"]},{"t":"游岩泉寺","f":"七言绝句","c":["野寺迢迢隐碧岑，曲栏荒殿古苔深。","可怜一段岩头水，洗尽浮生用世心。"]},{"t":"送人回京口军","f":"七言绝句","c":["扬子江头杨柳花，金山对面是京华。","行人归醉军城酒，北向青门正熟瓜。"]},{"t":"秋声","f":"七言绝句","c":["西风初起雁声微，千里关河叶尽飞。","借问凄凉何处落，五陵松柏远依依。"]},{"t":"翡翠","f":"七言绝句","c":["品流曾不让山鸡，珠树林深碧羽齐。","莫近梁王池上去，野烟寒雨草萋萋。"]},{"t":"赠闽山隐者","f":"七言绝句","c":["隐者閒门映竹溪，白云来往伴幽栖。","松花正熟山中酒，半亩黄精叶又齐。"]},{"t":"碧筒歌","f":"七言绝句","c":["试折青荷当玉觞，绿茎通处泻琼浆。","几回醉买西湖月，卧载莲舟梦亦香。"]},{"t":"郭干臣五马山房","f":"古风","c":["昨夜愁声落汉原，长陵金粟尽啼?。","谁家风木无穷思，五马山深独闭门。"]},{"t":"为高漫士题支离傲世图","f":"七言绝句","c":["南苑芳菲雨露新，空山寂寞独离尘。","也知樗散非时用，却倚云林冷笑春。"]},{"t":"渊明","f":"七言绝句","c":["带印何如漉酒閒，五株残柳旧乡关。","石头城下秋烟冷，正是东篱采菊还。"]},{"t":"题画马","f":"七言绝句","c":["逸思由来不受羁，长楸宫外草萋萋。","流沙路远空回首，宁向龙池影里嘶。"]},{"t":"海上送别林崇高先辈二首 其二","f":"七言绝句","c":["朝来候馆唱离歌，客里云山奈别何。","忽见陌头千树柳，青青那似故情多。"]},{"t":"登西石岩不与口占","f":"七言绝句","c":["狂客登山逸兴新，欲同清赏愧无因。","此身得似同林鸟，飞去飞来不属人。"]},{"t":"寄陈孟敷寓三衢","f":"七言绝句","c":["姑篾寒山色似苔，越城霜菊为谁开。","野藤洞口楼西月，付与何人照酒杯。"]},{"t":"次韵答林遵性","f":"七言绝句","c":["君去秋襟谁共开，客庭辜负菊花杯。","西风野水寒禽外，无那相思倚啸台。"]},{"t":"题茅斋霜月","f":"七言绝句","c":["猿断霜空烛影微，半林孤月掩荆扉。","五陵年少皆缨冕，何事寒山独布衣。"]},{"t":"野航风雨图","f":"七言绝句","c":["枫树萧萧野水西，楚天云雨正凄迷。","沧江欲暮风潮急，谁汎扁舟更出溪。"]},{"t":"林虚白画商山四皓","f":"七言绝句","c":["几年云卧得清閒，总被留侯误出山。","若使汉储非早计，绿萝青壁也何颜。"]},{"t":"为郑浮丘题花鸭","f":"七言绝句","c":["曲栏斗罢欲离群，还忆吹香几上闻。","积水天池非不到，野塘寒苇月纷纷。"]},{"t":"生色拒霜","f":"七言绝句","c":["綵毫将恨寄清酣，梦落西风濯锦潭。","却忆故园凉月曙，断英残粉湿秋衫。"]},{"t":"黄蜀葵","f":"七言绝句","c":["芳心曾为太阳倾，云叶离离玉露零。","想似茂陵仙梦远，柏梁秋雨洒金茎。"]},{"t":"题林良箴所藏文与可墨竹","f":"七言绝句","c":["兔鹘萧条墨影深，湖州真迹重千金。","梦回月冷閒堂曙，空翠濛濛上客簪。"]},{"t":"为高漫士题方壶效米小景","f":"七言绝句","c":["暮云春树意俱閒，鹤上瑶笙去不还。","梦觉屋梁残月曙，半帘空翠米家山。"]},{"t":"澹游雨竹","f":"七言绝句","c":["梦入零陵见旧丘，忽闻瑶瑟不胜愁。","觉来一片空山雨，散落潇湘万叶秋。"]},{"t":"林彦衡典教英山余以墨竹寄之因题于上","f":"七言绝句","c":["好是筼筜玉一枝，露寒金薤影离离。","泮林官冷闲看画，知尔家园落梦思。"]},{"t":"书云山小景","f":"七言绝句","c":["野杖閒行日未曛，商歌休思世人闻。","生平最是知心物，祗有青山共白云。"]},{"t":"题方壶清响生琳琅","f":"七言绝句","c":["壶丘仙客写琳琅，金薤临风片影凉。","夜半苍梧飞梦到，冷冷瑶瑟满潇湘。"]},{"t":"题王献之书展卷","f":"七言绝句","c":["练长谁涴墨淋漓，年少偏令太守知。","他日王孙求草圣，莫将疏懒傲当时。"]},{"t":"题陶靖节图","f":"七言绝句","c":["束带何须见督邮，宁辞五斗便归休。","秋风几度黄花酒，醉看飞鸿过石头。"]},{"t":"和靖观梅卷","f":"七言绝句","c":["门掩孤山少见人，梅花霜鹤自为邻。","秪今玛瑙坡头月，唯映巢居閤下尘。"]},{"t":"鹡鸰野棘","f":"七言绝句","c":["野棘荒原日又残，萧条孤影夜栖寒。","如今已遂连枝好，又恐分飞在急难。"]},{"t":"白头公","f":"七言绝句","c":["竹下棠梨花渐稀，白头相对语依依。","五陵年少多金弹，莫恋残春忘却飞。"]},{"t":"题董教沔阳王以义水墨扇头","f":"七言绝句","c":["暮云归鸟也知还，烟树苍茫楚望閒。","想是泮林官暇日，此心遥在五华山。"]},{"t":"为浮丘郑助教之子矿题山水扇头","f":"七言绝句","c":["桥门博士本忘机，柿叶房深隐翠微。","好是白云携不去，朝朝飞上老莱衣。"]},{"t":"书柯丹丘墨竹并古木幽篁 其一","f":"七言绝句","c":["凤箫吹断夜初澄，云叶离披玉露凝。","绝胜洞庭凉月曙，数声瑶瑟度零陵。"]},{"t":"书柯丹丘墨竹并古木幽篁 其二","f":"七言绝句","c":["孤根曾是老风烟，直节从教雨露偏。","忆得乐游原上路，汉陵千树也萧然。"]},{"t":"题扇头","f":"七言绝句","c":["醉逐吟鞭任去迟，夕阳前路更多岐。","上林春物仍堪赏，莫负秋风薜荔期。"]},{"t":"题画赠逸人","f":"古风","c":["潮水春深绿到门，半林残火独家村。","荷衣不醉长安月，只那乡山夜夜?。"]},{"t":"题高牧隐家藏西园雅集图","f":"七言绝句","c":["清朝戚畹尚风流，簪佩林泉结胜游。","转首西园摇落后，大梁佳气也成秋。"]},{"t":"题竹木翎毛","f":"七言绝句","c":["蜻蜓转逐断香飞，歌鸟残春听渐稀。","为报琅玕应结子，荒山秋晚凤凰饥。"]}]};